/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150306-3","meetingId":"h27-c-budget","date":"2015年3月6日","dateIso":"2015-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"提案","question":"おはようあります。２０７ページの紙おむつ支給、２１３ページの入院中の紙おむつ代の助成と、それから２１５ページの地域見守りネットワーク事業、それから２１７ページの重度訪問介護、それから２１３ページの仮称ふれあいステーションについて、お伺いいたします。","respondent":"永尾高齢者福祉課長","answer":"それを受けて、在宅のほうも今まで３,０００円だったところを５,０００円という金額に変更しております。それで、また在宅の方の紙おむつの支給の種類なのですけれども、今まで８種類だったのですが、今度は種類を多くしまして４４種類に変更しております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった、しっかりと必要とされる方に行き渡るような支援をこれからも引き続きやっていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今度の入院中の紙おむつにつきましては、区の事業として社会福祉協議会のほうに委託をするという形をとります。いずれにいたしましても、利用状況ですとか枚数、あと希望、そういうところも社会福祉協議会と連携しながら進めていきたいと考えています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"２１５ページの高齢者地域見守りネットワークについてお伺いします。平成２１年から行われている事業ですけれども、このたびの我が会派からの要望に、６年目から１０年目以降も５万円でお願いしたいということで、そういったことで予算も５万円ということになりました。","respondent":"大串福祉計画課長","answer":"まだまだこういった形で高齢者の数が増えていく中ではこういった活動が必要と認識しておりますので、今後ともＰＲ等々努めてこの見守りネットワークに協力をしていただける町会・自治会の皆様に数多く参加していただければと感じております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"重度訪問介護についてお伺いいたします。中には、障害の方もいらっしゃいますし、病気の方もいらっしゃったりとかいろいろな方がいらっしゃると思いますけれども、現在５０名ぐらいがこの制度を利用されているということですけれども、どういった方が利用されていらっしゃるのかお聞かせください。","respondent":"中山障害者福祉課長","answer":"実際には５０人ほどの方が利用されているのですけれども、中には難病の指定のあるＡＬＳの患者などもいらっしゃるところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"難病の方で大変苦しまれている方がいらっしゃるということで、品川区にお伺いしたところ、大体１日８時間程度で支援をされているということでした。","respondent":"中山障害者福祉課長","answer":"それで、今現在は障害支援区分程度４以上ということで、一律で規定をしているところではありますが、障害支援区分程度というのは４から上は６まですので、その方に応じてちょっと支給の見直しを今考えているところです。近隣区との関係です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。２０５ページ、生活困窮者自立支援事業、２１３ページ、仮称ふれあいステーション事業、２３１ページ、臨時福祉給付金、２５１ページ、子育て世帯臨時特例給付金、２３３ページ、仮称しながわネウボラネットワーク検討経費をお聞きしたいと思います。その上で、任意事業であります就労訓練事業、中間的就労等、一時生活支援事業についてはどうなっているのか教えてください。","respondent":"伊東生活福祉課長","answer":"それと、もう一つ、一時生活支援ですけれども、そちらに関してはこれは都区共同でやっております自立支援センターのほうで実施をしていくということで、同じように自立相談とあとは一時生活支援ということですので、衣食住の提供です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"それで、こちら、義務である自立相談支援事業についての相談窓口、これは再三確認させていただいていまして、生活福祉課のほうに設置ということで、過日の答弁では想定対象者が１,１００人というご答弁がたしかあったと思います。こことの連携ができないかどうかということもずっと提案しておりますけれども、この辺についてお考えをお聞かせください。","respondent":"伊東生活福祉課長、大串福祉計画課長","answer":"すみませんでした。就労準備支援事業につきましては、当区でも任意事業ということで実施していこうということで、すみません。就労訓練事業につきましては、区としては実施はいたしません。具体的には、こちらのステーションにコーディネーターをお２人つけてさまざまな相談、こういった窓口にしていこうと思っているところですので、委員ご指摘のようにそういった中での連携というのは十分可能だと考えておりますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"第三者に会話を聞こえにくくする、スピーチプライバシーシステムというものもありますけれども、そうした設置も考えたらいかがかと思いますけれども、いかがでしょうか。","respondent":"伊東生活福祉課長","answer":"現在の生活保護の相談に関しては、あのようなブースを設けておるところですけれども、同じように相談窓口としては設置をする予定ですが、ああいうブースがなかなかスペース上とれないというような状況もあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"今ちょっとそういった機械があるそうなのです。もしかしたら品川区はつけている場所があるのかどうかわかりませんが、もし参考までにご検討いただければと思います。次にいきます。２０１４年度の支給とは異なって、臨時福祉給付金と合わせて受給ができるということになっているそうであります。それぞれの給付金を合わせて受給すると想定される世帯は何世帯あるのでしょうか、教えてください。","respondent":"福島臨時給付金担当課長","answer":"それぞれ支給されるですけれども、実際問題、児童手当を支給していてなおかつ非課税世帯というようなデータはただいまのところ持ち合わせてございませんので、人数等はわかりません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"わからないということで、今後作業を進めていく中でその辺の対象者の照らし合わせ、照合というのでしょうか、照会というのでしょうか、できるのかと思いますけれども、これは課税額の決定時期が６月ごろだと思います。それぞれいろいろ相談体制の予算とかがくっついていますけれども、その辺も含めて教えてください。","respondent":"福島臨時給付金担当課長","answer":"合わせて支給される方への対応ですが、そもそも子育てのほうにつきましては児童手当の現況届、これを６月に行っておりますので、それとともに行う予定です。それとは別に臨時福祉のほうにつきましては、別途該当者には個別に送る予定ですので、漏れはないと考えております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"これについてはいろいろ工夫をまたお願いしたいと思います。これは補正予算でも取り上げさせていただいて、また昨年の予算特別委員会、また決算特別委員会でも、妊娠期から子育て期までの総合相談窓口の設置、母子保健コーディネーター、それから和光市の事例を紹介しながらネウボラの取組みを提案しました。そうしたことも含めて、現段階でどのようなネットワークの検討を考えているのか、教えてください。","respondent":"伊崎子育て支援課長","answer":"現段階での状況ですが、今現在さまざまなセクションで妊娠から子育ての期間のさまざまな支援をしております。そういったことを前提としつつ、品川のこの現況に合った形で、区民の方のニーズに対応できるような仕組みを作っていきたいと考えております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"もちろん施設そのものを品川区としても整備をしていただくというところが望まれるところではあるのですけれども、経過的な支援として、例えば近隣区でこうした整備されている産後ケアセンター、そこを利用したときの費用、そうした助成をする、こうしたソフト面での対応も検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"伊崎子育て支援課長","answer":"産後ケアもこのネウボラの事業の大きな１つのポイントです。品川区にはそういった機関も今なかなかございませんので、委員ご提案の内容も含めて検討とさせていただきたいと考えています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"最後、２４７ページの父親のための親育ちワークショップ、平成２７年度さらに１カ所拡大ということで、これも提案をしていただけに大変うれしいです。モデル事業で平成２６年度からやっていただいて平成２７年度３カ所となりますけれども、これまで取り組んできた成果、そして今後の平成２７年度ではさらにどういう思いで取り組まれるのか、教えてください。","respondent":"伊崎子育て支援課長","answer":"親育ちワークショップにつきましては、今年度２カ所でモデル実施をいたしました。そうしましたところ、多くの方に参加をいただき、参加いただいたお父さん方からご要望もいただいたところです。参加していただいた方の感想をお聞きしますと、やはり仲間づくりができたと。","voiceIndex":30,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"事業としては非常に小さな括りの一歩かもしれませんけれども、社会保障を支えていく、女性の輝く社会を支えていく私は大きな一歩だと思いますので、ぜひ今後も積極的に推進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"おはようあります。本日は、２１１ページの高齢者の趣味・健康づくり事業、そして２１５ページの高齢者外出習慣化事業、２１９ページの社会参加への支援、２３３ページの児童相談事業、２３９ページの事務所内保育推進助成事業について伺いたいと思います。最初に、２１１ページの高齢者の趣味・健康づくり事業について伺います。そしてまたどのような成果が得られたのか、あわせて伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"ただいま委員ご指摘がありました高齢者クラブの会員でなければ参加ができないのかというご質問もございましたが、全てのものにつきましては、やはり公募で、例えばシルバーダンスパーティーですとか、あるいは輪投げ大会ですとか。","voiceIndex":34,"id":"exchange-015"},{"speaker":"松永委員","kind":"意見","question":"グラウンドゴルフ大会が昨年第１回が開かれまして、かなりの人数が参加されたと思いますが、その中で、第１回ということで何名の方が参加されて、参加できなかった方もおられると思うのですけれども、把握している程度でいいのですけれども、何名ぐらいおられたのか。そして感想等ありましたらよろしくお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"グラウンドゴルフ大会の実績、それから感想ですけれども、グラウンドゴルフ大会を実施するに当たりましては、このグラウンドゴルフ協会の協力がなければ実施ができませんでした。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"関連して２１５ページの高齢者外出習慣化事業について伺います。そうした中で「食事処」事業については、シルバーセンター等区有施設３カ所でＮＰＯ法人等への運営委託により、月１回のペースで実施されているということで、この３カ所はどういったところでしょうか。月１回に何名の方が参加されているのか、お伺いしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"それでやはり調理場のある施設でなければこの事業というのが実施できませんので、これは南品川シルバーセンターと東品川シルバーセンター、それから新たに平成２５年の４月から大井林町の高齢者住宅の憩いの場を利用いたしまして、月１回開催をしてきてあります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"各期全６回行っていく予定ということですが、６回とも同じ場所でやられていくのか。対象者についてですが、６５歳以上の区民で本人１人で会場へ往復が可能な方２４名とありますけれども、これは１回ではなく前期６回毎回参加するという形になるのか、あわせて伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"この「食事処」の開催場所の拡大ということで、平成２７年度より後地商店連合会、この中でも親友会通り商店街のほうの個店を利用した形で実施するものですけれども、月１回ということではありますけれども。","voiceIndex":40,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"話は少し戻りますが、この事業目的に、引きこもりがちな高齢者に対しとありますけれども、今現在、品川区において引きこもりがちな高齢者はどのくらいおられるのでしょうか。あわせて、食事をしながら会話を楽しむために自分から話かけることは難しいと思いますが、私も知らない方に声をかけるということは難しいと思っていますので、その場の雰囲気というものを教えていただければと思います。","respondent":"白鳥高齢者いきがい課長","answer":"品川区内の先ほど具体的な６５歳以上の方の人口統計上の数字、７万８,０００人を超えているというお話もございました。","voiceIndex":42,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"２１９ページの障害者福祉費の社会参加への支援について１点だけ伺いたいと思いますが、品川区では、各町会・自治会で防災訓練やイベント行事が行われております。そこで、品川区としては、今度どのようにしてその不安を解消、取り除いたり、原因というのを突きとめていかれるのか、今後の対策を伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"それから一方で、地域の方にそういう障害を理解していただいて受けとめてもらうためには、理解促進をしていく必要があると思いますので、今回新しく障害者理解促進事業というのも設けておりますので、その両方を行うことで。","voiceIndex":44,"id":"exchange-020","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"最後に、２３９ページの事業所内保育推進助成事業について伺いたいと思います。プレス発表にもありましたが、平成２７年度には７０９人の受入拡大を予定し、また、平成２２年度から平成２６年度の５年間で２,９７９人を拡大したという実績を残しております。そこで、子ども・子育て支援新制度を活用して新事業の事業所内保育、地域枠の設置について伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"地域枠に関しましては国の基準が示され、昨年の第２回定例会の中で事業所内保育の条例を可決ご決定いただきまして、一定、大体４分の１程度なのですけれども、これまでの既存の事業所内保育施設ですと。","voiceIndex":46,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"この従業員枠と地域枠を１つにするということでありますが、そのメリット・デメリットについて伺いたいと思います。現在事業所内保育をされている企業は品川区には何社ぐらいあるのか、あわせて伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに、メリットとデメリットですが、メリットとしましては、品川区内、または区域外の方もいらっしゃいますけれども、昼間区民としてそれぞれの自治体でご活躍をされている事業所の従業員枠についても、一定国と区からの負担をお出しできるというところ。","voiceIndex":48,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"今後、企業との連携も大切となってくると思います。事業所内保育をされている企業は品川区に約６施設ということでありますが、今後新制度の事業所内保育事業に取り組む企業はありますでしょうか。品川区民の方が区外で新制度の事業所内保育を受け入れてもらう場合についてどのようになるのか、伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後この事業所内保育については、既に企業と連携をとりながらお話を進めているところもあります。","voiceIndex":50,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、介護保険について伺いたいと思います。４月から介護保険第６期が始まり、保険料も基準額で６００円の値上げ、そしてさらに制度改正で要支援１と２の方のサービスが介護保険給付から外されていくということになると思います。１５年度に移行するとしている自治体は２３区でどれぐらいあるのか、それがどこなのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今年度４月から移行する区は５区あります。","voiceIndex":53,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、新たな要支援１・２のサービスを、ヘルパーとデイサービスを地域支援事業に移行させていくということですが、これは認定を受けずにチェックリストで振り分けていくということも言われている制度ですけれども、このチェックリストは品川区は以前から活用されていますが、このチェックリストによってこの間どれくらいの方がサービスにいかれているのか。","respondent":"永尾高齢者福祉課長","answer":"４月から移行する区は、品川区、練馬区、千代田区、荒川区、江戸川区となっております。それで、チェックリストの関係ですけれども、現在想定しているのが約１,８００人程度を予定しております。","voiceIndex":55,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間のチェックリストでサービスを受けた方がどれぐらいいて、それでこれから１,８００人程度がチェックリストでサービスを受けていくということですので、今までの方がちょっとどれくらいなのかを伺いたいと思います。それから、この制度改正で３年間どれぐらい給付費が削減されるのか。そして、総合事業、地域支援事業に移行したほうの事業費はどれぐらいになるのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"これまでやっている二次予防対象者把握事業ですけれども、一応平成２５年度でいきますと、７５歳以上の高齢者の方に郵送をいたしまして、郵送で回答を回収している方法をとっております。","voiceIndex":57,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、今回の制度改正の中には、利用料の大幅引き上げもあると思います。収入で２８０万円、所得にすると１６０万円の人が２割負担になっていくということですけれども、これは対象となる人は品川区で何人、何％ぐらいになるのか。１年間で幾らぐらいになるのかお伺いいたします。","respondent":"永尾高齢者福祉課長","answer":"それで、人数でいきますと、約１万６,５００人ということになっております。それで、金額になりますと、平成２７年度でいきますと１億６,４３４万円程度です。","voiceIndex":59,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"それに伴って、給付費が減るわけですから、介護保険料も値下げをしている区、そして据え置きをした区というのが出てきていますけれども、品川区も十分にこれが介護保険料の引き下げができるぐらいの状況になっていくのではないかと思うのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ですので、給付費削減というよりは、給付費を適正化していくという考え方をとっておりまして、視点は利用している方を注視してサービスを行っていかなければいけないけれども、そのサービスを適正に行うための費用をきちんと把握し。","voiceIndex":61,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"新たな医療介護総合法で国が示すガイドラインの案では、新たな総合事業にすることで費用の効率化、すなわち介護給付費の抑制を図るように自治体に要求していくというものです。要支援者の介護給付費が、毎年五、六％伸びるものを三、四％に抑えていくと。それで、事業所の単価も２割、３割引き下げをしていくわけですけれども、そこからの引き下げ総額というのはどれぐらいになるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ご相談にいらっしゃって認定申請すれば、全員申請はお受けいたしますし、これまで逆に介護認定を受けていない方についても、チェックリストでケアマネジャーが状態をお聞きしながらきめ細かい配慮ができるという部分では、かえってサービスがよくなるのかと認識しております。","voiceIndex":63,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、単価の部分ですけれども、今までの介護報酬と比べてどれぐらいになっているのか。それで、デイサービス、ヘルパーがそれぞれどれだけ引き下げられるのかというのを、これを算定しないと介護保険料も決まってこないと思うのですが、そこをちょっとはっきり伺いたいのですけれども。","respondent":"永尾高齢者福祉課長","answer":"それ以降の年については、７５歳以上の高齢者の伸びをそこにかけていくというのが枠になっております。今回、品川区が４月に動かすということで、介護報酬自体は現在の介護報酬の上限でやっていきますので、来年度動かすよりは踏み台である枠は多くとれると認識しております。","voiceIndex":65,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"もともとの認定を受けさせない、減らしていくわけですから、十分なサービスも受けられないという状況がまたさらに大きく広がって続いていくと私は思います。この品川区には準備基金が、この間も質問しましたけれども、計画よりも大幅に増えていくという実態があるわけですから、保険料の値下げこそ、そして据え置きを今こそしていくべきと思いますけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それで、あと保険料の値下げのお話ですけれども、区といたしましてはやはり３年後というよりは１０年後のことを見据えた上で今回決定しているものですので、その動向だとか利用者のニーズもだんだん変わってくるところもありますので、この辺は慎重にやっていきます。","voiceIndex":67,"id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"２０９ページの法人に対する助成金で、まず５つの法人名が並んでいますが、その下に事業の助成があって、それ以外に各法人に対して事業の委託があると思うのですけれども、この法人への団体助成、事業助成、事業委託をどのように切り分けをしているのか、まず確認でお伺いしたいのと、それと法人の中に福栄会が入っていないのですけれども、これはなぜですかという確認です。","respondent":"中山障害者福祉課長、伊崎子育て支援課長、永尾高齢者福祉課長、白鳥高齢者いきがい課長、伊東生活福祉課長","answer":"２０９ページの法人に対する助成金のうち、品川総合福祉センターについてお答えいたします。これまでも、多世代交流ということでは児童センターにつきましてはシルバーセンターとの交流ということで。それと、あと福祉医療機構から設立当初にお借りしている部分の返還金について、区のほうで助成をしているです。自立支援事業の子ども家庭支援のお尋ねですけれども、こちらにつきましては生活保護受給者の中で子どもがいる家庭。","voiceIndex":70,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"１つだけ、利用ってすごくいいですね、もうそのままずばりで。最高が１,５００万円ですから。ただ、国ではないですから、地方自治として財政的にということがあるとは思うのですけれども、お金のことではなくして生活福祉課としてそういう家庭に対しての姿勢ですが、その辺、課長、どういう形でやっていこうと思っているのか、明確に答弁をお願いします。","respondent":"伊東生活福祉課長","answer":"確かにその貧困の連鎖ということを防ぐという意味で、この事業を始めたわけですけれども、やはり家庭の問題、学習環境、子どもが勉強するという意欲等を含めまして、なかなかそういうものを持てないような親の問題があったり、家庭状況によってですが。","voiceIndex":76,"id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"今までの確認ですけれども、この事業は平成２０年に始められて平成２４年には対象者を要介護３以上の６５歳以上の高齢者のいる世帯、２級以上の障害者のいる世帯であり、非課税世帯が１０割、課税世帯が９割の方に助成を拡大したこの経緯と、そして平成２６年、平成２７年と予算額を約２分の１としたそのわけなどを教えていただけたらお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"私から、高齢者の家具転倒防止対策の助成のお尋ねに対して、委員ご指摘のとおり、これまで平成２０年度から実施した助成事業であります。今回、要介護３以上の６５歳以上、または障害２級以上のいる世帯に拡大をさせていただきました。","voiceIndex":79,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"この対象者で個人的に結構つけられている方も、私もその１人なのですけれども、皆さんいらっしゃると思うのですが、ここで普及率というのはなかなか難しいと思うのですけれども、ここ数年かけてきたこの事業の進捗状況ということでは、多少普及率がわかったら教えていただきたいのが１つと、やはりひとり暮らしの高齢者の方に対してどのくらい進んでいるのかというのを私としては知りたいと思うのですが。","respondent":"白鳥高齢者いきがい課長","answer":"普及率の問題ですけれども、例えば防災フェアですとか、あるいは高齢者の多い、私の所管している高齢者クラブのほうにさまざまな機会を捉えて周知をしていますけれども、普及率につきましてはどの程度までかというのはちょっと把握してございません。","voiceIndex":81,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"平成２５年度の決特の総括で松澤委員から、震災時において自分が怪我をしないことが一番大切で、これが自助だと。そして、怪我をしなければ隣近所で助けを求める人を助けられる、これが共助だと、本当にそのとおりだと思います。そのことに関してどのように認識なさっていらっしゃるでしょうか。その辺お願いします。","respondent":"白鳥高齢者いきがい課長","answer":"それぞれお部屋の家具の状況にもよるのだろうと考えていますけれども、一般的に必要なＬ字型ですとか、あるいはポール式の器具ですとか、こういったものというのが中心となるのではないかと考えています。","voiceIndex":83,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"賃貸住宅のことなのですけれども、壁にねじ穴を開けるというタイプの器具が一番強度が高くて、ポール式より安全性が高いと聞いています。ただ、住宅の所有者の方の了解がなかなか得られないのではないか、難しいと思うのですけれども、この申込みに関しての賃貸住宅にお住いの方のお申込み状況といいますか、これにねじ式の器具の普及というのですか、その辺はどうなのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして、こちらで家主のほうの了解を得た中でもって取り付けをしていただいているというのが現状ですけれども、これまでこの家主の了解を取り付けてというよりも、個人の所有されているお宅でもって取り付けたケースのほうが多いかと思います。","voiceIndex":85,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。より安全性のあるものを取り付けていただきたいのです。ここで申込みの後の流れをちょっとお伺いしたいのですけれども、これはシルバー人材センターに委託というお話でした。位置を変える、ちょっとしたレイアウトを変えることでの安全性というのですか、それをご指導なさるということのお話なのですが、これはまた高齢者の方の見守りにつながっているのではないかと考えています。","respondent":"白鳥高齢者いきがい課長","answer":"やはり、家具転倒防止、大変大切な事業だということでシルバー人材センターのほうも認識しています。","voiceIndex":87,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう時間がないので、すみません、申告書なのですけれども、私ご相談を受けて、これがとても見にくいと。細かい字で高齢者を対象にしていらっしゃるので、もう少し工夫をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご答弁は、今年４月からは、当面は既存の民間事業者が行って、その後は社会福祉協議会やシルバー人材センターなど、さまざまな社会資源等と協議をし、概ね１年程度で持続可能なサービス体系を整えていくということでしたけれども、品川区は社会福祉協議会とかシルバー人材センター、確かにこれは強いイメージがありますが、社協というのは既存のさわやかサービスの有償ボランティアを指すのか。","respondent":"永尾高齢者福祉課長","answer":"すけっと品川養成事業ですけれども、方法としては平成２７年の秋ごろから開始の予定です。介護福祉専門学校の講師の方にお願いをして、基本的な権利擁護のことだとか情報管理のことだとかも含めた講座をやろうと考えているところです。","voiceIndex":91,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、２１３ページ、認知症の関係で今回さまざまやらせていただいたのですが、幾つか確認させてください。一般質問で国家戦略新オレンジプランの７つの柱に沿って質問いたしました。認知症対策の専門部署の設置を求めさせていただきましたが、この４月から高齢者福祉課内に保健医療・認知症対策係を新たに設置をして、認知症対策に力を入れていくというご答弁がありました。","respondent":"永尾高齢者福祉課長","answer":"それで、人数については３人の係を予定しています。新オレンジプランの関連ですけれども、品川区ではこれまでも認知症高齢者の対策というのは体系立ててやっております。","voiceIndex":93,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。認知症のことは本当にご相談が多いので、非常にありがたいと思っています。全部はやりませんけれども、この前の質問の中での徘回ＳＯＳネットワークシステムについては、現在大井地区で実施していますが、ご答弁ではさらなる拡充とエリアの拡大を検討するということでした。大井地区での実施状況、また今後具体的にどう拡充をされ、エリアを拡大されていくのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"大井第一、第二、第三地域を中心とした近隣の関係機関と連携をする方法ということで、捜索マニュアル等もつくっております。大井地区でやっておりますので、これからこういうやり方をほかの地区にも広げていくように検討しています。","voiceIndex":95,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"東京の標準モデルというのも拝見しましたけれども、ぜひ進めていっていただきたいと思います。９月中旬から１０月中旬にかけて開催されるアールブリュットｉｎしながわ水族館について質問します。あわせて水族館という魅惑的な空間を活かしての展示手法を求めたのですが、水族館へのアプローチなど区民公園の部分を活用するということでしたが、これはどういう意味なのか教えてください。","respondent":"中山障害者福祉課長","answer":"お尋ねのアールブリュット展に関する障害者団体の方たちへの周知です。今回、水族館の中の展示ルームのところに一角を設けさせていただいて、アールブリュット展を開催する予定です。","voiceIndex":97,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民の方から、障害者団体の方からも前回やったことを全然知らなかったというお声があったのでお話をさせていただきました。展示方法についてですけれども、本来であれば水族館の中、非常に幻惑的というか魅惑的な空間ですので、そこの活用をしていただきたかったのですけれども、これはなかなか難しいのでしょうか。","respondent":"中山障害者福祉課長","answer":"そちらにつきましては、実際には水族館の運営事業者とも相談をさせていただきながら、例えば水槽内でそういったものの展示が可能なのかどうか、そこは一部難しいところはあると思いますが、事業者と相談をさせていただければと考えています。","voiceIndex":99,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"国保が約９万２,０００人で協会けんぽ約６万人、合わせて約１５万人と。以前にも私、委員会で申し上げたことがあるのですが、もう２年以上前ですけれども、こういうデータヘルスに取り組むある博士の方からのお話を伺って、『ウォーリーを探せ』という絵本を例に挙げて説明していただきました。これ、実際の運用についてというのはいつごろになりそうなのか、教えてください。","respondent":"高森国保医療年金課長","answer":"データヘルス事業、策定をした上で支援ソフトというのを活用いたしまして、今委員ご指摘のようにさまざまな傾向のある方を抽出するという形になってまいりますけれども、これは一応今の予定では秋口ぐらいからスタートできるかと考えています。","voiceIndex":103,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと時間があるので、先ほど質問し忘れてしまったので、認知症のところで重ねて。以前に回想法というものの導入を求めさせていただいたのですが、これは歴史館と連携をして収蔵している生活用具、これを活用するという話でしたが、これの検討状況を教えてください。","respondent":"永尾高齢者福祉課長","answer":"回想法の有効性というのは認識しておりまして、各法人に対してもそのお話をしています。実際の実現については、もう少しお時間をいただきたいと思います。","voiceIndex":105,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"大まかな目安で結構なのですけれども、では、ちょっと質問を変えまして、どこにも入れなかったケースでは、補助や助成というのは何かあるのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"不承諾の方につきましては、例えば、今回は小規模保育事業のところも認可の中に入りましたので、品川区としては認証保育所の保護者の助成を行っているところです。","voiceIndex":112,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最終的に、２次募集でも保育園に入園できなかった親子には、次のような選択肢が考えられます。第２に他区の保育施設に入園させる、事業所内保育所を利用する。第４には、実の両親に子育てのために何度も上京してもらう。実施するにはかなりハードルも高いと思いますが、児童福祉法第２４条の精神を踏まえ、品川版子育て応援券の検討をぜひお願いしたいと思いますが、区のお考えはいかがでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、児童福祉法第２４条の保育実施についてお話しいただきましたが、今般、平成２７年４月から考えている子ども・子育て支援制度では、もちろん子育ての第一義的責任は保護者であるということを持ちながらも、家庭、地域。","voiceIndex":114,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いろいろご努力していることはわかりました。施設の補助ではなくて、入れなかった親子にどのように救いの手を差し伸べるかという救済の観点からご検討していただければ非常にありがたいと思います。次に、保育士養成についてお尋ねします。現在、品川区の認可保育園における保育士と保育士の資格を持たない職員の比率はどのぐらいなのでしょうか。大体のところで結構ですので、お示しください。","respondent":"竹田保育課長","answer":"保育士の資格を持つ職員と持たない職員の比率です。平成２６年度では、人材派遣、臨時職員等も含めまして全体で１,５０７人です。そのうち、資格を持っていないのが、概算で約４８０名程度です。","voiceIndex":116,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"３分の１ぐらいということですが、現在保育士が足りないことが問題になっております。それで要望なのですが、子育て支援の観点から、このような学校に保育士専門学校を併設することも考えていただけると非常にありがたいと思います。介護の専門家とともに、子育ての専門家の育成にぜひ区を挙げて取り組んでいただきたいと熱望しまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"私は２０７ページの品川介護福祉専門学校、２１１ページの福祉人材確保・定着事業の確認をします。福祉人材確保・定着事業からお伺いいたします。次に、品川介護福祉専門学校についてもお聞かせください。３点目に、外国人介護人材受入れに関してお伺いいたします。介護分野における外国人の受入れについて、現在の品川区のお考えと、受入れ数や出身国などの現状、今後の方向性をお伺いいたします。","respondent":"永尾高齢者福祉課長","answer":"外国人の採用ですけれども、在留期間というのが非常に問題になってくると思いますので、国の制度もにらみながら、外国人の受入れが可能であれば検討していきたいと考えております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと質問させていただきたいのですけれども、通信制というところで、社会福祉士のコースを行っているというのは、私も見させていただいたのですけれども、介護福祉士のほうでの通信制の活用は今後考えていらっしゃるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、もう既に在留期間が３年以上ある方については、実際介護福祉専門学校に入学している方もいらっしゃいますので、外国人、日本人に関係なく、制度上可能であれば、受け入れていきたいと考えています。","voiceIndex":122,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"国の動向を見ながら、人材をどんどん活かしていただけるようなサポートをお願いしたいと思います。なお、既に一面的なネガティブなイメージがありますから、福祉の仕事、介護職の魅力を打ち出すためには、事業者単位での取組みに加えて、品川区として区内の事業者と情報共有・連携をしながら、イメージアップを強力に推進する必要があると考えますが、区のお考えをお伺いいたします。","respondent":"永尾高齢者福祉課長","answer":"法人同士の懇談会等も実施しておりますので、そういう中で、お互いがどういう発信の仕方でプラス面を引き出せるかということも相談しながら、一つにまとまって、そのあたりのＰＲをしていきたいと考えております。","voiceIndex":124,"id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろなイメージアップ、例えば、芸能人とか、有名人で介護のお仕事に興味がある方をお呼びして、何かイベントを開催する等、イメージアップの効果を狙ったようなことを品川区主導で、ほかの事業者の方々と連携して行っていただきたいと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-054"},{"speaker":"向委員","kind":"質問","question":"詳しい経費の内訳ということで、おそらく企画運営業務委託費が３００万円弱、それと別にアートディレクター経費ということで１１６万円になっていると思うのですけれども、来年度本格的に実施するに当たって、アートディレクターの方が担う役割、人数が１人なのか複数なのか、どういった専門家、福祉関係が主なのか、それとも実際の芸術家の方なのか、そこをまず教えてください。","respondent":"中山障害者福祉課長","answer":"この方は、国のアール・ブリュットの審査会の審査員もやっていらっしゃる方ですので、役割といたしましては、区のそれぞれの日中活動の場に行っていただき、絵の引き出し、あるいは区内の障害者の方のアール・ブリュット作家を引き出すような発掘をやっていただく予定でおります。","voiceIndex":128,"id":"exchange-055"},{"speaker":"向委員","kind":"質問・要望","question":"去年、厚生委員会でも北海道の「ともに」というところへ視察してきました。障害者の方がつくったものは一つ一つが大切な作品ということで、ディレクターの方は、著作権についてもきちんとした知識はあるとは思うのですけれども、そのあたりを確認させていただきたいのと、実際展示される作品の所有権は福祉施設になるのか、それともご本人に帰属するものなのか、そこら辺の考えもあわせてお願いします。","respondent":"中山障害者福祉課長","answer":"実際の作品を福祉現場の著作にするのか、ご本人の著作にするのかというところは、今後の課題になってくるとは思いますが、できるだけその方の描いたものが製品化されて、その方の工賃として入るような仕組みを全体で考えていければと思っているところです。","voiceIndex":130,"id":"exchange-056"},{"speaker":"向委員","kind":"質問・要望","question":"作者ご本人の著作権をしっかり大切に守られるということと、家族ももちろんそうなのですけれども、福祉施設の職員の方々の中には、成年後見といった方とも関わることになってくると思うので、そのあたりの方々への普及啓発というのは、弁護士とか、法律の専門家も含めて、本当に丁寧にしっかりと行っていただきたいと思いますので、そのあたりのお考えもちょっとお伺いしておきたいと思います。","respondent":"中山障害者福祉課長","answer":"ご本人の作品に対する思いと、一方で著作権という権利のところは非常に難しい問題があると思います。","voiceIndex":132,"id":"exchange-057"},{"speaker":"向委員","kind":"質問","question":"わかりました。少し時間があるので、あわせて、４５３ページの国保の医療費通知事務のところで、以前、私がお願いしていた、今まで年に１回世帯主にまとめて医療費の通知が来ていたのですが、今度から１８歳以上にということで伺いました。１８歳という年齢の設定になった考えをお伺いしておきたいと思います。","respondent":"中山障害者福祉課長、高森国保医療年金課長","answer":"ただ、委員会があるので、そちらは欠席させていただいたのですが、まず私どもも勉強させていただいて、障害者の方の権利がきちんと守られるように、そしてより良い作品を世に出せるように努力していきたいと考えています。１８歳という年齢のお話ですが、私どもも１６歳がいいのか、１８歳がいいのか、あとは２０歳がいいのか、いろいろと検討してきたわけですけれども、他区の状況を見まして、今回は１８歳以上と決めさせていただいている状況です。","voiceIndex":134,"id":"exchange-058"},{"speaker":"向委員","kind":"質問・要望","question":"著作権については、熱い思いを抱いてくださっているということがよくわかりました。ぜひお願いしたいと思います。医療費通知のほうは、もう少し若いほうと２０歳になった場合といろいろ私も考えてみたのですけれども、家族のあり方が本当に変わってきて、ただ、国の枠組みなどでどうしようもないところがある中で、本当に１８歳と決断していただいて、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"私からは、２３７ページの障害児施設給付費に関連してと、同じく２３７ページの児童保育委託にかかわるところで、保育士のことについてお伺いしたいと思います。初めに、事業を始めるに当たっての背景、なぜこういう事業を始めようとしたのかということと、また現在区内には児童発達支援事業所に当たるものが存在するのかどうか、この２つについてお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"そこで、医療的ケアの必要なお子さんの行き場がどうしても少なくなっておりますので、このたび看護職を配置する事業所に対して、そこの一定の人件費を補助することで、医療対応のできる児童発達支援所の誘致をしたいということで、設けたところです。","voiceIndex":139,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、品川区には児童発達支援事業所に当たるものは３カ所あるとお伺いいたしました。今回の事業では、新たに事業を開設するに当たって、医療的ケアの人材派遣について助成していくという形かと理解しているのですけれども、既存の事業所がこれを利用するということについては、どのようなお考えなのかお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"現在３カ所ある児童発達支援事業所に配置して、実際に医療的ケアをするのは難しいと考えております。医療的ケアになりますので、訪問看護ステーションを持っているとか、医療系の事業所のほうが望ましいかと思っているところです。","voiceIndex":141,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えば、最初は保育士とご両親、保護者との間でのいろいろなやりとりから、なかなかそこではうまく解決できないといった場合に、１つは園にいくと、園の中でどうしようかと、トラブルを共有して、それでもだめな場合はさらに、区の中で何かそれをきちっとフォローするような体制が必要になってくるのではないかと思うのですけれども、現在どのようになっているのかということと。","respondent":"竹田保育課長","answer":"それで、保育士につきましては、保護者に適切な説明ができるように日々研修をするとともに、職層ごとに担当者、園長等、副園長等、来年度は特に力を入れて年６回ほど研修を予定しております。","voiceIndex":143,"id":"exchange-062"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、発表のずれによって、不承諾になってしまって、保護者が認証保育所に申込みをされようとするときに、品川区は２月中旬まで１次の発表がないものですから、どうも目黒区の方々が認証保育所に先に入られてしまうという話を何回か聞いたことがあるのです。こういったことについて、どのような状況を把握されているかお伺いしたいと思います。","respondent":"竹田保育課長","answer":"それで、認証保育所との関係なのですが、認証保育所はそれぞれ申込み期限を別途定めて、個別にお決めになられていると思いますので、場合によっては、私どもの発表よりも前に締め切りがあった場合は、そういうことも起こり得るのではないかと考えています。","voiceIndex":145,"id":"exchange-063"},{"speaker":"渡部委員","kind":"意見","question":"２４５ページの児童センター運営費で聞いていきます。平成２６年度の予算で、中高生ボランティア活動の支援というのが入っているのですけれども、今年の予算書はこの１行が全く消えているのです。事業がどこかに統合されたのか、全く止めてしまうのか、まずこれ自体の説明をお聞かせください。","respondent":"伊崎子育て支援課長","answer":"スポーツごみ拾いは既に２回実施しておりまして、来年度につきましては、イベントを通して培ってきたものを、今度は各館の日常の児童センター活動の中でどのように活かしていくかというところに立ち戻ろうということで、今年度はイベントの経費計上はいたしておりません。","voiceIndex":148,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。それでスポーツごみ拾いが事務事業概要のほうにも出ていまして、そのようなものに出ていただいた方が、果たしてその後児童センターに戻って、ボランティアとして活動いただいているのかどうか、いただけるのかどうか、その辺を教えてください。","respondent":"伊崎子育て支援課長","answer":"スポーツごみ拾いをしてくださった方たちにつきましては、その後アンケートをとらせていただきました。正確な数は記憶していないのですが、何割かの方はボランティアに対する意識が高まったということでご回答いただいております。","voiceIndex":150,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"機材の運搬とか、セット、インフルエンザでお休みになってしまったという子がいたら、代わりで入ってくださるのを見ていて、これはいいと本当に思いますし、続けていってほしい。区の行事ですから、決して外に思いきり発信していることではないと思いますけれども、これを発信したら品川区の児童センターはすごいことをやっていると思っているのですが、その辺、ひとつご答弁をお願いします。","respondent":"伊崎子育て支援課長","answer":"ボランティアにつきましては、今、小学生からバンドが育っておりますので、その方たちが卒業するに当たって、児童センターの活動を支援するような形で、職員の育成にも努めているところです。","voiceIndex":152,"id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"今６館、これが８館、いわゆるティーンズ館全部になっても構わないと思うのですけれども、それがそれぞれ盛り下がることなく、盛り上がっていくというのですか、事業を継続できるような仕組みにしていただきたいと思います。どうやって職員の方と中高生、大学生を含めた協力を仰いでいくかというところだと思いますので、そこは本当にくれぐれもお願いしたいのですが、もう一声いただけますでしょうか。","respondent":"伊崎子育て支援課長","answer":"子どもたちはバンド活動を通して、いろいろな力を培っていきます。そういったことを継承していけるように、職員の研修等もこれから充実させていき、技術はきちっと継承して、子どもたちを育てていきたいと考えております。","voiceIndex":154,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。今までの歴史があってここまでになっているものです。子どもたちがまた育ってもらって、次の世代につないでいっていただきたい。こういう活動をやっているところは滅多にないわけですから、本当に一つの活動を通して、子どもの居場所をつくるためにも必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２３２ページからの児童福祉費、待機児童対策についてお伺いいたします。いきなり数字なのですが、前回の鈴木ひろ子委員の質問のときの一次審査の不承諾通知１,２５６人の年齢別の内訳を教えていただきたいのと、１,２５６人も精査していくとだんだん減っていくという説明があったのですが、大体どのくらいの人数になるのか教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"申し上げましたとおり、０歳から２歳が１,０８６人、３歳から５歳が１７０人ということで答弁申し上げました。それから、１,２５６人の内訳です。現在、第２次審査に向けて精査している最中ですので、手元に細かい精査の数は持ち合わせておりません。","voiceIndex":158,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"年齢別のところはわかった段階で教えていただきたいと思います。計画上も３年間で量が足りない。計画上、平成３０年までは待機児ゼロにはなっていないということなので、このことへの認識をまず１点お伺いしたいのと、さまざまなデータがあるのですが、人口推計の中に、マンション建設増による人口増が入っていないのではないか、この点を加味していく必要があると思うのですが、それが１点です。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１号、２号につきましては、２号の説明にもあるのですけれども、２号認定で保育が必要な方も、品川区は私立幼稚園の預かり保育を充実しておりますので、中にはこの調査とは違って、実質は１号の中に教育機関の中に３００人程度現状でもいらっしゃいますので。","voiceIndex":160,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、０歳の給食がなくて、お弁当というのは、本当に大変な事態だと思っています。この最低を守らなければいけないと思いますので、ぜひ認可保育園を増設の柱に据えて、格差をつくらないこと、そして、認可外保育施設の認可化も含めた認可保育園の増設、私たちは計算して、２０園増設を求めたいと思います。この点も含めて、ぜひ前に進めていただきたいと思いますが、いかがでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"認可外保育施設につきましては、歳入のところでもご説明しましたとおり、例えば、小さい事業でしたら区の認可事業に、そして認証などの認可外の場合は認可へ、それぞれの事業規模に応じて、認可外の移行支援経費は、昨年度から予算に計上しています。","voiceIndex":162,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可外保育施設の１０万円の保育料の補助のお願いをしたのと、なぜ区立でつくらないのか、この点もぜひ答えていただきたいと思います、後でいいです。昨年は不承諾通知を精査して８７０人、区の発表の待機児童は１２８人でした。４月に入園できなかった場合、４月１０日までに再度申込みをしないと、待機児にカウントされない。この問題は事実なのか、お伺いします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"最後に４月１０日に翌年度以降の入所申込みをまたお願いする予定です。","voiceIndex":164,"id":"exchange-072"},{"speaker":"井上委員","kind":"質問・要望","question":"その前に、２０５ページの生活困窮者自立支援の相談窓口の質問が先ほどありましたけれども、これについてプライバシーが守られていないと思うと、次から相談には行かなくなると思いますので、もう少し切迫した状況を理解していただいて、プライバシー保護ができるようなレイアウトに、できる限りではなく、ここは最低限必要なところだと思いますので。","respondent":"中山障害者福祉課長","answer":"そういった中から、全てのケースを認めるというわけではなく、個々の事情を勘案させていただいて、相談の上、支給決定をして、認めていきたいと考えているところです。事業者の説明会ですが、３月１６日に予定しておりまして、一応３０者近く呼ぶ予定になっております。","voiceIndex":167,"id":"exchange-073"},{"speaker":"井上委員","kind":"質問・要望","question":"いろいろな背景はわかりました。それで、利用者となる方に直接意見はまだ聞いていないということでしたけれども、建設的な対話ができる場をぜひつくっていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"特に小学校のお子さんについては、今まで移動支援を一切認めてきておりませんので、全くの新規ということになります。ここについては、日々の療育相談の中からお声を拾いながら、あるいは特別支援学校との関係から、声を拾っていければと思っているところです。","voiceIndex":169,"id":"exchange-074"},{"speaker":"井上委員","kind":"質問","question":"よろしくお願いしたいと思います。次は、障害者の介護人派遣を受けている方々の６５歳介護保険優先適用についてお伺いしたいと思います。このことについて、厚生労働省からは自治体に向けて、一律ではなく、個々の状態に合わせて判断をするようにという通知が二度にわたって来ているかと思うのですけれども、その状況についてお教えください。","respondent":"中山障害者福祉課長","answer":"いずれにしても、個々のケースによって違いますので、そこはご相談の中で、高齢期に向けてのスムーズな移行ができるよう、高齢者福祉課とも連携してまいります。","voiceIndex":171,"id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで個々の対応というのが、なかなか利用者としては弱い立場であるので、そこはしっかりと保証していただきたいと思うのですけれども、柔軟な対応をしてくださるということであっても、不服申立てとか、相談窓口の体制が必要かと思います。これは今、区では現状どのようになっていますか。","respondent":"中山障害者福祉課長","answer":"不服申立てということですが、この障害福祉サービスを受けるに当たって、制度の活用ということになりますので、もし何かございましたら、区にご相談いただければと考えています。","voiceIndex":173,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問","question":"次は、児童センターの運営の中で、児童センター事業の施設運営委託費２億２,４００万円の内容をお伺いしたいということが１つと、２０１５年の新学期のすまいるスクール登録に合わせて保護者の方に、すまいるスクールは地域の児童センターと組織統合しますというお知らせが出されているかと思いますけれども、この組織統合というのは具体的にはどのような内容が書かれているのか教えてください。","respondent":"伊崎子育て支援課長","answer":"目的としましては、保護者の教育支援活動を含め、地域に根差した児童の健全育成を一体的に実施するということで、参加に当たっての手続や運営方法、利用方法、職員配置などは変更ございませんということ。","voiceIndex":175,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"委託館が１２館になっているというところで、保護者の方から契約変更などがあったときに、そこのスタッフがそっくり変わってしまうということについて、子どもたちがすごく残念がっているということなので、きめの細かい子育ち支援ということを児童センターは主に担っていくべき、学校とは違ったすごく重要な役割、位置づけが必要だと思うのですけれども。","respondent":"伊崎子育て支援課長","answer":"子どもたちに影響がないように、こちらも館長を通して努力してまいります。","voiceIndex":179,"id":"exchange-078"},{"speaker":"渡辺委員","kind":"確認","question":"お願いします。２１３ページ、認知症高齢者の支援とケアの充実の点で伺ってまいります。先だってまとめられた第６期品川区介護保険事業計画等の中でも、認知症高齢者の支援は拡充ということで、かなり整備されて、重点項目といえるかどうかあれですが、それぞれの項目があります。２年前に本会議の質問で伺ったときにも、品川区はモデル事業を含めて、かなり先行されて取り組まれている。","respondent":"永尾高齢者福祉課長","answer":"国で言われている推計のパーセントを掛け合わせてみると、国では高齢者の約１３％がＭＣＩという統計があると伺っておりまして、その数字で出しますと、約１万３００人がＭＣＩではないかと想定されているところです。","voiceIndex":182,"id":"exchange-079"},{"speaker":"渡辺委員","kind":"質問","question":"この辺の品川区の進捗状況、医師会等との連携等あるかと思いますが、今現在の状況、新オレンジプランとの兼ね合いで、品川区ではどの程度の規模を考えられているのかを１つ伺いたい。もう一つが認知症疾患医療センター、地域型で全市町村の数、目標値がありましたが、品川区ではどの程度の規模、全区的に１カ所なのか、あるいはもうちょっとエリアごとに考えられているのか、その辺も教えてください。","respondent":"永尾高齢者福祉課長","answer":"認知症の方を早期に発見して、専門医につなげるというのは非常に重要で、品川区でも昨年度から早期発見・早期診断事業というのを開始しておりまして、実績としても、平成２５年９月から今年１月にかけて３５人の方が。","voiceIndex":184,"id":"exchange-080"},{"speaker":"渡辺委員","kind":"質問・要望","question":"診療所型の必要性はもちろんなくては大変ですから、診療所型が増えることと同時に、この地域型を東京都との兼ね合い、あるいは民間との連携も含めて誘致するぐらいの形も必要かと思うので、そのお考えが１つ。その中で、認知症サポーターは第１次オレンジプランからあったと思いますが、直近の人数、またどのように増えているのかを教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"先ほど説明するのを忘れましたけれども、認知症地域支援推進員ですが、認知症疾患医療センターや医療機関、介護サービス、地域のいろいろな支援をさまざまな機関につなぐコーディネーターという役割を持っております。","voiceIndex":186,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からはまず２１３ページのひとり暮らし高齢者等福祉費、２点目が２１５ページの高齢者住宅対策事業です。もう一つが、ひとり暮らし高齢者等福祉は、安否確認の事業ですけれども、こちらも事業の現状と課題をお聞きしたいのですけれども、ひとり暮らしの高齢者が生活上困っていることで、安否確認でさまざまな事業をしていらっしゃいますが、その事業の現状と課題をどのように捉えていらっしゃるか。","respondent":"白鳥高齢者いきがい課長、永尾高齢者福祉課長","answer":"したがいまして、ここの高齢者住宅に入れない方が大体住宅あっ旋に流れる傾向にあるのですけれども、そういうご案内をしていますけれども、今のところ非常に少ない傾向にあるという認識です。課題としては、そういう部分につながらない方について、どういうふうにしていくかというところになろうかと考えています。","voiceIndex":189,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問","question":"その点いかがでしょうか。そうした方のために、目で、視覚で見られるようなものとか、聴覚障害の方がよく電気がつくようなものとか、そういうもので対応されている、高齢者の方で補聴器まではいかないけれども、でもかなりお耳が遠くなってしまっている方の、こうした生活に支障を来している課題に対して、どのような対策をとられていますでしょうか。どのように考えられますでしょうか。","respondent":"白鳥高齢者いきがい課長、永尾高齢者福祉課長","answer":"こちらにつきましても、やはりご本人の希望条件にかなうような申込みをしていただいているところですけれども、その中で広さですとか設備、あるいは家賃ですとか地域性。それで、現状ではそういう方に対応するようなものというのは、事業としてはないのですけれども、どのような製品があるのかとか、どのようなニーズがあるのか、そういうところを注意しながら考えていく必要があるかと考えています。","voiceIndex":192,"id":"exchange-083","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"質問・要望","question":"そういうところがどうかというのは、今後またこういったところも声を上げていきたいと思います。もう一つのほうは、ぜひニーズを、調査というか見ていただきたい。ぜひ民生委員の方々からもそういったお声をお聞きしながら、ニーズ調査とかそういったところも含めて、生活での支障を来しているところの手当を、ぜひ考えていただきたいと要望いたします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、そのうちの１カ所で、現場の職員、法人の職員が非常に熱心にされていたのですけれども、いろいろしつこくお話を伺っていると、実はトップの方がとても消極的なので、有休を取って手弁当でやっているのだというお話を伺って、ぜひ少なくとも品川区に関わるような法人の方々には、認知症やその啓発に対する意識をぜひ、上からといいますか。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長、伊崎子育て支援課長","answer":"それで幾つかの法人がやっておりますけれども、法人全部で取り組んでいるところもあれば、現場サイドのところもありますので、今後。出展者につきましては、こちらの障害者福祉課のほうで何か努力ができるかどうか、それは検討します。ですので、まず品川区の中でどういったやり方がいいのかということを、来年検討していきたいと考えています。","voiceIndex":197,"id":"exchange-085"},{"speaker":"あべ委員","kind":"質問","question":"非常に少ない数字で、特に０歳から２歳が少ない。小規模の中では、０歳の定員を１歳、２歳に振り分けていたということもあり、そしてまた申込者の、私が知る限りでは、育休を短縮して０歳のうちに申し込んでいる方が非常に多いという現状を考えると、やはり０歳、１歳、２歳の特にこの部分の定員を、より大胆に見直していく必要があるのではないかと思いますが、ご所見を伺います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"４点のご質問をいただきました。０歳、１歳、２歳のところですが、やはり今、１歳、２歳の枠でなかなか入れないから、０歳から預けたいということの対応としまして、品川区としても育休明け入園予約制度で、こちらのほうは一定対応しています。","voiceIndex":204,"id":"exchange-086"},{"speaker":"あべ委員","kind":"質問","question":"シッター助成に関しては国の制度もあるということで、そうするとそれを利用して何とか就労を継続されている方にポイントをつけるという発想はあり得ますでしょうか。それから事業所内保育につきましては、今、事業所内にあるところ以外への働きかけというつもりで伺いましたので、ご答弁をいただければと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それから事業所内保育につきましては、今後ものづくり・経営支援課が進めている事業所内の託児スペースの助成などもありますので、どのような企業に働きかけていくか改めて研究して、こちらは積極的に進めていきたいと考えております。","voiceIndex":206,"id":"exchange-087"},{"speaker":"あべ委員","kind":"質問・要望","question":"残り１分となりましたので、少し聞きたかったことをはしょって申し上げていきたいと思います。ひとり親家庭、今回の川崎市の事件などもありましたけれども、やはりひとり親の家庭というのは、一定の家計を維持するためにどうしても長時間労働にならざるを得ないという実態があります。ぜひ品川区内でも、ひとり親家庭の労働時間の状況を実態把握していただきたいと、これはお願いにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-088"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に成年後見制度です。それから保育の関係です。病気を持ったお子さんでした。どうしたらいいのでしょうかということを何回も確認していただいたのですが、やはり「検討していく」というお話をいただいた段階で、まだ入れるのではないかということをいろいろずっと考えて、保育士のところにもご相談に行ったということなのですが、最終的には今年の２月、不承諾ということで出てしまいました。","respondent":"大串福祉計画課長、竹田保育課長","answer":"そうした中で、先ごろ区内にある信用金庫の皆様で一般社団法人をつくっていただいて、市民後見活動をやっていただくといったところで、いろいろな形、さまざまな担い手をこういった形で。ただ、医学の発達とともに特別支援が必要なお子さんというのが、今後増えていくことも予想されますので、医療的処置が必要なお子さんや、あるいは集団保育が難しいお子さんの保護者に対する就労支援については。","voiceIndex":210,"id":"exchange-089"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"保育の関係で、今のお答えはすごくよくわかるのですけれど、やはり親としては集団の中で育てていきたいと、そういう思いもあって、医師の面談というのはたしか最後のほうでしたか、１月ぐらいですか、面談しているのは。だからもっと早くにその辺で対応して、個別のケースで対応できないのかというのは、ちょっと私は思いました。後見制度はＮＰＯ団体がついて、この前１０周年の式典がありました。","respondent":"竹田保育課長、大串福祉計画課長","answer":"その言葉でどれだけ保護者の方に伝わったのかというのが課題なのですけれども、今後はよりご理解いただけるような説明の仕方を工夫してまいりたいと思います。集団保育です。やはり社協だけで担うということは難しいというところで、そうした中で市民後見人の養成講座、先ほど申し上げましたけれども、そういったものを開催、もしくはご案内があったように困難ケースについては社協本体で。","voiceIndex":213,"id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"後見制度は社協の事業ですから、区からどこまで言えるかというのもあるのですけれど、うまく調整していただきたいと思います。保育のほう、ご説明もたくさんしていただいたというのは、十分了解しています。","respondent":"竹田保育課長","answer":"大井保育園につきましては、施設の中でも古いほうの部類ですが、区全体では長寿命化ということで、より有効に使えるようにということで研究しています。大井保育園も適切に対応していきたいと考えております。","voiceIndex":216,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"これで変更になったメリット、デメリットをお伺いします。それから、この利用実態はどうなっているのでしょうか。今のニーズ調査ではなくて、現在すまいるスクールを利用されている保護者の方々の実態は、どのようにつかんでいるのでしょうか。それと職員です。それで最大利用できる時間というのがあると思うのですが、それは今どういう状況になっているでしょうか。その考え方を教えてください。","respondent":"伊崎子育て支援課長、竹田保育課長、今井制度改革・待機児童対策担当課長","answer":"すまいるスクールの組織の変更のメリットですけれども、このたび来年度、児童センターと一体化をしていくということもあります。それから利用の理由ですが、近年では１番がリフレッシュ、２番が通院・出産、３番が学校行事等、４番が仕事ということで。最後に、子ども・子育て支援制度では確認という制度がございまして、これは市町村が実施主体となりまして、認可保育施設だけではなく小規模や家庭的保育も。","voiceIndex":219,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"それから職員の問題で、すまいるスクールと児童センターのほうですが、保育士ということですけれども、保育士が足りない、足りないと言っている中で、児童センターのほうに人が行くのですか。そこは共有化はできないはずです。だから、児童センターは児童センターで新規採用をしっかりしていただいて、ノウハウをきっちりとつけていただきたい、そのお考えをお聞きします。","respondent":"竹田保育課長、堀越人事課長","answer":"オアシスルームですが、そもそもスタートした目的といいますか考え方は、在宅子育てを支援するということで、リフレッシュや通院等をカバーしていくというような考え方でつくった事業です。今、委員のお言葉にありましたけれども、児童センターとの一体化等ありますので、いろいろな研修等も含めて人材育成に努めてまいります。","voiceIndex":223,"id":"exchange-093"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは２０７ページの事業助成の中のほっとサロンについて、もう一つは２２３ページの南品川シルバーセンターの浴室設置工事についてお伺いします。初めに、ほっとサロンのことでお伺いしたいと思います。その３カ所、荏原、西大井、南品川とありますが、この内訳を教えていただきたいということと、実際この３カ所に登録されている数はどのぐらいあるのか。","respondent":"大串福祉計画課長","answer":"それから登録者の内訳ですが、人数ということでは申し訳ございません、ちょっと把握しておりません。全部でサロンとしては１５カ所、４５サロン、これがサロン活動をやっているといったところまでは把握しています。","voiceIndex":227,"id":"exchange-094"},{"speaker":"山元委員","kind":"質問・要望","question":"そうすると、最初からスタートして何年か経っていると思いますけれども、グループが途中でやめたとか、やめないとか、その辺もわからないですか、わかりますか。もしわかるのであれば教えていただきたいし、そのやめられた理由、メンバーだった方たちのフォローというのはどういうふうなことなのか、もしわかれば教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"そのサロン活動をやめられた方のフォローということですか。すみません、２番目の質問がちょっとよくわからなかったのですが。","voiceIndex":229,"id":"exchange-095"},{"speaker":"山元委員","kind":"質問・要望","question":"今、１万４千何百人の方が参加されたということでありましたけれども、このサロンはずっと続けていらっしゃるところもあれば、いろいろな理由があってやめられたところもあるかもしれない。そうであるならば、参加していたのにできなくなってしまった方がいるわけですから、その辺のフォローというのをもしされているのであれば、教えていただきたいと、そういう質問です。","respondent":"大串福祉計画課長","answer":"すみません、サロン活動を中止された方に対してのフォローというところまでは、こちらのほうは今現在やっていないといったところです。申し訳ございません。","voiceIndex":231,"id":"exchange-096"},{"speaker":"山元委員","kind":"質問","question":"たくさんの方が、このほっとサロンを利用しているということがよくわかりました。やはり長い間やっていると、お話、おしゃべりだけでは済まなかったり、壁にぶつかるときがあると。できれば、別にテレビを設置しろとは言いませんが、今はとても薄型のテレビがありますので、そこの部屋に持っていけるような、そういう助成といいますか、そういうのはその中から支出できますでしょうか。いかがでしょうか。","respondent":"大串福祉計画課長","answer":"ほっとサロンにつきましては、運営助成ということでいろいろ助成をしています。今、ご要望がありましたテレビの設置といったお話をいただきましたけれども、なかなか設置場所等の問題もありますので、その辺については検討させていただければと思います。","voiceIndex":233,"id":"exchange-097"},{"speaker":"山元委員","kind":"質問・要望","question":"今は小さいの、大きいのたくさんありますので、ぜひお部屋に合わせて考えていただきたいと思います。もう一つ、やはり現場の方からの意見なのですが、これはちょっと所管が変わったらごめんなさい。もしここのほっとサロンで認知症カフェができたらいいのにと、そんな話があります。これは所管が違うので、ぜひ課長同士でご相談していただければと思いますが、ご意見をいただきたいと思います。","respondent":"大串福祉計画課長","answer":"ほっとサロンを認知症カフェに活用といったお話です。その辺、部内の中で協議しながら、実現の可能性を探っていきたいと思います。","voiceIndex":235,"id":"exchange-098"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひ前向きな検討をお願いしたいと思います。では次に行かせていただきます。２２３ページの南品川シルバーセンターの浴室設置工事について、まずここに来るまでの経緯を教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"その後、この東大井地区、南品川地区におきましては、公衆浴場が１軒もなくなってしまったということが、まず基本にございまして、その中でもやはりお風呂のない民間アパートにお住まいの方々ですとか、あるいは民生委員からのご相談も受けまして。","voiceIndex":237,"id":"exchange-099"},{"speaker":"山元委員","kind":"意見","question":"課長のおっしゃるとおり、東大井一丁目から六丁目は１軒も銭湯がありません。そういう意味では、高齢者の方たちが銭湯に行くのに、バスに乗ったり、電車に乗って、風呂桶を持ってまいります。そういうことを考えると、南品川のシルバーセンターにできたのは本当にうれしいのですが、実は東大井には関ヶ原シルバーセンターがあります。その辺はいかがでございましょうか。","respondent":"白鳥高齢者いきがい課長","answer":"関ヶ原のシルバーセンターには浴室はございませんが、近隣において公衆浴場がありますので、ですからそういう意味では、いろいろな調整というものが必要になってこようかと考えています。将来的にこれについては、なくなればどうなのかというふうな思いはあります。","voiceIndex":239,"id":"exchange-100"},{"speaker":"山元委員","kind":"質問・要望","question":"多分、課長は阪急大井町の温泉と間違えていらっしゃるのではないかと思います。１軒もございませんので、ぜひその辺、前向きに考えていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問","question":"孤独死を防ぐ見守りドア、この委員会でも何度か取り上げられてきましたけれども、品川区内の町会の方が、見守りドアの開発をされました。これは今、町内ではかなり普及しているのですけれども、東京都議会のほうで普及をしようということで、助成金の制度創設の議論が始まったと伺いました。こういった事態を品川区はどういうふうに受け取るか、また品川区の今後の取組みについてお聞かせください。","respondent":"大串福祉計画課長","answer":"こういった取組みにつきましては、この見守り事業に参加していただいている団体間で意見交換会というのを毎年やっておりまして、ぜひそういった中でこの事例についてもご紹介して、普及等々できればと考えているところです。","voiceIndex":244,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"共助の充実ということで高齢者見守り活動助成事業の実施、普及啓発事業の実施、関係機関による連絡会の開催ということで、さらにこの充実をしていっていただきたいと思います。逆にそういう生活安全の点から、こういったものが不安要素にならないか。ないと思いたいのですが、その辺の課題というか、不安というものがないか、その辺はいかがでしょうか。","respondent":"上垣外生活安全担当課長","answer":"したがいまして、この見守りドアに取り組んでいただいた方はもちろんですけれども、その周辺に、近隣に住んでいらっしゃる方に対して、歩み寄るであろう不審者に対する警戒感を強めていただくとともに、必要に応じて１１０番通報などをしていただく必要があると考えております。","voiceIndex":248,"id":"exchange-103"},{"speaker":"本多委員","kind":"質問","question":"そういった不安も払拭して、さらに充実されることを望みます。次に行きます。それでこの福祉人材ネットワーク化推進事業、平成２５年度の決算でいくと２４０万円、平成２６年度の予算で１０６万円、新年度の平成２７年度予算が１０６万円ということで、若干消極的な数字計上かと思うのですが、その辺はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"平成２６年度からやり方を少し変えまして、平成２５年度までは介護福祉専門学校のほうに委託をしてやっておりましたけれども、平成２６年度からはＮＰＯのほうに委託をしております。ただ、内容については平成２５年度から変わってございません。","voiceIndex":250,"id":"exchange-104","title":"町会・自治会支援"},{"speaker":"本多委員","kind":"質問","question":"わかりました。よろしくお願いします。それで、今、東京都の福祉保健局が福祉人材情報の一元化ということで、介護福祉士、社会福祉士、保育士などの福祉人材に関する人材バンクシステムを、平成２８年度から立ち上げるというふうに伺ったのですけれども、品川区のそういった部分の考え方や、都との連携についてはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"人材の確保ということで、東京都のほうで提案している人材バンクについて、非常に期待しているところです。ただ、現在もハローワークや介護福祉専門学校で就職合同説明会というのをやっておりまして、さまざまな形で介護職員の確保に努めていきたいと考えています。","voiceIndex":252,"id":"exchange-105"},{"speaker":"本多委員","kind":"質問","question":"よろしくお願いします。最後に１点だけ。２１３ページの認知症高齢者の支援とケアの充実、渡辺委員からも質問がありましたが、１点だけお聞きします。平成１６年度にスウェーデンの認知症対策を調査してきました。医療プログラムによる早期発見、早期投薬、注射によって、認知症の進みぐあいにブレーキをかけるという取組みを、スウェーデンではやっていました。","respondent":"永尾高齢者福祉課長","answer":"なかなか、脳が一部萎縮してしまっていたり、脳疾患が原因というところで、治るというのはなかなか難しいところですけれども、早期に発見して進みぐあいをできるだけ抑えていくということで、発症を遅らせるというところが現在の方法です。","voiceIndex":254,"id":"exchange-106"},{"speaker":"南委員","kind":"質問","question":"２２０ページの社会福祉施設について伺います。一つは特別養護老人ホームの問題です。そこで私は広町二丁目のイトーヨーカドーに貸している駐車場、２,７６０m2だそうですけれども、今年６月で契約が切れるというふうに聞いておりますので、ここに２００人規模の保育園を建設する、その計画と一緒に特別養護老人ホームもつくるべきだと考えていますけれども、いかがでしょうか。","respondent":"大串福祉計画課長、今井制度改革・待機児童対策担当課長","answer":"こちらの事業用地については、再開発事業用地というふうに伺っております。そちらで特別養護老人ホームを整備ということはちょっと難しいと考えているところでございまして、特別養護老人ホームを整備するという考えは持っておりません。広町二丁目の運営主体の件ですけれども、こちらは今、計画については全て検討中です。","voiceIndex":257,"id":"exchange-107"},{"speaker":"南委員","kind":"質問","question":"保育園が２００人規模をつくるという同じ土地に、なぜ特別養護老人ホームは、再開発用地なので難しいということになるのでしょうか。その違いを教えてください。","respondent":"大串福祉計画課長","answer":"特別養護老人ホームにつきましては、基本的に入所された方は長期間入所される可能性が高い施設です。そうした入居者の特性を考えますと、そこに暫定的なものをつくるというのは、施設の特性上そぐわない。こういったことで、特別養護老人ホームの整備はできないです。","voiceIndex":260,"id":"exchange-108"},{"speaker":"南委員","kind":"質問","question":"特別養護老人ホームがつくれないという、そこのところがどうしてもわかりません。なぜ暫定ということでしか考えられないのか、そこについて伺いたいと思います。それから、次の質問に移りたいと思います。八潮にシルバーセンターをつくってほしい、こういう質問です。去年の決算でも同じ質問をしました。なぜつくらないのか伺います。必要ではないというふうに思っていらっしゃるのでしょうか。","respondent":"大串福祉計画課長、白鳥高齢者いきがい課長","answer":"あくまでも再開発事業用地ということで、こちらの土地の目的が決まってあります。そうしたところに恒常的な施設をつくることは不可能ということで、特別養護老人ホームは難しいというふうにご説明しています。しかしながら、八潮地区の中でも文化施設、例えばこみゅにてぃぷらざ八潮ですとか、あるいは八潮地域センター内の施設、こういったものをより多くの方にご利用いただくというのが適切な判断だということで。","voiceIndex":262,"id":"exchange-109"},{"speaker":"南委員","kind":"質問・要望","question":"多くなっている、そういうところに、他の地域と絶対的な格差がある、こういう状況は一刻も早く解決するべきだと思うので、少なくとも私は代表質問で、八潮の高齢化のまちにふさわしいまちづくりを検討していきたいということを質問したのですけれど、その際にも庁内で検討していきたいというお話だったのですけれど、そこにぜひシルバーセンターを入れ込むような計画もつくってほしいということを。","respondent":"大串福祉計画課長、白鳥高齢者いきがい課長","answer":"あくまで再開発の事業用地ということで、再開発を目的として土地を持っているところですので、そちらのほうでの特別養護老人ホームの整備はできないといったところです。それから来年度、平成２７年度につきましては、この八潮地域センター内の敬老室がありますが、こちらにつきまして、旧来のカラオケ設備ということで設置してございましたけれども、やはりご要望が多くございましたので。","voiceIndex":265,"id":"exchange-110"},{"speaker":"南委員","kind":"質問・要望","question":"暫定期間の関係ですけれども、旧日野小学校跡地は、もうかなりの期間、暫定、暫定ということで引き延ばしているではありませんか。これはきちんと区民の要求に応えて、特別養護老人ホームをつくるべきだということを強く要望したいと思います。したがってこみゅにてぃぷらざのを使わざるを得ないと、こういうこともありますので、やはり両方つけるべきだと思います、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは在宅子育て支援について、それと２５５ページ、生活保護費について、そして高齢者施設と保育園について、お伺いをします。生活保護費について、厚生労働省から価格の安い、いわゆるジェネリック医薬品を使用する割合を、現行の６１％から７５％以上に引き上げるよう、各自治体に求めることを決めたという報道がありました。品川区の現状と今後の取組みについて、お知らせください。","respondent":"伊崎子育て支援課長、伊東生活福祉課長","answer":"保健センターでもさまざまな相談を受けております。そして保育課のほうでは、一時預かりオアシスルームなどの預かり機能を持った事業をしています。広く相談に応じるというところでは、いずれの部署でも相談員を設置してやっております。今後のことですけれども、やはり厚生労働省からも普及促進ということで話が来てありますので、引き続きこちらのほうも力を入れまして、医療扶助の抑制ということで頑張っていきたいと考えております。","voiceIndex":270,"id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"要は保育園と高齢者の施設を一体化した施設について、区のお考えをまずお知らせいただきたいのと、例えば保育園をつくる際、今は非常に待機児童の課題があって、保育園を何とか増やしていこうという方向性の中で、しかしながら人口推計を見た中で、高齢者の施設が今後さらに必要となっていく中では、保育園をつくる際の設計を、ある一定の期間は保育園。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"株式会社でも駅前とかで、別の事業主体にはなりますけれども、例えばデイケアみたいなところが上の階にあって、その下の階に保育所があるなど、事業所主体としてもこの頃いろいろ工夫はされておりますので。保育園は今、待機児童対策が最優先課題ですので、一定程度待機児童が解消されたところで、施設の有効活用については今後検討してまいりたいと考えております。","voiceIndex":276,"id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。区としても、例えば多世代の交流をやられたりもしています。それと、誰でも利用ができる、例えば富山型デイサービスの活用なども、ぜひ検討を進めていただきたいと思います。我が会派として、富山に行って見てきました。非常にいい取組みをされていると思いましたので、ぜひ品川区でもその可能性を生み出していただければと思いますが、何かあれば一言よろしくお願いします。","respondent":"大串福祉計画課長","answer":"委員ご提案の富山型のデイサービス、いろいろお話は伺っております。今後とも研究をしてまいりたいと考えています。","voiceIndex":279,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"１点目は２１１ページの高齢者生きがい対策事業費の高齢者クラブについて、２点目が２２９ページの認知症について、認知症は我が党でも２人ほど質問していますが、今、国家戦略が決定したということで、これからの対策ということでお伺いしたいと思います。この品川区の高齢者を支える仕組みの中で、高齢者クラブの位置づけ、役割というのですか、これをどのように捉えているのかお伺いいたします。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者クラブ連合会のほうの事務局としての立場から、この高齢者クラブという位置づけにつきましてのご質問かと思いますが、やはりこれだけの高齢社会になりますと、地域の中で町会・自治会活動も活発に行われる中で、日中あるいはさまざまな場面で、お元気な高齢者の方々のお力。","voiceIndex":282,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"言われればそのとおりなのですけれど、高齢者の方は１町会に１つということになっています。あるいは高齢者７万８,０００人いる中で、２万人ぐらいしかいませんから、そうすると組織率からいうと２５％です。自主的に、独立的にということで、ただ任せているのではなくて、そういうようなことがこれから必要ではないかと思うのですが、その辺の考え方をお伺いいたします。","respondent":"白鳥高齢者いきがい課長","answer":"そういう中では、区として何ができるかということは、この助成金だけではなくてさまざまな情報を提供しながら、これは上部組織であります東京都老人クラブ連合会とも連携をとりながら、進めてまいりたいと考えております。","voiceIndex":284,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問","question":"一つの行事に、高齢者の施策ということで高齢者クラブに入っていない方も参加してやっているわけですから、そういう方たちに「高齢者クラブに加入しませんか」というパンフレットを配るとか、そういうような応援ならできると思うのですが、その辺のことをちょっとお聞きしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"これまで各クラブごとにさまざまな手法を凝らしながら、会員増強ということを行っておりますが、２年前から、年が明けて１月から３月を、会員増強強化月間という位置づけで、さまざまな形をそれぞれのクラブで工夫しながら、会員増強に向けて努力をしているところでありますし。","voiceIndex":286,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"基本的に自主的にという大命題があるので、なかなかしにくいのかと思いますけれども、やはり少しずつではあっても参加できるような手助け、助言というのは本当に必要だと思いますので、今後ともお願いしたいと思います。次に行きます。この中で、認知症対応型のデイサービスというのがありますけれども、これは現在どのような形で、どれぐらい参加しているのか、その辺をお聞きします。","respondent":"永尾高齢者福祉課長","answer":"区内のデイサービスセンター等で、認知症対応型デイサービスというのも幾つかやっております。","voiceIndex":288,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かに数字を見ると、これだけ認知症が騒がれている中で、利用人数は実際に減っているのですが、減っているところもありますと言えばいいのでしょうか。そのような意味で、この辺もしっかりとこれから取り組んでいっていただきたいと思います。これから大きく展開するにはどうしたらいいか、その辺のことをお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それでこれからの方向性ですけれども、サポーターレベルアップ事業というのを開始しておりますので、これをさらに広げ、そのサポーターの方々が今度は地域のほうで活躍できるような体制をとっていきたいと考えています。","voiceIndex":290,"id":"exchange-119"},{"speaker":"松澤委員","kind":"意見","question":"世論調査を見ますと、そういう機会があったら参加したいというような「認知症を正しく理解する機会に参加する」というのがやはり多数を占めているので、この辺しっかり重きを置いて、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":292,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問","question":"事務事業概要では、この社会福祉法人、所管法人としては、区内にのみ事業所を所在する社会福祉法人１２法人というふうになっていますが、たしか記憶では区内には１８法人あったとお聞きしていますが、ほかの法人の指導監査はどうされているのでしょうか。もう一つですが、ちょうど２年経過するところですが、この間の実績はいかがなものでしょうか。よろしくお願いします。","respondent":"大串福祉計画課長","answer":"その間、平成２５年度につきましては定款の変更申請が１６件、指導監査にまいりましたのが６法人で実施をしました。平成２６年度につきましては、定款の変更申請が２件、指導監査が７法人実施をしたといったところです。","voiceIndex":294,"id":"exchange-121"},{"speaker":"高橋委員","kind":"質問","question":"そうすると指導監査をされたのですが、その指導内容というのでしょうか、その件をお尋ねすることと、もう一つ、残りの６法人については直接区が関与しないわけですが、その指導監査について、今あった東京都や厚生労働省からの情報とか、区のほうにどのように入ってくるのか。身近なところにあるのですが、実は遠くで監査をしているという点があるので、その辺区のほうがどう把握をしていくのかということ。","respondent":"大串福祉計画課長","answer":"指導監査部内での異動が非常に多いというふうに伺っておりまして、職員のスキルアップが図られていると。翻って今、私どもの区の体制といたしましては、係長１人と再任用の職員、非常勤の方というところで、３名体制でやっております。","voiceIndex":296,"id":"exchange-122"},{"speaker":"高橋委員","kind":"質問","question":"指導監査の内容と、都の体制との比較をご説明いただきました。そうするとさらに、社会法人の監査だけではなくて、施設のほうのかなり詳しいことも把握しながら、今後この業務を行っていかなければいけないと思うのですが、そういったことも含めて、現在の課題も含めて今後の体制、どのような形を目指そうとされているのでしょうか。","respondent":"大串福祉計画課長","answer":"いずれにいたしましても法人の健全運営もしくは透明性の確保に努めまして、ひいては入居者の処遇の向上、こういったものを図っていければと考えております。","voiceIndex":298,"id":"exchange-123"},{"speaker":"高橋委員","kind":"質問・要望","question":"次に子育て支援のほうですが、ほかの委員の方からもいろいろご質問があったのですが、在宅子育てについて伺います。数字からすると、これは事務事業概要で見たところ、０歳で８０％、１歳で５４％、２歳で５０％と、在宅子育てをされています。施設整備費として１億４,７００万円余が計上されていますが、このようなハード面からの児童センターの今後のあり方について、お願いします。","respondent":"伊崎子育て支援課長","answer":"そういった場合は、皆様が使いやすい児童センターにするために、職員のほうからお声がけをしたり、あるいは掲示をしておむつ替えは適切にしていただくような、そういったソフト面での充実を図って対応しています。","voiceIndex":300,"id":"exchange-124"},{"speaker":"浅野委員","kind":"質問・要望","question":"２４９ページ、すまいるスクール運営費、４５３ページと４８５ページから人間ドック助成事業、４４０ページと４８４ページから葬祭費について、質問します。これからも子どもたちの健全育成の事業として、発展をさせていただきたいとの観点で、質問します。これは他の区と比較してどの程度なのか、そういうデータがあれば教えてください。","respondent":"伊崎子育て支援課長","answer":"他区との比較ですけれども、品川区はご承知のとおり、放課後対策総合プランということで、放課後子ども教室と放課後児童健全育成事業を一体にやっておりますので、なかなか他区との比較というのが難しいところです。学童単体ですと、登録率はかなり減ると考えております。","voiceIndex":303,"id":"exchange-125"},{"speaker":"浅野委員","kind":"質問・要望","question":"登録費用ですけれども、年１,２００円で、内訳が登録料５５０円、放課後子ども教室補償制度費用保険掛金６５０円となっていますけれども、他の区の状況を見てみると、４００円とか５００円のところがあるのですけれども、この保険掛金の違いというのは、例えば補償内容が違うのか、また時間とか場所とか、そういうものが違うのかと思っているのですけれども、この点を一つ教えていただきたいのと。","respondent":"伊崎子育て支援課長","answer":"ですので一定、充実した内容のものに入っていると考えております。","voiceIndex":305,"id":"exchange-126"},{"speaker":"浅野委員","kind":"質問","question":"この内容については、ちょっとほかとの比較はわからないということだと思いますけれども、実際に保険が適用された例というのでしょうか、そういう事故が発生した例というのはあるのかどうかということと、例えばすまいるスクールが実施されている場所であることが条件なのか、また授業が行われている時間帯以外で発生したものについては補償されないのではないかと思うのですけれども。","respondent":"伊崎子育て支援課長","answer":"適用する場所ですが、すまいるスクールの実施時間の学校内はもちろんのこと、すまいるスクールからの登下校についても、適用となっております。","voiceIndex":307,"id":"exchange-127"},{"speaker":"浅野委員","kind":"質問・要望","question":"登下校も含めて、子どもへの補償が保たれるというふうに認識しました。それと次の質問に行きますが、人間ドック助成事業についてですけれども、今年度は昨年の６月２日からの実績しかないと思いますけれども、それを含めて平成２７年度の人間ドック助成事業の予定件数について、国保または後期高齢、両方ともそれぞれ教えていただければと思います。","respondent":"伊崎子育て支援課長、高森国保医療年金課長","answer":"子どものけが、事故などの場合については、正規の職員を中心にして対応ができるような体制をとっております。平成２７年度の予算につきましては、まだ去年１０月時点で予算を調整していますので、状況等見込みがまだ立ってございませんでしたので、平成２６年度と同様の２００件の申込みということで予算を組んです。","voiceIndex":309,"id":"exchange-128"},{"speaker":"浅野委員","kind":"質問","question":"この人間ドック助成事業、最近始まったということで、まだまだ知れ渡っていないのかという気もするのですけれども、国保のほうは、平成２６年度の１０カ月で、平成２７年度の予算というのは減少していると思うのですが、そして後期高齢者は逆に増えているというふうに読めるのですけれども、この見込みとずれた原因の分析、これをひとつ教えていただければと思います。","respondent":"高森国保医療年金課長","answer":"平成２６年度から平成２７年度の予算が減少しているですが、こちらは印刷経費等が若干値下がりした関係で下がってあります。助成件数については変わりはございません。","voiceIndex":312,"id":"exchange-129"},{"speaker":"浅野委員","kind":"質問・要望","question":"この事業につきましても、人間ドックを受けているという方には朗報だと思いますので、ぜひとも広く周知をしていただければと思います。時間もあれですけれども葬祭費について簡単に答弁いただきたいのですけれども、実際の支給率ですが、亡くなった方の人数に対する支給件数について教えてください。","respondent":"高森国保医療年金課長","answer":"亡くなった方の件数ですけれども、平成２５年度が５０２件です。平成２６年度は、現在手元に資料はございません。","voiceIndex":314,"id":"exchange-130"},{"speaker":"浅野委員","kind":"質問","question":"資料がないということですけれども、実際に申請をした数が、亡くなった人数よりも少ないのではないかということを想定して質問しておりますが、もしわかれば教えてください。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。確かに委員ご指摘のとおりですが、すみません、回答について今、持ち合わせてございません。","voiceIndex":316,"id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"２０７ページの成年後見センターのところと、２０５ページで成年後見制度利用支援事業というのが入っているのですけれども、この辺のつながりというのはどういうふうになっているのか、教えてください。","respondent":"大串福祉計画課長","answer":"２０５ページにあります成年後見制度利用支援事業というのは、この成年後見制度を使われる方に対しての支援といった内容になっております。","voiceIndex":319,"id":"exchange-132"},{"speaker":"須藤委員","kind":"意見","question":"２０５ページで今言った収入印紙とかいろいろな費用が入るというのは、社会福祉協議会にそのままお願いしてやったほうが早いのではないかと思うのですけれど、また仕組み的に無理なのか。向こうでいろいろ当たって、アドバイスいただいてやっているので、また区役所に来てどうのというのは、手続きが必要になるのか、そこのところを聞かせてください。","respondent":"大串福祉計画課長","answer":"２０５ページの制度利用支援というのは、あくまでも成年後見制度を利用される方に対しての支援という形になりますので、こういった形で分けた表記になっているです。","voiceIndex":321,"id":"exchange-133"},{"speaker":"須藤委員","kind":"質問","question":"介護を減らしていこうということで、各自治体いろいろなことをやって、介護が下がってきて卒業したと、介護が外れたら卒業式みたいなのをやっている市もあったり、いろいろやっていると思うのですけれど、このあたりは実績的にはどういうものがあるのか、またどういうふうに考えているのか教えてください。","respondent":"永尾高齢者福祉課長","answer":"要介護度改善ケアですけれども平成２５年度から開始いたしまして、平成２５年度、実際に改善された人数というのは４７名です。平成２６年度は４３名ということになっております。","voiceIndex":323,"id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"いつまでこれが必要になるのか。国保では１万６,０００円得るのに、１７万円払っているというような形になっているので、何となくおかしいのではないかと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"それによりまして、平成２３年度以降は時効の中断が生じている医療費、および平成２１年度以降新たに発生した医療給付等の請求遅れ分についての支払いが続いているような状況になっておりまして、これは必然的にもう消滅していくような状況です。","voiceIndex":325,"id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"介護予防のほうは後でまた聞きますけれども、わかりました。続いて２１７ページの移動支援事業、いわゆるガイドヘルプですが、各障害で費用が違ってきているのですけれども、これは人数とかそういうもので出している、費用の算出の仕方ですが、根拠は何かあるのですか。","respondent":"中山障害者福祉課長","answer":"移動支援の各障害別の金額の差ですが、やはり利用の頻度、その方たちの今まで使ってきた時間数、そういったものを予算に反映させていますので、そういった違いです。","voiceIndex":329,"id":"exchange-136"},{"speaker":"須藤委員","kind":"意見","question":"今日のニュースでやっていたのは、１人の保健師あるいは助産師がずっとついて、交代でいくのでなくてお一人でやるというので、頼むほうも安心できると思いますので、上手に活用をお願いいたします。それから介護保険制度、５３４ページ、３款地域支援事業費があります。品川区自身で考えてこういうふうな、地域支援事業として款を立ち上げたのか。項についても、その辺を聞かせてください。","respondent":"永尾高齢者福祉課長","answer":"こちらの科目については、国のほうの指定でつくっているところです。","voiceIndex":333,"id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"そして５３６ページに一般介護予防事業というのがいろいろ出てきています。この一般介護予防事業の考え方というのは、品川区はどういうふうに考えていらっしゃるのでしょうか。介護予防というものを。","respondent":"白鳥高齢者いきがい課長","answer":"介護予防の普及啓発事業の考え方ですけれども、やはり要支援あるいは要介護のための防止策ということで、お一人でも元気に過ごしていただくための介護予防を推進していこうという、そういう考え方で啓発事業を行っているものです。","voiceIndex":335,"id":"exchange-138"},{"speaker":"須藤委員","kind":"質問","question":"それもお年寄りになったらなったときの状況というのも、もちろん予防としてはやらなければいけないだろうと思うのですけれど、そういうあたりをどういうふうに理解していらっしゃるのかということを、少し聞かせてもらいたいと思ったので、そのあたりを教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"あくまでも認知症対策の一環といたしまして、さまざまなことを行っておりますけれども、一つにはいきいき脳の健康教室、これは読み書き計算をしっかり継続していく。","voiceIndex":337,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"最後に認知症の早期発見・早期治療というのは先ほど荏原病院云々というお話を伺ったのですけれども、早期というのは、医者に行く前に見ていかないと早期にならないと思うので、今、予防の段階で発見できるような仕組みとタイアップしていかないと、そこで先ほど来の高齢者クラブがあったり、シルバー成年式があったり、いろいろなところがあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":339,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"６５歳以上の高齢者のうち、５人に１人が認知症であるという計算となりますが、今、介護などを支える社会福祉分野の人材の確保をどうするかが課題になっているということですが、毎年聞いているのですが、介護現場は一向に、改善されていないのですか。そしてまた介護サービスを受ける方、家族を含む方もそうですが、課題が出てきているように感じていますが、その課題についても教えてください。","respondent":"永尾高齢者福祉課長","answer":"特に老老介護の場合は、介護する人もかなりだんだん厳しい状態になっております。そのあたりを今後どういうふうに区とまちの人たちで支えるか、そういうことが大きな課題かと認識しています。","voiceIndex":341,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"今、国のほうでも介護現場に関してはヘルパーの処遇改善対策をやっております。理由は、職場環境と低賃金ということで、それがもう若者の中で広まっている。そうしたらもう既に、このまま行ったら介護の崩壊というのが、どんどん進んでしまうのではないか、始まっているのではないか、また区としても、手に負えないのではないかと思うのですが、その辺どうなのですか、お答えください。","respondent":"永尾高齢者福祉課長","answer":"今度、実務者研修を受けないと介護福祉士になれないというふうに、制度のほうも変わってきておりまして、それに対しても実務者研修の通信制の講座というのを平成２８年度に開設する予定で、平成２７年度にその準備に取り組む予定になっております。","voiceIndex":343,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、いくら一生懸命やっても、ちょっと焼け石に水ではないけれど、どうするのですかと。ところが要支援１だと１日しかご利用になれないとか、そういう制約を受けてしまう。そういう工夫をして、何も給食をつくることはない、出てもらうような仕組みづくりをしない限り、この開きは絶対おさまらないのではないですか。大丈夫ですか、どうですか、でもどんどんその開きは止まらない。","respondent":"永尾高齢者福祉課長","answer":"今度の介護保険の制度改正というのはまさにその部分をどうするかということが言われていることだと思います。その中で、多様なサービスによる介護というところで、その支援の部分でこれから区のほうでも新しいものを考えていきたいと考えています。","voiceIndex":345,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"多様なサービス、よくわかります。でも何とか引っ張り出す工夫を、私は区としてやっていただきたいと。それが将来の介護費用、医療費の削減につながると私は思うし、お年寄りの元気にもつながると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":347,"id":"exchange-144"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２１３ページの入院中の紙おむつ代助成事業と、２１４ページからの障害者福祉についてお聞かせいただきたいと思います。紙おむつ代の助成事業ですが、共産党は介護保険が２０００年から始まりましたけれど、その前の年から入院時の紙おむつ代の現金支給を求め続けてきました。ところが先ほどの答弁を聞いてちょっとがっかりです。所得制限をつけているのは、品川区を除く２２区で４区だけしかありません。","respondent":"永尾高齢者福祉課長","answer":"障害者につきましては、あくまでもこれは要介護３以上の認定者ということになりますので、基本的には障害者の方で要介護３以上であれば、対象になるというふうに考えております。","voiceIndex":349,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ低所得者対策にしたのかということです。なぜ所得制限をつけるのかという、その理由を聞かせていただきたいと思います。要介護３ということは、６５歳とか介護保険対象の要介護３以上でないとだめなのかということをお聞かせいただきたいと思います。高齢者のサービスに所得制限はつけない。しかし給付は所得制限をつけるべきではないと思うのですけれども、改めて品川区の考え方をお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"入院中の紙おむつ代ですけれども、一定程度所得のある方は、やはりご自身で負担をしていただきたいと考えているところです。在宅の方につきましては、社会福祉協議会のほうでやっておりますけれども、それは区民の皆様からのご寄附に基づいてやっております。","voiceIndex":351,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の緊急通報システムについてお伺いします。平成２６年度から高齢者と同様に、民間型にしていくということになっていると思うのですけれども、今年度予算で１６台ということで予算書に載せられておりましたけれど、私はすごくこの台数は少ないのではないかという思いがしているのですけれども、制度が知られていないのではないか、周知をどうしているのかということをお聞きしたいと思います。","respondent":"中山障害者福祉課長","answer":"一応こちらの障害者のしおりのほうでも周知をしておりますのと同時に、今後はケアマネジャー、地域の居宅介護支援事業所とも連携しながら、必要なご家庭にはきちんと制度が入っていくような連携はとってまいりたいと考えています。","voiceIndex":353,"id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分制度を知らないために、すごく不安を持ちながらも、そういう要望も出せないという状況があるのではないかという思いがしているのです。もう一つ、こういう方がお母さんの病気ですとかレスパイトですとか、そういう医療ショートステイ、その考え方は品川区としてどういうふうに持っているのかということについてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ対象者の拡大ということは、全体の調整の中で把握してまいります。重度心身障害者の方のレスパイトと言いますか、医療デイになりますが、東部療育センターですとか、北療育医療センター、そういったところのご紹介をさせていただいて、入院していただいているところです。","voiceIndex":355,"id":"exchange-148"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この言葉、ゴールドとかプラチナでもいいですから、やはり高齢者という響きがあまりよろしくないのではないかという思いがありまして、実際、区としてその辺はどうお考えなのか。ひとり暮らしの高齢者福祉についてということで、高齢者世帯の安否確認と書いてあるのですが、高齢者世帯という中に、生活保護の受給者がどれぐらい含まれているのかというのを一点お聞かせいただきたいということ。","respondent":"白鳥高齢者いきがい課長、伊東生活福祉課長、小林施設整備課長","answer":"この町会・自治会との連携につきましては、この高齢者クラブのほうの活動の中身にしましても、生きがい活動でしたり、健康増進活動。高齢者といいますか、６５歳以上の高齢者ということで生保受給者というお尋ねかと思いますけれども。障害者施設につきましては昭和５６年の法改正がありましたけれども、それ以降の建物等は補強済みということで。サービス付高齢者向け住宅の家賃助成ということで、２月に開設いたしましたカルナ五反田に関係するご質問にお答えいたします。","voiceIndex":358,"id":"exchange-149"},{"speaker":"いながわ委員","kind":"質問","question":"それとサービス付高齢者向け住宅ですが、経緯はわかりました。今後、品川区においてサ高住というのですか、この住宅を普及させていくというのですか、推進していくというか、どうお考えなのか。今後どうするか、増やすべきなのか、増やすのであれば地域的にここは何軒とかそういう決め事をつくってやっていくのかも含めて、今後必要性はどう考えられているのかというのをお聞かせください。","respondent":"白鳥高齢者いきがい課長、伊東生活福祉課長","answer":"この２月には先ほど申し上げましたカルナ五反田というものが、民間主導でもって建設、運営を開始している施設ですけれども、これからの区の考えといたしましては。引き続き、いろいろな就労支援ですとかさまざまな支援をしていますので、これを強化しながら、自立に向けて支援してまいりたいと考えています。","voiceIndex":364,"id":"exchange-150"},{"speaker":"いながわ委員","kind":"質問・要望","question":"生活保護に関して、本当にもらうべき人、給付されるべき人が給付されるというのは納得いくのですが、働けるのに働いていないという方も結構いらっしゃると私は思っております。そういうのをしっかりと、監視というとおかしいですがチェックをして、自立をするように促していただきたい、そのように思っていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":367,"id":"exchange-151"},{"speaker":"たけうち委員","kind":"質問","question":"２３５ページの待機児童解消対策費、２４５ページのオアシスルーム運営費、２５３ページの生活保護費でお伺いします。待機児童解消対策費は関連してなのですが、いわゆる待機児童解消ということでなかなか厳しい実態というのはこの間伺っているのですけれども、今回の申込みの中で、今実際には働いていない、預けられれば働きたいということで申し込まれた方が何名いるかというのがわかれば、教えてください。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長、伊東生活福祉課長","answer":"申し訳ありません。そういったことのないように、一度お電話いただければ、空きがあればこちらからご案内するというような形で。それで５人までが今ですと６万９,８００円、６人以上が７万５,０００円。","voiceIndex":369,"id":"exchange-152"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからオアシスルームは、ちょっと要望を受けた中で、今、ホームページ等ではなかなか出ていないので、全部７カ所か８カ所、全部電話して空き状況を知るということがあるらしいので、なかなか入れないのは仕方ないにしても、そういうのが全部、７カ所、８カ所電話しなくてもいいような方式がないかと。それはそれで、そういうことがあるのかどうか、わかれば教えていただきたいのと。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長、伊東生活福祉課長","answer":"昨年度の待機児童数の事例で申しますと、申込者数が最終的に２,４８３人のうち、求職中という形の方が。それからホームページ等の記載ということですが、ちょっとすぐには難しいのですが、どこかでお電話をいただいたらほかの空き状況がわかるような。その辺はまだ何とも聞いていない状況ですので、それをしっかり聞いた上で、当然説明をしっかりしながら、それに沿って進めていきたいと考えております。","voiceIndex":373,"id":"exchange-153"},{"speaker":"たけうち委員","kind":"意見","question":"生活保護のほうだけ、最後、７月からスタートするというふうに、もう一部でかなり報道も出ていますので、そうなるとその交渉、当人ができる方もいるかもしれないけれど、大家に引き下げの交渉を、ただ中にはそういうことすらできない方も当然いるわけなので、そこで区の方も大変だとは思うのですけれど、どういうふうにご努力いただくかと、そこら辺の腹づもりというかお考えは。","respondent":"伊東生活福祉課長、今井制度改革・待機児童対策担当課長","answer":"必要に応じて、大家のほうにもご説明が必要であれば、ケースワーカーを通してご説明をさせていただきたいと思います。申し訳ありません。２,４８３人のうち、求職は１６６人です。","voiceIndex":377,"id":"exchange-154"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は２１０ページの社会福祉法人許認可に関連をして、それから２１４ページの障害者福祉に関連して質問します。特にこれから高齢者が増大していくわけでありますし、そのためには必ず福祉サービスの充実には財源が伴っていくわけでありますから、私どもとしては財源にも十分配慮した福祉政策の展開をしていただきますよう、よろしくお願いいたします、要望であります。","respondent":"大串福祉計画課長","answer":"ただ、社会福祉法人を設立したいといったとき担当するのは、当然我々ですけれども、逆にその社会福祉法人が特別養護老人ホームをやりたいといったときの特別養護老人ホームの開設の許認可というのは、依然として東京都が持っているということで。","voiceIndex":381,"id":"exchange-155"},{"speaker":"伊藤委員","kind":"確認","question":"要はそれぞれの責任を持って、社会福祉法人を監査できているかということが問題なわけであって、そうすると今の話によると、設立の許認可については東京都であると、確認ですが、もう一回すみません、間違えているかもしれないので。あくまでも品川区の立場としては、区内の社会福祉法人に対する指導なり監査であるということでよろしいのでしょうか。","respondent":"大串福祉計画課長","answer":"我々のほうでは、当然法人の健全な運営、これを担保するというのが大きな使命になっておりますので、そちらについては粛々と、業務のほうを執行してまいりたいと考えています。","voiceIndex":383,"id":"exchange-156"},{"speaker":"伊藤委員","kind":"意見","question":"ぜひそれはしっかり進めていっていただくよう、指導をお願いしたいと思います。それから障害福祉のほうは、震災時の障害者の方に対する支援のことであります。そうすると、こういう方々に対して本当に個々具体的な障害者に対する震災時の支援計画を確立していかないといけないと思うのですが、障害者福祉課のお考えをお聞かせください、お願いします。","respondent":"中山障害者福祉課長","answer":"それとあわせまして、平成２８年度以降の話になろうかと思いますが、こうした補完避難所の開設訓練などを具体的にやることで、実際に災害が起きたときのシミュレーションをしてみたいと考えているところです。","voiceIndex":385,"id":"exchange-157"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめて質問しますけれど、そういう事例を考えていくと、ある程度障害の重い方々は品川区でつかんでいるでしょうから、あらかじめＡさん、Ｂさん、Ｃさんについては震災が起こったらここの福祉避難所等に避難してくださいということを具体的に計画してみたらどうでしょうかということが１点。ですから行政では把握していない方がたくさんいらっしゃるというデータもあります。","respondent":"中山障害者福祉課長","answer":"そういったケースバイケースのことを考えながら、順を追って、何より自宅を安全な場所として、耐震ですとか家具の固定ですとか、あるいはさまざまな災害物品も用意していただくことで、外に避難をしなくてもいいような。","voiceIndex":387,"id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1024#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":123128,"voices":389}},{"id":"h27-20150309-3","meetingId":"h27-c-budget","date":"2015年3月9日","dateIso":"2015-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を178件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"２９７ページ、プレミアム付区内共通商品券のところで幾つか伺いますが、先週、補正の審議があって、補正の予算が通りました。４月の中頃ということで国からおりてきた８億円分という話、各会派、私どもも強く要望させていただいたところですが、この間１週間ですけれど、議決もされて、刻一刻と発売日が近づいていると思います。","respondent":"米田商業・観光課長","answer":"プレミアム付区内共通商品券の春期の事業ですが、発行総額９億６,０００万円、８億円の販売で、１億６,０００万円、２０％のプレミアム分ということで、５,０００円を１口単位として発行する予定です。販売開始日ですが、現在のところ、４月９日を軸に調整をしています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"４月９日というご答弁がありましたので、もうますます本当に近い。その方々に、今度もし２０％になるとしたら、１万円で１万２,０００円ですよと。しかも東京駅のスイカみたいなことはないにせよ、初日に場所によっては混乱が起きるのではないかというような思いもあるのですが、その辺の対応策等は何か区商連と一緒に考えていらっしゃるのかどうなのか、お願いします。","respondent":"米田商業・観光課長","answer":"あわせて販売開始に当たってのいわゆる混乱回避ということなのですが、そういった意味では、全部で５０カ所近くの販売コーナーを設けるということで考えておりますが、当然、主力となる郵便局の協力もいただきながら、あるいは商店街や商店街連合会で販売するに当たっても、今。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"ではないと、ホームページはそんなに見る方はいらっしゃらないですし、町場で掲示板にポスターをどんとつくって、また売り出しますよと、町会にお願いしてなり、ふれあい掲示板を使うなりしての周知方法をもうちょっと細かく教えてほしいのと、やはり郵便局は結構、特定郵便局が町場の中にあって、小さいところで、万万が一ですけれど、相当並ばれるようなことがあったらなどと思っていたものですから。","respondent":"米田商業・観光課長","answer":"あわせて、区の広報紙のほうも、今、４月１日号に載せる形で調整を進めているとともに、統合ポスターのほうでも周知を図るということで、いわゆる知らなくて買えなかったということについては回避していきたいと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういうところもなるべく今回やっていただきたいというような思いもあります。組合活動などをされていると思うのですけれども、そういうところで一括して登録をいただいて、区内それぞれちょっと飛び地といいましょうか、商店街に絡んでいない、かかわっていないようなところでも使えるような仕組みというのは何とかとれないでしょうか。何かその辺をどういうふうにお考えなのか、もし教えていただければ。","respondent":"米田商業・観光課長","answer":"これまでも取扱い店舗の拡大ということでやっておりましたが、今回、発行額も大きいということで、早速、区商連のほうも今、取扱い店舗の確認というか、掲載店舗の調整を行っているところでは、商店街や各個店等に、取扱いの金額が大きいので。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"何年か前に実際、荏原のほうの酒販がそのような動きをして使えるようになっているというのもありますので、広めていただきたいのと同時に、これは再度の要望になるのですけれども、やはり商店街は、僕も実際に質問してみて、歩いて、ではステッカーを張ってあるかというと、なかなかやっぱり張っていないのですよね。そして、２９７ページで、今回も予算書のほうには金額が上がっています。","respondent":"米田商業・観光課長","answer":"そういったさまざまな課題等が生じましたら、またその辺を十分踏まえて、それを活かして、秋口の対応について考えてまいりたいと思っているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"以前はものづくりで伺って、品川パビリオンに品川区をアピールするようなものをと言ったのですが、先日、ヴィアイン東京大井町のホテルの方とお話しすることがありまして、今、平日の稼働率が大体九十二、三％ぐらいあるそうです。やみくもに何かをやるのではなくて、ピンポイントに絞ってやっても、相当な方々に品川区にお越しいただくということが可能だと思うのですが、何か手は打てないでしょうか。","respondent":"米田商業・観光課長","answer":"そういう支援と、あとは鉄道機関との協力ということも必要になってくると思います。りんかい線という品川区を通る路線について、遠方から訪れる方をぜひ大井町・大崎に誘客できるような形で、また新たな取組みを考えていければと考えているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"私からは２５９ページ、ＡＥＤ管理費、２６５ページ、そ族昆虫防除対策費、２９７ページ、プレミアム付区内共通商品券発行助成についてお伺いします。ＡＥＤです。これまで設置場所の拡大、また設置場所がわかる一覧、また地図などを求めてまいりました。その上で、現在、ＡＥＤの地図についてはどうなっているか教えてください。","respondent":"川島健康課長","answer":"今ご質問にありましたＡＥＤの地図につきましては、まず平成２０年に発行しました『わが家の防災ハンドブック』に掲載しています。これは平成２４年に改訂されておりますので、新しいものが載っているということです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"今の『わが家の防災ハンドブック』については、区有施設なのですね。私も冒頭言っていなかった。この間、私も、区役所の総合案内横に設置されているＡＥＤのところまでこのワンコに案内してもらって、ああ、ここにあるのだと改めて確認しましたが、このナビワンコで見られるよということも、ＡＥＤ施設の一覧のところに、一緒に紹介なりリンクを張ったらいかがかなと思うのですけれど、どうでしょうか。","respondent":"川島健康課長、秋山情報システム課長","answer":"委員ご指摘のものとか、そういった新しい技術を活用していくことは重要だと思うのですが、まず台数を拡充することに主眼を置いておりますので、今後、まずわかりやすい位置にちゃんと設置していること。私のほうからナビワンコの件ですけれども、オープンデータを利用されたアプリの一つということですので、区としても正確な情報を公開していくことで、そのようなアプリが増えていくだろうということは想像しておりますので、次年度以降。","voiceIndex":19,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"次の観点の質問で、ＡＥＤの訓練を受けた地域の方から、夜間のときの課題として、音声はＡＥＤから出るのだけれども、ボタンだとかソケットを設置するときに、例えば夜間とか暗いときに使うときに見えづらいのではないかという声をいただいて、今現在、入替えのタイミングで、蛍光表示版のものが順次入れ替わっているというのは知っているのですが、暫定的でも、今、替わっていないものについては。","respondent":"川島健康課長","answer":"いつでも使えるようにするため、夜間でも目立つ、発光するということは重要だと思うのですが、維持管理のしやすさとの両立もありますので、ご紹介いただいた内容も含めまして、安価で見やすくわかりやすい、発光ですとか装飾ですとかというところは研究してみたいと思います。","voiceIndex":22,"id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"過去にもＡＥＤの設置場所については、平成２４年度予算特別委員会で、２４時間営業のコンビニとか飲食店、ファミレス、ガソリンスタンドといったところに協力を依頼することとか、また生活安全パトロール隊の車に搭載して、いざというときにも対応ができるような仕組みはどうだろうかという提案をさせていただきました。こうしたところの工夫について教えていただきたいと思います。","respondent":"川島健康課長","answer":"ＡＥＤがいつ必要になるかというのがわからないということで、前々から２４時間対応の重要性というのを訴えていただいているです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区から直接そうした依頼ができる先というのは、ある程度あると思います。次に行きます。そ族です。デング熱対策です。これまでも蚊が媒介する感染症対策を、品川区としても鋭意とられてきたと思います。その中で、昨年多くのご相談をいただいて、直接ご対応いただいた案件もありました。今回、８５０万円の予算計上ということで、どのように対策を強化するのか教えてください。","respondent":"高山生活衛生課長","answer":"中身としましては、雨水ますを蚊の発生源とみなしまして、そちらに、ボウフラ対策、幼虫対策ということで、脱皮等がしにくいような薬剤を投入することによって、区内全域において蚊の量を減らしていくような対策の内容となっております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"私もプレス発表を読んだので、今ご答弁いただいたことは確認したのですけれど、もうちょっと具体の部分が欲しかったなと思いますが、その上で、厚生労働省の厚生科学審議会の中に、感染症部会の蚊媒介性感染症に関する小委員会というところがあって、その中で蚊媒介感染症に関する特定感染症予防指針案というのがまとめられたということで報道にも出ておりまして。","respondent":"佐藤保健予防課長","answer":"それが昨年の事例を受け、国内でも感染するのだという認識になって、現在の動きになっているわけですけれども、これまでは、基本的には蚊に刺されないほうがいいわけですので、蚊には刺されないようにという注意は一般的には申し上げてきたところですが、そういった意味で。","voiceIndex":28,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きます。プレミアム付商品券です。先ほど渡部委員のほうから、るる質問をしていただいて、私としても聞きたかったことを、答弁を引き出していただきました。その上で、例年、予算規模で計上されているこちらなのですが、その発行時期・回数・発行規模について、先ほど若干のご答弁がありましたけれど、改めてお伺いしたいと思います。","respondent":"米田商業・観光課長","answer":"その上において、当然、春期の発行分につきましては、年末年始の時期においては使えないわけですので、その辺の結果を踏まえて、区にある当初予算に計上しますものをどう有効に使うべきか。これについては改めて検討して、秋期に備えたいと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"時間がないので、最後は要望になりますが、ぜひ今回の、春にやります２０％は、ある意味で、一旦は今回限りですと周知をきちんとやっていったほうがよろしいのかと思いますし、その辺の周知と、また品川区で独自に計上している商品券の発行については、また発行総額においては１口当たりの発行単位もぜひまたご検討いただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問","question":"ホームページを見ると掲載されているのですが、平成２５・２６年度で、この取組みについて、全く同じセミナーの開催とか、間伐材探検ツアー、ワークショップ、ベンチの製作という、大体同じようなのが平成２５・２６年と続いていますが、実際に品川区としての着地点というのですか、何を今後考えていくのかというのをまず教えてください。","respondent":"三ツ橋環境課長","answer":"そちらにつきましては、まず区商連への補助金の事業です。こちら、区商連に対して補助金を出し、区が実施する国産間伐材の有効活用事業を助成することで、区民に向けて国産間伐材を使用したもの、また環境保全につながるというものがありますので、こちらを助成してまいります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"いながわ委員","kind":"提案","question":"もちろん、品川区にまだそういった補助というのはないわけでありますが、少なくとも、ある意味、こういう事業をやられているわけですから、東京都がどこに助成しているというのですか、例えば私立の保育園でどことどこに多摩産材が使われているというのを把握されていたら教えてください。事業所も含めて教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"略しまして公共建築物等における木材の利用促進法と申しますけれども、こちらは平成２２年５月に法案が成立され、またそれに基づいて東京都は方針を定めております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問","question":"ついでにもう１点お伺いしたいのが、本来、公共建築物における木材の利用の促進に関する法律の中で、国・地方公共団体の責務ということで、公共建築物への木材利用の促進に関して実効性を担保するため、農林水産大臣と国土交通大臣へ利用目標などを定めた基本方針について、毎年１回、実施の状況を報告しなければいけないというのが、その方針というのですか、法律の中に入っている。","respondent":"三ツ橋環境課長","answer":"そちらから区商連事業への展開がございまして、国産間伐材というものが展開しております。その中で、方針というものは、今現在のところは検討段階でございまして、ほかの関連する事業、関連部署とも協議を図りながら検討してまいりたいと考えています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"でも、それが区商連の事業としておさまっていていいのか、どうなのか。もっと幅広く、やはり学校、あと高齢者の施設も含めて、木を使っていくということは非常に大切なことだと考えています。今、これから各部署と連携してということなのですが、具体的に品川区としては今後の方針として定めるべきではないかなという思いの中で、もう一度そこは聞かせていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"内容につきまして、法律の定義の中で、確かに学校や老人ホーム、保育所、病院、体育館、社会施設、図書館、車両など、法律の関係では定めておりますけれども、今後、方針につきましては、やはり非常に慎重に対応していかなければいけない問題だと思いますので。","voiceIndex":40,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひよろしくお願いします。ここまでお話を進めてきたので、１点、最後に、品川区の公共施設、いろいろ多くあると思います。そういうところで、今、実際に、多摩産材とか、間伐材なのかは別にしても、それを使っているところというのですか、何というのでしょう、達成率というのですか。そういうのがもしわかれば教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"実際に品川区内で多摩産材あるいは国産間伐材などを使っているものに関しましては、ちょっと把握はできていないのですけれども、今後は展開していけるといいと考えております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"意見","question":"今、御殿山小学校がやっているという話があったので、そういうのをしっかりキャッチして、やっぱりこういうのは進めて、議員の中にも材木屋もいるので、やっぱり木は大切だと思いますので、しっかりそれを進めていくようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、２７４ページの環境費にかかわって、横須賀線の騒音と羽田増便について伺いたいと思います。横須賀線ですけれども、西大井四丁目と五丁目の間で横須賀線の大きいカーブがあります。同時にまた新幹線がこの地域を通過する際の騒音規制というのは何デシベルぐらいなのか。新幹線よりも横須賀線のほうがうるさいわけで、ぜひＪＲに必要な対策を求めていただきたいと思いますけれど、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"新幹線騒音につきましては規定がございまして、こちらは７５デシベル以下となっております。横須賀線というのは在来線ですので、環境基準の規定がございません。新幹線につきましては、今申し上げたように、７５デシベルと、基準が決まってまいります。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、まずぜひ現状をよく把握していただきたいと思うのと、それと横須賀線は湘南新宿ラインを含めて本数が増えたり、また貨物列車が通過するときもすごい騒音です。もう一つ、今後、大崎短絡線計画が具体化すると、この問題がさらに深刻になると思うのです。それだけに、まずは現状を十分に把握し、ＪＲに対応を求めていくということが、この点からも必要だと思うのですけれどもいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"朝の増便、また１日中、全てを聞いたところ、特に増便しておりませんということでございました。こちらの現状把握ですけれども、苦情があった場合には区の環境課が実際に測定して丁寧に対応してまいりたいと思いますので、よろしくお願いいたします。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"次に羽田増便についてですけれども、本会議でも、騒音・落下物・墜落のリスクについて伺いましたが、区民への影響が具体的にどのような形になるのか、想定されるのか、ここを明らかにすることが私は今大事だと考えています。風向きによっても変わると思います。南風時８０デシベルの影響が起きる範囲は、地上部分では飛行ルートの左右何メートルぐらいに影響を及ぼすのか、現状を伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"区民への影響ということで、騒音の影響というお尋ねですけれども、こちらはまず区に対して、国から住民への説明ということが一番大事なことと考えておりますので、騒音に関しても、国にしっかりと説明をしてもらいたいというのが区の要望としています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"国に対して説明を求めているということですけれども、地上部分にどういう広がり、また幅を持った、８０デシベルならどれぐらいの範囲なのか。落下物ですけれども、飛行機からなぜ氷の塊が落下するのか、これを防ぐにはどのような対策があるのか、区の見解を伺いたいのと、市街地への墜落について、住民の被害を防ぐにはどのような対策があるのか、現状を伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"資料につきましては、今までも国に対して説明を求めており、また区民に対してしっかりと説明をしていくように引き続き要望はしてまいります。","voiceIndex":52,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、国に求めると同時に、区も８０デシベルの影響がある範囲が、私は真下だけだとは限らないと思うのです。この点を伺いたいと思います。落下物について伺ったのは、なぜ飛行機から氷の塊が落下するのか、これを防ぐにはどのような対策があるのか、区の認識を伺いたいと思います。市街地への墜落を回避する方法にはどんな対策があるのか、区の認識を伺いたいと思います。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"資料づくりにつきましては、国からまずいろいろ説明を聞き、いろいろ考えてまいりたいと考えています。若干、補足しますけれども、騒音の区民への影響の部分ですが、建物あるいは音の広がり、風の影響、それらは非常に専門的な見地を要しますので、区のほうとしても情報提供を受けながら検討はしてまいりますが。","voiceIndex":54,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"騒音については、区民への影響がどういう範囲に及ぶのか、そこをしっかりわかるように示していただきたいと思います。市街地への墜落の回避についても、場所は陸上を飛んでいるわけですから、海に回避するというのはなかなか現実的ではありません。こうしたリスク回避が示されていないもとで、品川区はこの計画を了承することは絶対あってはならないと思いますので、強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"それと、補正のときにお伺いしたのですけれども、ちょっとよくわからなかったので、出生数と乳幼児の人口動向について、品川区の乳幼児がまだまだ増えていくのか、それともピークが過ぎて穏やかに減るのか、それとも急激に減るのか、このあたりの数字を教えてください。","respondent":"太田品川保健センター所長","answer":"６・９カ月児も去年の６,２００人に対して６,５００人で、１歳６カ月児は去年が３,６００人で今年も３,６００人ということで、ほぼ同等を見込んでおりまして、３歳児につきましては３,２００人を３,４００人と増えていくというふうに見込んでおります。","voiceIndex":59,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"それで、原因などは分析していませんというなら、していませんという答弁で結構ですから。やはり人口というのが大事なわけですから、その辺の分析のお答えが全然いただけていないので、その辺をよろしくお願いします。","respondent":"柏原行財政改革担当課長、太田品川保健センター所長","answer":"今後の流れにつきましては、先ほどもありましたけれど、平成２７年度をピークにというところでは予測、推計しておるのですけれども、人口流入が起きているといったところで、そういった方々の世帯が出産されているということで。それで、今までの出生数で生まれた１・６・３歳のお子さんたちに比べて４カ月児の人口が多いです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"６・９カ月児の数字が大きいではないですか。ほかのは３,０００人台で来ているのに、ここだけ傾向が違うではないですか。だから、それの原因と要因を教えてくださいということです。","respondent":"太田品川保健センター所長","answer":"対象者も３,５６６名ということです。９カ月児が、対象者が平成２５年で３,５６６名、受診者が３,０２２名ということで、この両方の年齢を加えたものがこちらの予算書の６,５００名です。","voiceIndex":64,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"次に２７５ページの太陽光発電システム設置助成をお伺いしますけれども、太陽光については神奈川県知事も力を入れていますけれど、国の原発をどうするのかというところまで考えていかなくてはいけないと思うのですけれども、今日は区の話なので、国のことは置いておいてやらせていただきたいと思いますが、自然の力を利用したエネルギーのエコという意味で私も注目しているのですけれども。","respondent":"三ツ橋環境課長","answer":"太陽光発電システムのことについてお答えいたします。国の考え方はいろいろありますけれども、地球温暖化防止に向けて、太陽光発電という自然再生エネルギーというのは非常に大事なものだと考えています。そこで区も太陽光発電システム設置助成というものを実施しております。","voiceIndex":66,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"ちょっと今日、私の質問が悪いのですね。すみません。区の姿勢を、どういう思いでやるのかというのを明確に答えていただきたい。太陽光は大事ですよね。昔、こういうエコなどと言うと、マイ箸などあったのです。だけど太陽光というのは原発等にもかかってくるわけですから、区としては、こういう思いで、こういう形でやるのですという姿勢を明確にお答えいただけますか。","respondent":"三ツ橋環境課長","answer":"温暖化対策事業につきましては、こちらは温室効果ガスの削減というものが区としても非常に大事だと考えていますので、こちらについては、特に太陽光について推進していきたいと考えています。","voiceIndex":68,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"２９１ページの永年継続事業所顕彰経費と、２９５ページの経営相談事業費、それから時間があったら２９７ページの国内・海外展示会出展費助成と海外進出推進事業についてお伺いします。","respondent":"米田商業・観光課長","answer":"いろいろ調べている中では、１００年以上事業を継続している事業所も、おおむね２０ぐらいあるというようなことで伺っておりますので、一応その辺のところを想定しつつ、これから産業団体と意見交換しながら。","voiceIndex":71,"id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"そういった形で顕彰されるということは本当にすばらしいことだと思いますけれども、例えば顕彰して、その後どうするのかということを聞きたいのですけれども、終わりではなくて、例えば広報しながわなどで一社一社特集していったり、あと歴史館とか区のスペースなどでその会社の歴史とか製品を展示していったり、中小企業センターもありますけれども、そういったところでの。","respondent":"米田商業・観光課長","answer":"顕彰式では当然、区のほうから盾や感謝状を贈呈したりというようなことで考えておりますが、当然、それ以降ということで、いわゆる１００年というような一つの目安で表彰されましたということでは、そちらの事業所のＰＲを、中小企業センター等含めてできるような形。","voiceIndex":73,"id":"exchange-033"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひとも積極的に行っていっていただきたいと思います。永年ということで、継続されてきたということとちょっと関係してなのですけれども、経営相談事業費の中で、事業が継続していくことを、事業承継についての相談ということでお伺いしていきたいのですけれども、近年すごく、事業承継については相談が多くなっているということを、この間も新聞で見ました。","respondent":"山崎ものづくり・経営支援課長","answer":"事業承継につきましては、品川区の企業数が２万２,０００社でございまして、そのうち４名以下の小規模事業が１万２,０００社ということで５４％を占めている関係があります。","voiceIndex":75,"id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"大体、その相談の中で、今までは金融というか融資関係の相談が多かったかと思いますけれども、相談件数は減ってきていますけれども、その中で大体、事業承継に関する相談というのが現在どれぐらいになっているのかもお聞かせいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"団体のほうの関係ですけれども、東京都のほうが東商支部などで、東京都としての事業継承支援というような形の窓口もやると聞いておりますので、そうした機関と十分連携をとりまして、小規模の融資なども含めまして、総合的に対応してまいりたいと考えています。","voiceIndex":77,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間がないのですけれども、海外進出事業のことでお伺いしたいと思います。行ったことがないのでわからないですけれども、見たことはないのですけれど、バンコクとか、それからベトナム調査団派遣を平成２５年度にやられたかと思うのですけれども、その２つのことに関してのその後の状況というか検証はどういうことになっているかお聞かせください。","respondent":"山崎ものづくり・経営支援課長","answer":"ベトナムのほうは若い労働力等々の魅力があるというところで、そちらの調査も含めまして、ＡＳＥＡＮ諸国、新興国ということで注目もされておりますので。","voiceIndex":79,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、２９５ページ、武蔵小山創業支援センター運営費、２９７ページ、プレミアム付区内共通商品券発行助成、３つ目が２６３ページ、女性の健康診査、３点についてお伺いします。武蔵小山創業支援センターについて伺います。ここに運営委託で約４,４００万円、建物の維持管理費で約１,３００万円、これは一つの事業者に委託しているのか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"それから内訳としましては、４,０００万円余の部分が武蔵小山創業支援センター内で行うソフトの事業というところの委託費でございまして、それ以外の部分がハード系の施設経費というようなことです。","voiceIndex":82,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"次の日曜日には、第４回ウーマンズビジネスグランプリのファイナルもありますし、品川まちなか起業ステーションとか、羽ばたけ！セミナーも年間６０回から８０回、相談件数も２００件前後、私も視察に伺っていろいろお話を聞きましたけれども、非常に優秀なスタッフの方がいらっしゃる。その導入から１２年が既に経過しております。法的にどのように位置づけられるのか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"武蔵小山創業支援センターにつきましては、平成２２年８月開設ということですので、その前年の２１年度の４定で、区立創業支援施設条例ということで、公の施設に位置づけられております。","voiceIndex":84,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"確認","question":"一部の委託であるということなのですけれども、委託と、その導入の際に、指定管理制度の大きな違いの一つに、法改正の際に大きく強調されていたのが、権限と業務の範囲が変わると。委託業務においては、施設の基本的な利用条件の設定や施設の許可使用権限は自治体に残る。これは利用条件の設定に当たります。そこを突っ込みたいわけではないのです。ですけれども、一応ちょっと確認させてください。","respondent":"山崎ものづくり・経営支援課長","answer":"その内容を区のほうで確認させていただいて、現地と十分連携をとりながら、形式的ではありますけれども、条例あるいは施行規則に基づいて手続はやらせていただいているというような内容です。","voiceIndex":86,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"なぜこんな細かい、つまらない指摘をさせていただいているのかというと、５,０００万円という金額で委託をしている事業について、大きなお金だと思うのですけれども、実質的には包括的な管理業務を行っている事業者が、外形的には一部の業務委託を行っているとされているならば、その事業内容について、我々議会とか区民がなかなかチェックできない。これは議会への報告義務があるのか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"これはセンターなどの事業の継続性・連続性も含めた観点です。それで、ちょうど開設から５年目を迎えて、今年度、再度プロポーザルということで、やり直しをしたものです。そうしたところで、定期的なチェックといいますか、そういったことをさせていただいているです。","voiceIndex":88,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょうどはざまのようなところに今あると思うのです。例えば工場アパートなどは、確かにこれはもう本当に施設の管理だけだと思うので、それは別に指定管理しなくてもいいと思うのですけれど、法的な観点から見ても、先ほども一点ちょっとご指摘させていただきましたけれども、あと区民とか議会のチェックなどというところも実態に合った制度をとるべきだと考えますが、いかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"こうしたものが６月にオープンの予定になっておりますので、さまざま管理運営方式につきましては、固定しているということよりも、よりベストな、ベターな方式を、これからしっかり考えて検討していくというような必要性は感じているものです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間がないので、２つまとめて質問します。女性の健康診査ですけれども、これもさまざま若い女性の方から最近ご要望を伺います。女性の場合はいろんな事情があって、品川区だけでかかりつけ医がいるということではないものですから、ふだんから自分の身体の状態をよく知っているお医者さんにかかりたい、かかっているという場合がある場合に、できたら自分の身体の状態がわかっているところで健診を受けたい。","respondent":"米田商業・観光課長、川島健康課長","answer":"ある程度、融通の余地があれば、ご提案のようなことについては現状もうやっておりますし、ある程度は可能かとは考えているところです。ですので、区内で一律にやるということになると、単価の問題ですとか、それから条件の問題とか、やはり２３区それぞれ事業形態が違うということで、ちょっとなかなか難しいというのが見解です。","voiceIndex":92,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは里帰りという事情があるから仕方がないということだったと思うのですけれども、これも多分、１つ例外としてできるわけですよね。ちょっと私も正確な表現は忘れてしまいましたけれども、そんな内容になっていると思うのですが、これが例えば特別区であるとか、東京都のほうで検討課題に挙がっているのかどうか。挙げていただきたいという趣旨で、もう一度お聞きいたします。","respondent":"川島健康課長","answer":"現状ではそういった検討課題には挙がってございません。","voiceIndex":95,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後は、検討課題に挙げていただきたいという質問でございましたので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"本日は、２６１ページの任意予防接種と感染症予防費に関連して、ロタウイルスワクチンと感染症対策についてお尋ねいたします。ロタウイルスワクチンについて再度お尋ねいたします。第３回定例会でもロタウイルスワクチンの接種費用の助成について要望いたしました。ぜひ助成の検討をお願いしたいと再度要望いたしますが、区のお考えはいかがでしょうか。","respondent":"佐藤保健予防課長","answer":"副反応などの課題も予防接種にはあります。そういった意味で審議会等の結論を注視しながら慎重に検討を重ねたいと考えております。","voiceIndex":99,"id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"意見","question":"次に先天性風しん症候群についてお尋ねします。ただ、麻しん・風しんにいつかかってもおかしくない、２０代から４０代のワクチン未接種の成年男性の集団に対するＭＲワクチンの接種勧奨は、とりわけ今後も力を入れて行う必要があると思いますが、区のご認識と、あわせてホームページの啓発以外の具体的な施策をご紹介ください。","respondent":"佐藤保健予防課長","answer":"風しんの抗体検査、特に男性への啓発活動についてのお尋ねです。現在、今年度の実績ですが、やはり男性のほうでも３０代を中心に２０代から４０代の男性の方が特に抗体検査を実施していただいております。","voiceIndex":101,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これに関連して、最近、アメリカでディズニーランドを起点とした麻しんの流行が報告されております。なぜアメリカで今、麻しんが流行しているのか、区はどのように捉えていらっしゃるのでしょうか。ご説明をお願いします。","respondent":"佐藤保健予防課長","answer":"もう１点、オハイオにありますコミュニティで広がった感染症につきましては、その方もフィリピンに行かれたことが発端と聞いておりますが、予防接種率が極めて低い集団ということで爆発的に広がったというふうに聞いております。","voiceIndex":103,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"意見","question":"アメリカの麻しん患者は２０１４年は６４４人、２０１５年も既に１４５人を超えてメキシコなどに飛び火しているということです。アメリカの公的機関であるInstitute of Medicineも２００４年にこの問題に対する最終的な調査報告をまとめて、「ＭＭＲワクチンは自閉症を引き起こさない。２００７年、我が国でも麻しんが大流行しました。","respondent":"佐藤保健予防課長","answer":"それにいたしましても９０％未満という数字で、さらにＭＲワクチンの接種率向上には努力をすべきところと私どもも認識しております。具体的にですが、２期は就学前１年間の期間ですので、まず未接種者に対する年度途中での勧奨ということを行っております。","voiceIndex":105,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで、昨年の本会議で指摘した、１歳児に区が配布している案内チラシの、「ＭＲワクチンの次に水痘ワクチンを」という、保護者に誤解を与えるような表現というのは、既にもう改善されたと受け取ってよろしいのでしょうか。去年の４月段階に患者から見せてもらったチラシには、まだこの表現が残っておりましたが。","respondent":"佐藤保健予防課長","answer":"水痘ワクチンにつきましては、これまでは任意予防接種ということでそのような記載になっていたと思います。","voiceIndex":107,"id":"exchange-049"},{"speaker":"松永委員","kind":"質問","question":"私からは２７５ページの環境調査測定費、そして２９５ページの商店街にぎわい創出事業、関連して商店街活性化推進事業、また時間がありましたら、２６９ページの食育推進事業について伺いたいと思います。初めに、２７５ページの環境調査測定費について伺いたいと思います。どういったところで測定をされているのかについてもあわせて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"今年度、そちらで導入しております。品川区内につきましては、八潮、大井中央陸橋、平塚橋交差点、豊町・北品川交差点で大気汚染の測定を実施しております。","voiceIndex":110,"id":"exchange-050"},{"speaker":"松永委員","kind":"質問","question":"品川区においては、こうした幹線道路というものがとても多くありまして、それを踏まえて今後どういった取組みをして、地球温暖化防止とか、そういった対策がありましたら教えてください。","respondent":"三ツ橋環境課長","answer":"実際に大気汚染につきましては、東京都がディーゼル規制を平成１５年に実施いたしまして、大気汚染が大分減ってきている状況にあります。しかしながら、区といたしましても、きちんと状況を把握しなければいけないと考えていますので、今後とも実施してまいります。","voiceIndex":112,"id":"exchange-051"},{"speaker":"松永委員","kind":"質問","question":"次に、先ほども中塚委員から質問がありましたけれども、改めて航空機騒音調査について伺いたいと思います。そうした中で、来年度、航空機騒音調査が取り込まれておりますけれども、その調査方法といいますか、また調査される場所について伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらの内訳といたしましては、測定機の保守点検委託、また測定データの確定業務の委託、また航空機の騒音調査の測定機の設置についてです。場所につきましては、非常に難しい部分がありますので、詳細にいろいろなことを検討しながら決めてまいりたいと考えています。","voiceIndex":114,"id":"exchange-052"},{"speaker":"松永委員","kind":"意見","question":"すみません。大体でいいのですが、何カ所……３カ所、失礼しました。今後、そういった調査結果を国に伝えていくとは思いますけれども、国が調査結果を受けて、そのまま資料にするのかどうかわかりませんけれども、今後そういった形で品川区としては、その調査結果ということで、今後進めるのか進めないのかというのは、その辺ははっきりと答えていく予定でございましょうか。","respondent":"三ツ橋環境課長","answer":"実際に今現在の静かな状況の段階の測定をまずはしていきたいと考えていますので、そちらの公表につきましては検討させていただきたいと思いますが、必要に応じて対応してまいりたいと考えています。","voiceIndex":116,"id":"exchange-053"},{"speaker":"松永委員","kind":"質問","question":"今、音はあまりうるさくはないとは感じておりますけれども、もし万が一、さっき言いましたけれど、国土交通省で中間取りまとめが発表されまして、そこでオリンピック・パラリンピックまでに実現するという方策があると思いますが、その方策どおりになった場合に、例えばオリンピック・パラリンピックが閉会した後に、またその後も同じような形で続いていくのか。","respondent":"三ツ橋環境課長","answer":"オリンピック・パラリンピック以降のことにつきましてのご質問にお答えいたします。国としては、資料に基づきますと、飛行場を増設していく可能性は書かれておりますけれども、それはまだかなり未定の部分ですので、その状況に応じて対応してまいりたいと思います。","voiceIndex":118,"id":"exchange-054"},{"speaker":"松永委員","kind":"質問","question":"２９５ページの商店街にぎわい創出事業に関連して、商店街活性化事業について伺いたいと思います。イベント事業助成とにぎわい事業助成との違いについて伺いたいと思います。","respondent":"米田商業・観光課長","answer":"対しまして、にぎわい事業の助成につきましては、例えば、ワゴンセールですとか朝市・夕市、あるいはポイントカードの倍出しというようなことで、商店街のほうで年６回以上継続して行われる、にぎわいについての取組みに対する助成ということで。","voiceIndex":120,"id":"exchange-055"},{"speaker":"松永委員","kind":"質問","question":"昨年度の予算書を見ていますと、イベント事業助成額が９,１９０万円で５２件になっております。同じ件数で本年度は９,７４０万円と、５５０万円ほど増額されておりますが、これは消費税によるものなのでしょうか。","respondent":"米田商業・観光課長","answer":"経費がある程度上がってきたというところで、そういう部分もあるかもしれませんし、あるいは事業を少し拡大してイベントを行いたいというような申請も上がってきてありますので、そういうことでの経費の増加というふうに捉えてあります。","voiceIndex":122,"id":"exchange-056"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした助成を受けて、商店街からこういった声が上がっている。例えばにぎわっているのか、にぎわっていないのかという現状がわかれば教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"例えば、イベント事業等については、区内のみならず区外あるいは都外からもお客さんを招いて、それでいわゆる商店街というものをイベントを通じて感じていただいて、また再来を期すというようなこと、それからにぎわい事業については継続的な取組みということで。","voiceIndex":124,"id":"exchange-057"},{"speaker":"松永委員","kind":"提案","question":"今後の課題として、にぎわいのある商店街を目指すためには、そうしたイベントを定期的に行い、リピーターを増やすことも大切だと思います。私からちょっと提案なのですけれども、活気とにぎわいのある商店街は、さまざまな理由があると思います。そこで、たしか静岡県のあるＮＰＯ法人が行っている事業だと思いますが、イベントで、こども１０円商店街というものをやってみてはどうかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、２９１ページ、就業支援費について質問をしてまいります。若者・女性就業支援事業についてですが、平成２７年度から女性をなぜ対象に加えたのでしょうか。対象を拡大したのに、予算額は、平成２６年度は若者就業支援事業だけで８,０８５万４,０００円、平成２７年度は女性を含めまして３,９９０万４,０００円と、約半額ぐらいになっております。その理由を教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"この若者の就業支援につきましては、多様な就業支援する中の一部ということでございまして、そうした制度のスキームを切り替えた観点で、対象を女性に広げつつ、事業の実施方式につきまして、研修を受けていらっしゃる間については自己負担も導入したりということで。","voiceIndex":128,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"女性の枠を入れたことを踏まえて、ちょっとそこでお聞きしたいのですけれど、若者の就業の相談のチラシを私はちょっと見せていただいたのですけれど、ここに、小さいのですけれど、女性向けの就業相談の実施という欄がありまして、子育て中の再就職や、家庭と仕事を両立する働き方についてのキャリアカウンセラーが、アドバイスをするというのをお聞きしたのですけれど、この対象は再就職の。","respondent":"山崎ものづくり・経営支援課長","answer":"女性の方対象の就業相談員につきましては、私どもの、女性支援のコーディネーターの非常勤の経費というところで予算化されているものです。委員がおっしゃったとおりです。","voiceIndex":130,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"２０２０年までに指導的地位にいる人の３割を女性にすべきである」という、女性就業の大切さについての声明がございました。女性、本人だけが頑張っても動くことはできずに、やはり家庭も現場も、地域、そして自治体の役割がとても重要だと思いますが、この内容、私がちょっと言葉を引用させていただいたのですけれど、女性の就業に対しての区としての気持ちをお聞かせいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"それと、女性につきましては、やはり結婚なり出産なりということで、一度離職して再就職というようなところが特徴ですので、そうした女性のキャリアを活かした再就職の視点というのが重要だということで、そのあたりに力を入れて支援していくというようなことです。","voiceIndex":132,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"この事業の内容について、少し詳しく触れたいのですけれど、プレス発表の資料の中で、「研修」とありました。ここのところで、カウンセリングの役割は何かすごく重要だと思うのですけれど、ここを教えてください。さっきのキャリアカウンセリングとまた違うのではないかと思いますが、その辺のことをお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"その結果、一致した企業に行っていただいて学習をし、インターンシップをしていただいて、また戻ってくるようなケースもあります。１回で決まるということではなくて、そういったことを繰り返す窓口がカウンセリングというようなことで位置づけているものです。","voiceIndex":134,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"相手の中小企業側の受入れとして、就業支援コーディネーターの派遣というのはとてもよいことだと思いますし、多くの中小企業が利用して活発な求人活動をしていただきたいと思うのですけれど、ここに派遣するというのは区の商工相談員ですか。これは募集をかけて、中小企業の方が自分で希望するのか、それともＰＲをするのか、区のほうのシステムがちょっとわからないのですけれど、お聞きしたいです。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした意味では、既に区のほうでは企業の経営支援などのコーディネーターがおりますので、そうしたコーディネーターが就業支援のコーディネーターも兼ねるというようなことで、就業に結びつける力を十分発揮したいというふうな考えのもとに配置するものです。","voiceIndex":136,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは２６５ページ、猫の不妊・去勢手術費助成と、２９１ページ、都市型観光プラン策定経費についてお伺いしたいと思います。これまで毎年、猫の不妊・去勢手術費用助成は継続している事業ですけれども、その効果について少しお伺いしたいと考えています。それで、もしずっと経年して助成を続けていく中で、数字的なもので何か成果が示せるものがあればひとつ教えていただきたいというのがあります。","respondent":"高山生活衛生課長","answer":"それから最後に助成頭数については、平成２５年度から順次拡大してきてはいるのですが、こちらのほうは助成頭数を、予定数を上回るような申込みがあったということも、一つ効果ということで申し上げることができるかと思います。","voiceIndex":141,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういった衛生的な問題に対して、今回の不妊・去勢手術の助成をすることによって、地域猫がいなくなる、本当にゼロに近い数字になっていくということを、この事業としては目指していかれるものなのか、あるいはこういった地域で起こる、いまだにある衛生上のふんとか尿の問題、においの問題、こういうことに対して区はどのように対応しようとお考えをお持ちであるのかお聞かせいただきたいと思います。","respondent":"高山生活衛生課長","answer":"ふん尿の問題につきましては、不妊・去勢手術に加えまして、地域猫活動ということで、定時定点給餌ということで、決まった時間に決まった場所で、決まった顔ぶれを確認しながら餌をやるといったことも推奨されているのですが、そういったことによって。","voiceIndex":143,"id":"exchange-065"},{"speaker":"塚本委員","kind":"提案","question":"そういった取組みで、本当に目指すところが地域猫ゼロにというところで実現できればと思いますけれども、なかなかやはり、この間ずっと地元でそういった取組みを見てきた者としては、減ってはいるけれど、あるとき突然また子猫がいるというようなこともあるので、やはりもう一歩踏み込んだ施策として、この前、我が会派から、餌やりに関する条例化の提案等もございましたけれども、そういった。","respondent":"高山生活衛生課長","answer":"やはりこれは地域によって、お話を伺うと、１００通りのそれぞれのお困り事がございまして、条例で一律に規制することが果たして最適かということもありますので、そういった意味では、地域のそれぞれの個別の相談に個別に対応していくというこれまでのスタンスということは。","voiceIndex":145,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問","question":"２９１ページの都市型観光プラン策定経費についてなのですけれども、プレス発表のほうでは、新・観光アクションプランということで、「品川区の魅力を国外に広く発信する」とか、また、「前回策定以来、大幅に増加している訪日外国人の動向などの新しい視点というようなことも踏まえて今回のプランの策定を目指す」ということでありますが、例えば今、具体的な数字的なところで。","respondent":"米田商業・観光課長","answer":"いわゆる機内情報誌等で、今、日本向けの便の中で周知しているところですけれども、それを持って実際に商店街などのお店を訪れているというようなことで体感しています。","voiceIndex":147,"id":"exchange-067"},{"speaker":"塚本委員","kind":"意見","question":"都市型観光プランということで、荏原地域にちょっと話を移すと、やっぱり商店街というのが一つの観光資源としてこれまでも言われてきたと思います。今回の新たな都市型観光プランということにおいても、外国人に対する観光資源としての商店街の価値というものが、引き続き大きな観光資源として考えられていくものなのだろうと想像しますけれども、その点について最後にご答弁をお願いいたします。","respondent":"米田商業・観光課長","answer":"これまでも、こちらのほうにいらっしゃる外国人の方へ、商店街ということを意識した宣伝も行っております。引き続き、商店街とも連携して、多くの方が商店街に訪れる、品川区といえば商店街ということで、今後もやっていきたいと思います。","voiceIndex":149,"id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"２つ質問したいと思います。１つは２６７ページの、子どもの各種健診と保健指導について、もう一つは２６９ページの健康塾についてです。それで、いろんな相談だとか対応していただいていると思うのですけれども、各種の乳幼児の健診や健康相談、栄養相談など、そういう部分で、子どもの育ちに遅れがあるのではないかと気がついたときにはどのような対応をしているのか、まずそれを伺いたいと思います。","respondent":"太田品川保健センター所長","answer":"健診で発達の遅れ等が見つかった場合には、医療機関のほうに精密健診を受けていただくようにご紹介しております。","voiceIndex":152,"id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"例えば、身体機能が普通に育っていないのではないかとか、あるいは目の動きだとか、さまざまな身体のいろんな器官の部分での遅れがあったときには、そういう精密検査等々もあるのですけれども、それは本当に大事なことだと思って、できるだけ早く発見して、早く専門の機関につなぐというところは本当に重要なことだと思うのですけれども、それだけではなくて、いろいろな部分で、例えば心の発達だとか。","respondent":"太田品川保健センター所長","answer":"それで気になるお子さんは、保健所の心理経過観察グループで発達を促したり、親御さんの受入れを促したりしております。平成２４年度の３歳児健康診査の心理相談の実施率は７.３％の４８５名です。","voiceIndex":154,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"なかなかそういう、決して少なくない数字だと思うのです。そういうコーディネーターの役割が、保健師、保健所にはあるのではないかと思っているので、その点についての保健所・保健師の役割がどういうものなのかというのを一つ伺いたいと思います。あるとしたら、私はしっかりとした適切な対処が必要だと思っているのですけれども、その辺については実態はどうなのでしょうか。","respondent":"太田品川保健センター所長","answer":"子どもの貧困の問題で、健康面とか親御さんの心理的な子育ての面に影響があるかですが、それに関しましては、やはり虐待の観点から考えますと、経済的に困難な状況にあると虐待に至りやすいということは一般に言われていることだと思います。","voiceIndex":156,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"ないのか、あるのか。それから、次の健康塾について伺いたいと思うのですけれども、健康塾は、事務事業概要で見ると、２２会場で実施されているということなのですけれども、実施回数と参加状況についてまず教えていただきたいと思います。希望者が多いのか少ないのか等々の、どういうことかわからないので、もしそちらの設置の理由があったら教えてください。","respondent":"太田品川保健センター所長、川島健康課長","answer":"ただ、問診や診察の中で保護者から訴えがあった場合には適切に対応し、そして関係各課とも今後も連携していきたいと考えています。１,８５１人、平成２５年が１,９５５人、平成２６年度が２,０３２人という形で人数が伸びてきているということで、順次、会場もシルバーセンター以外に増設してきた経緯があるので、このような会場数になっているです。","voiceIndex":158,"id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"それについて見解をお願いします。これはもう共通の願いですから、そういう中で希望が増えるのは当然だと思うのです。健康に過ごしたいという、これは共通の願いだし、区も在宅重視と言っているのであれば、本当にいつまでも在宅で暮らせるように、健康で暮らせるように、そういう基本的な体制はとるべきだと思っているのですけれど、その辺についていかがでしょうか。","respondent":"太田品川保健センター所長、川島健康課長","answer":"健診での問診をこれまで以上に丁寧に行いまして、収入のこと等を聞くのは大変プライバシーの問題もありまして、かえってこちらの支援から遠ざかってしまうということもありますので。会場の空きに少しばらつきがあるということで、それから講師のトリム体操連盟のほうも、なかなか講師を増やすという体制はとりづらいということで、現状のままやっていかざるを得ない部分もあるのかと考えています。","voiceIndex":161,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"保健所のほうの対応は、ぜひ早急にそういうふうにしていただきたいと思います。そして、ぜひ実態をつかんで、適切な処遇ができるようによろしくお願いしたいと思います。健康塾のほうは、ぜひ私は、必要なところは増やすと、そういう角度で取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-074"},{"speaker":"井上委員","kind":"質問","question":"私からは、２６１ページの定期予防接種と２６５ページの猫の不妊・去勢手術費助成についてお伺いいたします。定期予防接種のところでは、ヒトパピローマウイルスワクチンについて３点伺います。１つは、２０１５年度の予算額が幾らで、昨年との増減額をお示しください。２つ目は、厚生労働省の積極的勧奨中止について何か進展があれば情報をお知らせください。そのリーフレットにこのような文面があります。","respondent":"佐藤保健予防課長","answer":"私どもも一応、国の認識に基づきましてご説明を申し上げているところです。","voiceIndex":166,"id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"」 こういった声をいただき、そして国の調査だけではなく、区でも独自に後追い調査をしてほしいとの要望がありました。こういった問題で、明らかに健康である方たちに症状が出ているということで、重症事例があったかないかということではないと思いますので、件数が多い、少ないということではなくて、区が直接、後追い調査をすることをもう一度求めますけれども、見解を伺います。","respondent":"佐藤保健予防課長","answer":"そういったことも含めまして、現在、専門家でも意見の分かれるところですので、国においての科学的根拠に基づいた検証が行われることを私どもは待ちたいと考えております。","voiceIndex":168,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"今、接種してから経過してでないと、そういったことがわからないという事例がたくさん出てきていますので、自治体としてもそういった子どもたちに優しく向き合っていただきたいなと要望いたします。この事業はお金をつけても担う人がいないと成立しないので、こういった活動をされている方たちに対してどのような対策を区は考えているでしょうか。","respondent":"高山生活衛生課長","answer":"いわゆるモデル地区ということで、町会ぐるみの取組みに関しても支援するような形でやっておりますので、そうした意味では、引き続き、個人のみならず地域、町会・自治会を対象とした支援なども継続してまいります。","voiceIndex":170,"id":"exchange-077"},{"speaker":"横山委員","kind":"確認","question":"私は２９１ページの観光協会運営費補助、海外日本博出展、都市型観光プラン策定経費について確認します。は観光協会運営費補助からお伺いいたします。しながわ観光協会のウエブサイトの外国語対応の充実についてお考えをまずお聞かせください。","respondent":"米田商業・観光課長","answer":"その中で必要に応じて外国語の表記を増やしているというようなことではありますけれども、委員ご指摘のように、外国の方が訪れる可能性の比較的少ないものについては、まだまだ多言語化対応ができていないというのが現状ですので、この辺については、今後も見据え。","voiceIndex":173,"id":"exchange-078"},{"speaker":"横山委員","kind":"質問","question":"２０１４年１０月２８日の区民委員会での都市型観光に関するご説明の中で、マレーシアやインドネシアということで、これはムスリム旅行者の誘客強化事業ということで、国でも初めて取り組んだと伺っておりますという記載があるのですけれども、品川区におけるムスリム旅行者の誘客強化事業についても、ハラールの認証取得、ムスリム旅行者に配慮した食事や礼拝スペースの確保など。","respondent":"米田商業・観光課長","answer":"この辺については東京都も今、ムスリム旅行者のおもてなしのガイドを出しておりますので、引き続き、数は多くはないのですけれども、継続して取り組んでまいりたいと思います。","voiceIndex":175,"id":"exchange-079"},{"speaker":"横山委員","kind":"質問","question":"最後に、都市型ＭＩＣＥおよび都市型観光の推進を図るために、国際会議の誘致やユニークベニューを検討してみてはいかがでしょうか。時間がないので、国立博物館ですとかロンドン自然史美術館などが、ユニークベニューハンドブックでも紹介されているのですけれども、いろいろ課題はあると思いますが、課長のお考えをお聞かせください。","respondent":"米田商業・観光課長","answer":"なかなかすぐには結びつかないと思いますが、そういうところから、あるいは先ほど来ありますように、いわゆるビッグサイト、ああいうところからの誘客をきちんと図ってまいれるようにこれからも努力を続けていきたいと思ってあります。","voiceIndex":179,"id":"exchange-080"},{"speaker":"大倉委員","kind":"質問","question":"私からは２７７ページのボトルキャップ回収運動。少し大きくなってしまうのですが、品川区のエネルギーの活用の考え方についてちょっとお伺いできればと思います。例えばペットボトルの横にキャップ回収場所というのをつくってやっていくのか、それとも、そもそもペットボトル回収とは別にキャップだけの回収ボックスとか、そういった取組みについて教えていただければと思います。","respondent":"三ツ橋環境課長","answer":"は庁舎から取り組みまして、その後、ほかに展開していこうと考えています。","voiceIndex":182,"id":"exchange-081"},{"speaker":"大倉委員","kind":"質問・要望","question":"町会等でも、有志や町会の方々がペットボトル、キャップを集めて、ほかのそういった施設に持っていって活用するというような取組みもやっていますが、品川区で集めたペットボトルはどこに行って、そのキャップはどうなっていくのかというのを教えていただきたいのと、町会のそういった活動と連携ができるのかどうかというのがわかれば教えていただければと思います。","respondent":"三ツ橋環境課長","answer":"このペットボトルのボトルキャップがどのようになっていくのかですけれども、まずボトルキャップを回収し、そして、こちらはたくさん集めないといけませんので、実は４５リットルの袋で７袋ぐらい、結構集めないと活用できないですので、まずは回収し。","voiceIndex":184,"id":"exchange-082"},{"speaker":"大倉委員","kind":"意見","question":"かなり多くのキャップが必要ということで、集めて活用していくことが１つ目的にあると思うのですが、多くのものを集めるときに、例えば区のエコ推進のイベントであったり、そういったところでも、何か区でやっていますよという発表だったり広報というのができると、品川区もこんな身近な取組みから始めているのだという意味ではアピールできるポイントであるかと思っているので。","respondent":"三ツ橋環境課長","answer":"実際にイベント等で実施するかというのは、まずは庁舎内に回収箱を置きましてやっていくというように考えております。","voiceIndex":186,"id":"exchange-083"},{"speaker":"大倉委員","kind":"意見","question":"例えば、そうした品川区で行っている身近にできる環境の取組みというのも広報することも、区民として、ああ、こんなことをやっているのだという、品川区役所を身近に感じる一つかと思っているので、広報も、こんな働きをしてやっていますよというのと、あとキャップを入れていく側からしても、例えばこれだけ集まって、こういう形になって、今それが何になりましたというような見える化というか。","respondent":"三ツ橋環境課長","answer":"ボトルキャップにつきましては、やはりＣＯ２の削減というものも回収することで重要になってくると思われますので、そちらにつきましても検討させていただきたいと考えています。","voiceIndex":188,"id":"exchange-084"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区のエネルギーの活用というか、環境計画においても第二次環境計画をまとめて、５つの重点プロジェクトということでさまざま取り組んでいると思いますが、特に自然エネルギーの活用について、かなり重要な部分として位置づけていると思いますが、こうした自然エネルギーを活用する企業への支援というのが。","respondent":"三ツ橋環境課長","answer":"水素エネルギー活用につきましてですが、非常に金額的にも高いということを、いろいろなものがありますけれども、東京都の取組み、また国の取組みなどを考えながら、それらのことをいろいろ踏まえながら、区としてどのようなことができるか等、検討してまいりたいと考えています。","voiceIndex":190,"id":"exchange-085"},{"speaker":"大倉委員","kind":"質問","question":"今回、その事業も非常に好評で、学研に行っていろいろ皆さん見ることができて、区の職員も行ったと伺っていますが、どういったところがよかったのかというのと、今後、学研以外にも再発見ということでいろんなところで取り組んでいくと思いますが、なかなか探していくのも大変なのかなというのもあるのですが、探していく大変さがある中でも、地域という部分で言うと。","respondent":"三ツ橋環境課長","answer":"そのようなものがありましたので、非常に好評でございました。今後も、こちらは環境情報活動センターに環境学習講座という形をとらせていただきまして、区内の事業所などをピックアップした中で取り組んでまいりたいと考えています。","voiceIndex":192,"id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"区の職員も行って、いろいろすばらしい取組みがあったという部分で言うと、品川区の庁舎内でも何か活用できるのかなといったときに、多分、先ほどの透明の見える化されたキャップの回収箱とか、まさにそういうところだと思いますので、これからもそういったところがあれば、ぜひ取り組みながら活かしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-087"},{"speaker":"こんの委員","kind":"提案","question":"事業概要はお聞きしました。今回、これに踏み切った理由というところを教えていただきたいと思います。それから、２９１ページの就業支援ですけれども、若者・女性の就業支援、これは先ほどもほかの委員から質問がありましたけれども、私も去年の第３回定例会のときに、ママ・インターン事業を提案させていただいた。こうしたことは、この国の予防接種法を踏まえてどのようにお考えになりますでしょうか。","respondent":"三ツ橋環境課長、山崎ものづくり・経営支援課長、佐藤保健予防課長","answer":"現在、いろいろな、区民の方からのお問い合わせもあり、また今回、区独自の環境マネジメントシステムの運用を来年度から実施いたしますけれども。若者・女性就業支援事業です。企業に実習に行った場合、技能習得助成金の支給を逆にするです。参加者の自己負担という意味ではございません。このロタウイルスワクチンにつきましては、２０１１年に日本では承認されておりますので、まだ数年しかたっていないという状況の中で。","voiceIndex":196,"id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"それで、どうなのでしょうか。それまでの流れというところで、いわゆる季節風のインフルエンザのほうも特にそうなのですが、毎年受けなければいけないというところを、ロタウイルスも同じことですけれども、財政的にというところもあるのでしょうけれども、かかってから治療する医療費と、その前に予防接種する費用と、そちらをどういうふうに見るかというところではどうでしょうか。","respondent":"佐藤保健予防課長","answer":"ただ確かに、かかった後で治療するよりも予防したほうがというお考えはもちろんあろうかと思いますけれども、やはりインフルエンザワクチンの効果、それから集団に対する効果も含めて、そういったこともバランスよく考えなくてはいけない点ですので、もう少し科学的に。","voiceIndex":200,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"国の動きも注視していただきながら、できるだけ、高齢者の方に限って今、インフルエンザは定期接種になっておりますけれども、国の流れを待っているとというところも１つ念頭には置いてくださっているとは思いますが、そこのところを重ねてお願いをしておきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-090"},{"speaker":"渡辺委員","kind":"質問","question":"私は、２９３ページ、消費者関係のところ、あと２９９ページ、ものづくり企業立地継続支援、そして２９１ページの新・観光アクションプランの点から伺っていきます。その辺は踏まえられているのか、あるいは柔軟に対応されているのか、まず伺いたいと思います。もう一点、消費者を守る観点で伺います。特に今回、全部に共通しているのは、地域力を頼る。この点をどう考えられているのか。","respondent":"山崎ものづくり・経営支援課長、米田商業・観光課長","answer":"そうしたところで、工場の改修の部分は環境問題に対応するサッシの二重化ですとか、そういったことと、それから区内でなかなか土地を探してというケースは非常に困難な側面がありますが、そこの部分を行って。区としても、こういったものを少しでも取り込めないかというようなことは考えつつ、現在、国民生活センターでメール配信サービスというようなことで、タイムリーな消費者被害の状況であったり。","voiceIndex":204,"id":"exchange-091"},{"speaker":"渡辺委員","kind":"提案","question":"金額のことであれ、規模によって違うのだと思ったときに、やはりそれなりに補助率を、ありがたいはありがたいのですが、何でしょう、きっかけづくりにつながるかどうかというのはあったものですから。どこかに委託する。そうすると、今かかわっている方々、あるいはこれから、それだったらという大きな導線になるのかという思いで申し上げているので、一つの提案としてお考えをお聞かせください。","respondent":"米田商業・観光課長","answer":"東京都のほうも今後５年間ということで、オリンピック・パラリンピックまでを見据えた観光のプランというものを定めておりますし、現状といたしましては、これまで１０年間定めてまいりました観光アクションプランの成果を検証しつつ。","voiceIndex":207,"id":"exchange-092"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それでここのリニューアルで、今、策定のところで委託される中で、一つ要望的なものになりますが、第三者目線というのを最近すごく意識しました。この辺の専門性、プロフェッショナルの養成というのはどうお考えかと。逆の立場で考えれば、僕らも行政関係は、必ず検索もネットではしますし、特に年代がいかれた方ほどそうかなという気もしているので、その辺の行政の労力のかけ方もあわせて伺います。","respondent":"米田商業・観光課長","answer":"そういう中で感じて帰ってきたということでは、いわゆる行政とのタイアップがあったらもっとうまくいっただろうというようなことでのご意見もありますので、そういった意味では、品川区あるいはしながわ観光協会といったブランドを。","voiceIndex":209,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"２８９ページの中小企業センター等運営費。ここは１階のロビーがあると思うのです。２つ目が、２６５ページの猫の不妊・去勢手術費助成。幾つか質問がありましたけれども、私からは、動物虐待と凶悪犯罪の関連性からお聞きしたいと思います。それと、捕獲器は何台ありますか。そして助成金です。ですから、品川区内の動物病院の中でも手術料金がばらばらである。そこの辺の考え方をお聞きしたいと思います。","respondent":"米田商業・観光課長、高山生活衛生課長","answer":"こちらについては引き続き、そちらの課との連携を深めて、今後検討してまいりたいと思ってあります。経年で見てまいりますと、平成２４年度で申しますと４８９頭、平成２５年度で申しますと５３５頭、平成２６年度については年度途中ということもございまして、１月末の数値として３７９頭ということで。","voiceIndex":212,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"協力は、品川区も助成金等々があるわけですから、やはりやっていただきたい部分があると思うのです。それで、安いところがあるのだから、それを品川区内・区外限らず許可すればよろしいのではないでしょうか。捕獲器は６台。暴れます。そうすると、ほかの所管、地域活動課もしくは教育関係も、これは非常に密接な関係があるのではないかと思うのですが、その関係性についてもご見解をお聞きしたいと思います。","respondent":"高山生活衛生課長","answer":"病院ごとにいろいろな経営方針などもありますので、一概に全てにおいて獣医師会加盟の病院が協力的ということではないということは承知するところです。","voiceIndex":215,"id":"exchange-095"},{"speaker":"向委員","kind":"質問","question":"それと環境のほう、ミュージカルなのですけれども、こちらも新規事業ということで、中身をちょっと見ていくと、出演者謝礼１００万円ということで計上されているようなのですが、ただ、中身を詳しく見ると、台本とか楽曲の企画・制作、あと劇団等に協力を依頼するとか、結構内容は盛りだくさんで、これを考えていくと、出演者のギャラとか云々とか、脚本家の先生など、もしそれなりに依頼されるのであれば。","respondent":"米田商業・観光課長、三ツ橋環境課長","answer":"それで、その取組みを通じて、商店街の方々にも国際化について考えていただく契機となるような形で事業を計画・立案して商店街連合会と進めていく。このように考えているところです。ただ、ギャラなどは非常にいろいろな状況になってくると思いますので、そちらもいろいろ考えてまいりたいと考えています。","voiceIndex":218,"id":"exchange-096"},{"speaker":"向委員","kind":"質問・要望","question":"市民が参加するミュージカルというのは、全国的に見ても、実施している自治体もあって、例えばこの間は、つい先日、徳島市のほうでは、劇団四季の徳島出身の方に出演もしていただき、もちろん市民も、そして市長も出演するというようなミュージカルをしている自治体があって、せっかく品川区はこういった立地にありますし、もちろん劇団四季もありますし、それ以外にたくさん著名な方。","respondent":"米田商業・観光課長、三ツ橋環境課長","answer":"イベントの関係ですけれども、こちらについてはいわゆるイベントのブースということで、数名の外国人の方を呼んで、３商店街でというようなことで、今、事業のほうは計画していますが、これも今後のしかけ方によっては。魅力的なミュージカルにするためにはどのようにしたらいいのかということを、劇団などにも協力を仰ぎつつ、また区民参加も検討しつつ実施してまいりたいと考えています。","voiceIndex":221,"id":"exchange-097"},{"speaker":"向委員","kind":"質問・要望","question":"あと五分ほど、衛生統計のほうと区民健康づくりプランのほうでちょっと触れさせていただきたいのが、衛生統計調査を見ると、幾つか区民の死因、これは日本国民の死因と直結するような、わりとそんなに大きく違うデータは出ていないと思うのですけれども、区民の命にかかわる病因となっているような病気、上位三つ、四つでも、ちょっと教えていただければと思います。","respondent":"川島健康課長","answer":"多分、がんも肺炎も高齢化が原因ではないかということなので、そういう分析をしております。がんの予防や治療が進歩しましたら、さらに肺炎による死亡がもっと割合上、増えてくるのではないかという考えです。","voiceIndex":224,"id":"exchange-098"},{"speaker":"向委員","kind":"質問","question":"時間がないので、ちょっと今回はがんのほうについてお尋ねします。介護保険になると４０歳以上などで、その中でも若い世代は特定疾病がある場合、がんなどがあれば使えるのですけれども、このあたりは区として、今どういう認識でお考えがあるでしょうか。お願いします。","respondent":"川島健康課長","answer":"今ご案内のありましたとおり、がん診療連携拠点病院というのが全国に３９７カ所あるそうなのですが、そのうち品川区内には昭和大学病院とＮＴＴ東日本関東病院の２カ所が拠点病院で、がん患者のリハビリテーション料が算定可能な病院というのがＮＴＴ東日本関東病院と。","voiceIndex":226,"id":"exchange-099"},{"speaker":"向委員","kind":"質問・要望","question":"私が申し上げたいのは、リハビリをもう少し、区としてもできることはなかなか現時点で厳しいのは私も重々承知はしております。なので、そのあたり、区としてできることは少ないかもしれないのですけれども、うまく連携を図っていただければと思いますので、以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-100"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は衛生費で、２６４ページ、保健指導費。それから健康になるのか、薬事衛生なのか、そこら辺で１点。それから２９５ページあたり、産業経済費の中の商店街にぎわい創出事業。時間があれば２７７ページ、緑化に絡んでちょっとお聞きしたいと思います。ある会で、ちょっとその時期では早いのではないでしょうかというお話をいただいたのですが、離乳食関係のお話を教えていただければと思います。","respondent":"太田品川保健センター所長、川島健康課長","answer":"それ以外にも、１歳６カ月児と３歳児健診でも、幼児食についての相談、それからその前の７カ月から１２カ月についてはホームページ上で離乳食のアドバイスを載せておりますし、電話相談等でも個別に対応しております。それから都からは、各区の薬物乱用防止推進協議会宛てに、年十数万円の委託金が支払われるということなのですが、指導員からはちょっと少ないという話を聞いておりますので。","voiceIndex":230,"id":"exchange-101"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その辺をどう考えたらいいかというお話がありました。例えば、こういう講習会をやりますということで児童センターに持っていくと、そこですぐに、児童センターの中に伝わっていないような状況があったということも前に聞いたことがあったのですが、その辺の連携体制は問題ないでしょうかということをもう一回確認したいと思います。","respondent":"太田品川保健センター所長、伊崎子育て支援課長、川島健康課長","answer":"離乳食の教室の開始につきましては、やはり五、六カ月から離乳食を開始しますので、そこでまず最初に行うというのはやはり大切だと考えています。以前、その際に、実習の方法についていろいろと行き違いがあったこともございましたが、今は事前にきちっと調整をするようにいたしまして。こちらの薬物乱用防止指導員の支援につきましては、やはり現行のようなスタンスになろうかと考えておりますが。","voiceIndex":233,"id":"exchange-102"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"離乳食で、私が栄養士の話を取り違えている部分もあるかもしれないので、先方とよく打ち合わせしていただいて、ご要望に沿って進めていただきたいなと思いますので、よろしくお願いします。それから、先ほど別のほうで気になっていた商店街の関係で、にぎわい創出で、さんま祭りとちょっとお言葉が出たので確認をさせていただきたいと思いました。今年は目黒が使えないですよね。","respondent":"米田商業・観光課長","answer":"今年度の実施につきましても、いろいろ昨年度までとは状況が違うという中では、早期に地元商店街と連絡をとりまして、状況にもよりますが、円滑に進めていける上でのご支援はしますというようなことで、とにかく情報をいただいて。","voiceIndex":237,"id":"exchange-103"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、ぜひ品川区との交流を続けていくためにも、うまく調整していただきたいと思いますので、よろしくお願いします。これは何でもそうですけれど、先に住んでいる人のところに後から行って、よく、もともとやっているところに対して周りから言うことを言いますけれど、その逆の形になってしまうので、この点はどういうふうに考えたらいいのか、ちょっとそれを１点教えていただければ。","respondent":"山崎ものづくり・経営支援課長","answer":"区内の敷地を移るという意味の移転もあります。それから、昨年、実際に事例がありましたけれども、例えば区立の工場アパートなどの空きがありまして、そちらのほうに入居のために移転するというようなケースなどを想定しているものです。","voiceIndex":239,"id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。区内工場アパート、広町とか鮫洲のほうとかありますけれど、そういうイメージでよろしいですね。わかりました。それと、先ほどの本の中に、よく今まで、「産学公」から、産学公に金融機関を入れて、「産学公金」と言ったのか、そういう考え方がまた出てくると。区として、金融部門に関してどういうふうに考えているのか、そこら辺も教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"それに加えまして、最近は地元に密着した金融機関として、地元の小規模事業者を中心とした企業を応援して、やはりエリアとして、そうした小規模事業者の持続的発展により地域も活性化していくのだというようなところで、いろいろな提案をいただいて。","voiceIndex":241,"id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひその辺をうまく進めていっていただきたいと思います。やはりこれは少し形としてうまくないのではないかと思います。向こうに進出企業が少ないからこうなってしまうのかもしれないのですけれど、やはり１年間として１社で長くずっと使ってくれているのはわかっていますけれど、やっぱり数社入らないと、事業としてはおかしな形になってしまうのではないかと思うのですが、この辺はお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"ＪＥＴＲＯのほうと連携しまして、ＪＥＴＲＯのブースで、その上に私どもはありますので、紹介していただいたりというようなことで、利用の促進といいますか、活用いただける企業のＰＲも含めて努めてまいりたいなと考えています。","voiceIndex":243,"id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"サポートセンターの内容はわかります。ちょっともう１点、緑化の関係で、今年、緑と花のあるまちづくりというのが、ボランティア団体は同じで金額がちょっと増えていたのですが、ボランティア団体の中から、やっている場所等に、そこは水もないよなどというクレームがつけられたこともあったのですけれど、これはどういう形の金額増加になるのか教えてください。","respondent":"多並公園課長","answer":"この拡大を図りたいということで、来年度の予算の中で委託費という形で、また地元に入りながらもう少し拡大するための講習会などを進めながら、よりボランティア活動を進められたい方々が増えるような形で取り組んでいきたいと考えているところです。","voiceIndex":245,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、不妊治療費の助成事業についてお伺いしたいと思います。今回、男性の不妊治療助成に関することをちょっとお聞きしたいのですけれども、文京区ですか、男性の不妊検査費用として１万円を助成する制度が、今年の４月から始めると新聞で見ました。そこで、品川区では、男性不妊治療の助成はどうなっているのか、現状と今後の見通しですか、教えていただきたいと思います。","respondent":"川島健康課長","answer":"男性の不妊治療助成に関しましては、品川区のやっております一般不妊治療助成事業の中でも、対象を夫婦としておりまして、従前から男性についても一般不妊治療に係る検査や治療にかかった医療費の自己負担額の半額を、１０万円を限度に助成しているということですので。","voiceIndex":248,"id":"exchange-108"},{"speaker":"山元委員","kind":"質問・要望","question":"私の勉強不足で、９年前からもう男性にも品川区は助成しているということでありましたけれども、ここで９年間でご夫婦で助成制度を受けていた方もいらっしゃるかと思いますけれども、そのうち、男性ももちろんなのですが、ご夫婦で助成を受けていた人数、またその助成制度を受けて赤ちゃんができた人数がもしわかれば教えていただきたいと思います。","respondent":"川島健康課長","answer":"助成を受けた方の数が、順番にいきまして平成２４年度が６５３件、それから平成２５年度が７２６件、平成２６年度が７９０件ぐらいになるだろうという見込みで、順に、妊娠したということをこちらでもアンケートで追っておりまして、平成２４年度からいきますと１３７件。","voiceIndex":250,"id":"exchange-109"},{"speaker":"山元委員","kind":"質問・要望","question":"とてもうれしいことでありますけれども、また実は、ある報道をテレビで見ますと、不妊治療に当たって、その原因というのですか、４１％は女性にあるという。うちはすっぱ抜かれたかなと、そんな感じはするのですけれども、そうではなくて、やっぱり周知の方法にもうちょっとアピール性が必要だったのかと思いますが、今後の周知方法というか、何かお考えがあれば教えていただきたいと思います。","respondent":"川島健康課長","answer":"かなり件数が増えてきておりますので、周知効果は今までのままでも高かったのだろうとは思っているのですが、夫婦で使える仕組みだというところを、もしかすると少し強調したらいいのかと、今、考えております。","voiceIndex":252,"id":"exchange-110"},{"speaker":"山元委員","kind":"意見","question":"それは今までのことで、今後何か周知方法として、品川区として今までと違った何かアピール性のあるもの、何かお考えがありますか。","respondent":"川島健康課長","answer":"少し研究というか、させていただければと思います。今ちょっと、ぱっと思い浮かばないです。申し訳ございません。","voiceIndex":254,"id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"最後になります。やはり不妊治療というのは大変お金のかかることで、文京区では１回の治療につき５０万円以内、そして最大で２５０万円まで融資するということでありますけれども、品川区では、特にご夫婦で治療を受けるとなると、かなりの負担があるかなと思いますが、その辺、品川区としては融資のお考えがあるかどうかお聞かせいただきたいと思います。","respondent":"川島健康課長","answer":"現状、不妊治療に係る融資というのは区ではしておりませんが、現在の一般不妊治療の助成が所得制限がないということが、かなり経済的には助かるのではないかと考えております。","voiceIndex":256,"id":"exchange-112"},{"speaker":"山元委員","kind":"質問・要望","question":"２６５ページのほうの猫の不妊・去勢手術助成についてお聞かせいただきたいと思います。今、我が会派の塚本委員はじめ、さまざまな猫の不妊、また去勢のお話がありました。そこで、区は餌をやっている方を掌握しているかどうか、またもし掌握しているのであれば、その対応ですか。無断というのですか、地域猫に餌をあげている方たちの状況をつかんでいるかどうか教えていただきたいと思います。","respondent":"高山生活衛生課長","answer":"問題が発覚・発展しているようなケースについては、実際に保健所のほうにもご相談が寄せられておりまして、何年にもわたって仲裁というような形で粘り強く職員が双方の意見を聞いてお話をさせていただいて。","voiceIndex":258,"id":"exchange-113"},{"speaker":"山元委員","kind":"質問","question":"これは区にお願いしていいのかどうかわからないのですが、一言、間をとっていただくではないのですが、上手にスムーズに流れる方法を考えていただければ、たかが猫といえど、されど猫でありまして、やはり猫のことで人間関係もうまくいきますので、その辺、もう少し区としての、お願いするのはちょっとあれなのですが、間を取り持つというか、そういうことはできることでしょうか。いかがですか。","respondent":"高山生活衛生課長","answer":"時には地域センターの所長でありますとか、地域の町会長なども交えまして、よりよい解決方法を模索しています。","voiceIndex":260,"id":"exchange-114"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、２５９ページの保健衛生総務費の公衆浴場についてと、あと２６３ページの成人歯科健診について伺いたいと思います。公衆浴場についてですけれども、公衆浴場は、年々ちょっと減ってきてしまっている現状があると思うのですけれども、現在の公衆浴場数と、減ってきている原因、理由を教えてください。","respondent":"川島健康課長","answer":"区内の公衆浴場の数、件数のご質問です。今現在、結論から申しますと、２９件、浴場数があります。平成元年には８５件ございましたので、かなり減少しているということです。","voiceIndex":264,"id":"exchange-115"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした浴場の減少は、廃業してしまった方の暮らしや、また利用してきた区民に大きな影響が起きると思いますけれども、こうした浴場減少を食い止めていく考えは区にあるのか、そして今後どのような考えがあるのかを伺いたいと思います。","respondent":"川島健康課長","answer":"区では、公衆浴場は貴重な地域資源、観光資源であるというふうな認識で、少しでも多くの公衆浴場に、いつまでも地域で愛され続け、存続していただきたいと考えておりまして、その姿勢につきましては、昨年の１０月補正で。","voiceIndex":266,"id":"exchange-116"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"浴場への設備改修などは私たちも求めてきましたので、本当によかったなと思っているのですけれども、今回の予算で、南品川シルバーセンターに浴場設置がされると、とても本当に地域の方に喜ばれているのですけれども、プレス発表では、シルバーセンターに浴場設置がされる目的として、「近隣に公衆浴場のない南品川地区において、日常生活における不便さの解消を図り。","respondent":"川島健康課長","answer":"ただ、例えば公衆浴場が周りにないところをどうするかなどという、ハード的な設備を何かつくるなどというのは厳しいと考えております。","voiceIndex":268,"id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問","question":"南品川シルバーセンターへの浴場設置は本当に喜ばれています。しかし私は仕事をしているので、６０歳以上ですけれども入れませんと、寂しく語られました。南品川もやっと１件設置されますけれども、困難地域の把握、また困難を持つ区民の実態把握はしているのか伺いたいと思います。そして困難な地域・区民に支援が必要と考えるのですけれども、区としての考えを伺いたいと思います。","respondent":"川島健康課長","answer":"銭湯が全くない地域というのは当然把握しているのですが、やはり公衆浴場とはいえ、一企業の経営支援のような形にもなると思いますので、どこまで区がどのような形で足を踏み込めるかという部分は非常に難しい問題もあると認識しております。","voiceIndex":270,"id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、実態を把握するための実態調査を行ってほしいと思います。ですので、そういった意味でも実態調査を行って、そして具体的な対策を打っていってほしいと思います。お風呂が設置できなくても、遠くのお風呂まで歩いていかなければいけないという区民に対しての移動のための足の確保や、あとは今ある浴場へのさらなる支援などを求めたいと思いますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"はソフト的な部分で、浴場組合のやるいろんなイベントを支援するですとか、そういった形もあろうかと思うのですが、少し公衆衛生上の観点からいくと、健康課のカテゴリーから外れるのかなというところもありますので、私どもの健康課でできる支援というのが。","voiceIndex":272,"id":"exchange-119"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど、公衆浴場が地域の大事な資源だと、存続させていきたいということを伺いました。お風呂の困難地域への支援をぜひとも行っていただきたいと強く要望して終わりたいと思います。それで、成人歯科健診のほうですけれども、今回、クリーニングが入ったということですけれども、クリーニングを入れた理由と、あとクリーニング分にかかる予算がどれぐらいになっているのかを伺いたいと思います。","respondent":"川島健康課長","answer":"平成２３年度から順に受診率が、６.４６％、６.９９％、６.９１％と、７％未満が続いていたということもありまして、何とか受診率が上がるために方策を打てないかということで、クリーニングを実施するということになったです。","voiceIndex":274,"id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"予算のほうもちょっと教えていただきたいのと、あと品川区は４０歳から５歳刻みで７０歳までの健診となっています。５歳刻みの根拠を改めて伺いたいと思います。それから、品川区の世論調査を見ましても、定期的に歯の健診を受けているという区民が、定期的に身体の健康診断を受けているというのと比べて、歯のほうがやっぱり半分以上少ないのです。","respondent":"川島健康課長","answer":"それから５歳刻みの年齢設定ですが、もともと４０歳から５０歳、６０歳、７０歳ということで都の補助金が出てやっていた事業を、刻みを細かくしたというような経緯で、このような事業形態になっているのだと考えております。","voiceIndex":276,"id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと、この５歳刻みというのは、私は以前からずっと、１年ごとにぜひ健診を受けるような仕組みにしてほしいということを求め続けているのですけれども、先日、知人が歯が痛いと言っていたのが、次の日にはもう大きく腫れて、熱が３８度まで上がって、歯も保存できるかどうかというような大変な事態だったのです。ですので、これが５歳刻みというのは遅すぎると思うのです。手遅れになる状況です。","respondent":"川島健康課長","answer":"このクリーニングの導入で、大体３％ぐらい受診率が上がればいいと私どもは見込んでおりまして、まず年齢のことではなくて、今回やるクリーニングのほうが円滑に実施されるということをまず第一に目指すべきだと考えております。","voiceIndex":278,"id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど、１０歳刻みのところを区は５歳刻みで独自でやっているのだということでしたけれども、５歳で刻んでいくということの根拠をちょっともう一回明確にお聞かせいただきたいのですけれども。","respondent":"川島健康課長","answer":"制度を導入した当初というのは、やはり財政負担の平準化などという形の考え方もあったと思いますので、まずこれで受診率が増えるというのは、歯のクリーニングで増えた場合のこともありますので、１年間、歯のクリーニングがどうなるかというのを注視しながら。","voiceIndex":280,"id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"受診率を見ながらいろいろ対策を打っていくということですけれども、世論調査では、定期的に歯科健診を受けているという区民は、１年間で２％しか上がっていないのです。年齢拡大をすることが一番の受診率アップにつながるとおっしゃっていたのです。ですので、ぜひ３５歳からの健診とセットで進めてほしいと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"２８３ページの清掃総務費、２８５ページ、粗大ごみ中継所維持管理費、２点、質問いたします。２８３ページの清掃総務費や、東京二十三区清掃一部事務組合分担金と、平成２７年度の執行が適正に行われるように願っております。そのために何点かお聞きします。品川清掃工場で１月２８日に停止され、２月２０日に再稼働されましたが、まずこれの復旧する経費について教えてください。","respondent":"小林品川区清掃事務所長","answer":"今ご指摘のありました品川清掃工場１号炉の水銀混入ですが、この復旧費につきましては幸い軽微で済み、清掃と点検で約５０万円ほどの経費がかかっております。","voiceIndex":284,"id":"exchange-125"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、血圧計の捨て方等も、病院のほうではやっているというふうな把握をされておりますけれども、診療所でしたり個人が捨てる場合にどうしても混入してしまう。その点についての対策というのはどこまで進められていくのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"これは基本的には全ての医療機関、医師会のご協力を得ながら対応しておりますけれども、引き続きこの趣旨の徹底を働きかけていきたいと考えております。","voiceIndex":286,"id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"それでも発生してしまうということは、今度、収集したものの、工場の中で、さらに水銀が入っている可能性があるものの分別というのは、これは難しいと思うのですが、方法はないでしょうか。それができればこうならないのですけれど、非常にそれは難しいと思うのですが、何かそういう対策というのは工場の中では無理なのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"もちろん工場としても、この水銀も含めた不適正搬入につきましては、適時、検査をして発見に努めておりますけれども、その全量については、なかなか把握し切れないというのが現状です。","voiceIndex":288,"id":"exchange-127"},{"speaker":"本多委員","kind":"質問","question":"品川区事業系ごみ排出実態調査報告書によりますと、「２０２０年の東京オリンピック・パラリンピックを控え、東京都では事業所の建設ラッシュや国内外の観光客増加に伴う事業系ごみの急増などが懸念され、早急な対策が重要課題となっている」と記載されているのですが、こうした事業系ごみの減量化に向けての具体策については、今現在何かお考えがあるのでしょうか。教えてください。","respondent":"小林品川区清掃事務所長","answer":"ここを一気に減量のポイントとしてやっていくことによって総量の圧縮を図りたいというのと同時に、それを事業所にお願いする経過で、各事業所への立入りないしは啓蒙を積極的に進めることによって、資源化の推進とあわせて廃棄物の総量の圧縮を図ってまいりたいと考えております。","voiceIndex":290,"id":"exchange-128"},{"speaker":"本多委員","kind":"質問","question":"よろしくお願いします。最後に、２８５ページの粗大ごみ中継所維持管理費について伺います。粗大ごみを取り扱う作業状況は現在どのようになっていますでしょうか。","respondent":"小林品川区清掃事務所長","answer":"粗大ごみ中継所のお尋ねかと思います。こちらは現在、区内で収集しております粗大ごみを一旦持ち込みまして、その分別と中継をして、積み替えて大型車両で中央防波堤のほうへ搬入する基地として活用しています。","voiceIndex":292,"id":"exchange-129"},{"speaker":"本多委員","kind":"質問","question":"わかりました。それで、東品川中継所の活用については、平成１２年度に都から移管を受けて２０年間ということで、平成３２年度までですから、あと５年になりました。それと、５年後、その後の品川区としての活用の考え方、企画の考え方について教えてください。","respondent":"柏原行財政改革担当課長","answer":"ただ、２０年たったときが、ちょうどオリンピックの開催の目前でございまして、まちづくり、それからオリンピック・パラリンピックに向けた扱い方とか、いろいろ活用の方法はあると思いますので、そういった方向で使っていければというふうなことで検討しています。","voiceIndex":296,"id":"exchange-130"},{"speaker":"高橋委員","kind":"質問","question":"２６７ページのすくすく赤ちゃん訪問事業、健康センター事業費、それから２９９ページの品川産業支援交流施設経費。品川産業支援交流施設のほうからお伺いします。６月の開設がもう間近なのですが、現時点での３階のイベントホールの予約状況や、４階の事務室への入居予定の企業の状況、その企業の特徴などをご説明願います。","respondent":"山崎ものづくり・経営支援課長","answer":"それから特徴の２つ目としては、地域に根差した既存の創業支援センターからの第二成長の受け皿というようなことで、こちらも広町のほう、それから天王洲、西大井、武蔵小山の４企業が第二成長として入居を予定しているという状況で。","voiceIndex":299,"id":"exchange-131"},{"speaker":"高橋委員","kind":"質問","question":"企業のほうなのですが、私はちょっとこの業界は明るくないのですが、かなり有力な企業が内定していると伺っていますが、素人の私でもわかるような形で、この企業の様子を教えていただければありがたいと思います。それから創業支援センターからのつながりという形で、非常に区のほうの施策がつながった好例だと思うのですが、その点についてどのようにお考えでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"こうした内外の企業のさまざまな質の高い交流をこの場で創出してまいりたいと考えているものです。","voiceIndex":301,"id":"exchange-132"},{"speaker":"高橋委員","kind":"質問","question":"素人の私にもわかりました。さまざまな魅力のある企業の交流が期待できますが、ちょっと質問の視点を変えしますが、昨年の決算特別委員会でも指定管理者の話をお尋ねいたしました。こちらは財団法人と民間の株式会社が共同事業体で運営されると伺っています。","respondent":"山崎ものづくり・経営支援課長","answer":"その協定の内容に沿って、先ほど来のような事態に対しまして、区としては事業の継続性が一番大切ですので、必要な措置をしっかり講じていくことになっているものです。","voiceIndex":303,"id":"exchange-133"},{"speaker":"高橋委員","kind":"質問","question":"今ちょっとお話が出ましたが、健康センターのことを伺いたいと思います。そのような形で、今、保養施設と同じような形で運営を、経営方式を変えていく典型的な施設ではないかと思いますが、そのあたりの考え方、健康センターの今後の運営について、こちらは健康のほうの部署か、それとも企画のほうか、ちょっとわかりませんが、伺いたいと思います。","respondent":"川島健康課長","answer":"さらにいろんな経費が削減されるというのはその次についてくるというような形で考えておりますが、おかげさまで平成２６年にまた指定管理を更新しましてからも利用者数が伸びているというようなことが結果としてあらわれているのではないかと考えております。","voiceIndex":305,"id":"exchange-134"},{"speaker":"高橋委員","kind":"質問・要望","question":"利用者数の伸び等ありますが、先ほどお話があったように、効率的な運営や民営化も含めた施設の見直し、新しく指定管理をまた更新したのですが、それも含めて今後検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-135"},{"speaker":"あべ委員","kind":"質問","question":"私からは２５８ページの保健衛生費、特に保健師に関してお伺いしたいと思います。それから２６５ページの猫の不妊・去勢手術費助成、それから３０１ページの品川産業支援交流施設経費、時間があれば２８５ページ、清掃事業について幾つかお伺いしたいと思います。保健衛生費というか保健師なのですけれども、区には今現在３８人の保健師がいると伺っております。品川区のお考えをお伺いしたいと思います。","respondent":"堀越人事課長、高山生活衛生課長","answer":"年間の推移ですけれども、１０年程度前は、３５名というような年もありまして、所管といろいろ必要な人員等の調整等図りながら配置しているという状況です。さまざまな事情で殺処分をせざるを得ない状況もやはり目をそむけてはいけないといったことから、減少している傾向は間違いないのですが、物の言い方としては殺処分減少を目指すといったスタンスにしておりますので。","voiceIndex":309,"id":"exchange-136"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで全国的にも保健師の配置というのは増えてきているようですけれども、品川区として、先ほど１０年スパンでは３５人からという時期もあったということですけれども、やはり今後、認知症の方が増えていくこと等々考えますと、やはり今以上に増やしていく、計画的な増員が必要ではないかということで、お考えをお伺いしたいと思います。","respondent":"堀越人事課長、高山生活衛生課長","answer":"離職の原因は、今ちょっと手元に資料はありませんけれども、そのようなときに若干欠員が生じて、非常勤職員で応急的に対応したという時期がありました。区といたしましても、究極的な姿としては殺処分がゼロであるということを目指すことについては間違いございませんので、そういったことを志向しながら進めてまいります。","voiceIndex":312,"id":"exchange-137"},{"speaker":"あべ委員","kind":"質問","question":"それで、これはまず３０１ページの予算書の読み方なのですけれども、利用料金収入見込額が約９,４００万円、括弧書きで書いてあって、その後に一般会計で約４,８００万円とありますけれども、これは区として、利用料金収入として利用者の方から約９,４００万円の収入を見込み、それが指定管理者に入って、区からも約４,８００万円の一般財源。","respondent":"堀越人事課長、山崎ものづくり・経営支援課長","answer":"今後のことですけれども、先ほどご答弁申し上げましたとおり、今年度、精神保健の分野で、保健予防課のほうに保健師の配置というのを今検討しているところでございまして、そういう中で対応していきたいと考えています。施設のほうです。考え方は委員おっしゃるとおりでございまして、ここで足し込んだ１億４,０００万円余が、この施設の３階と４階の運営経費・人件費も含めたトータルコストというようなことです。","voiceIndex":315,"id":"exchange-138"},{"speaker":"あべ委員","kind":"質問","question":"予約は好調だと聞いているのですけれども、それでも全体として足りない分を区が４,８００万円払うというのは、ビジネスモデルとしてちょっと破綻しているといいますか、せめてとんとんまで持っていくところからのスタートではないかと思うのですが、その辺のお考えはいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"足し込んだ１億４,０００万円余の支出の見込みは、４月に施設の引き渡しがあります関係で、ほぼ１年間のトータルコストというようなことで、もともと初年度ということで、２カ月分の収入が含まれていないというようなことと、それからこういった大規模な施設につきましては。","voiceIndex":318,"id":"exchange-139"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません。ただ、やっぱりビジネスとして成り立つような厳しさを持ってやっていただきたいということです。どちらかというと固めに見積もっているということなのですけれども、既に予約からかなり好調ということですので、これでもし初年度あるいは２年度以降に利益が出てくると、それはビジネスクラブと区とではどのような分け方になるかということは、どうお考えなのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"それからさらに２年、３年、好調に稼働が伸びれば、それを超える収入があるというようなことも目標としては持っていまして、超えた部分については、これから協定の中で定めていくことになりますが、１つの例ですけれども、区と団体のほうで半分ずつ折半して。","voiceIndex":320,"id":"exchange-140"},{"speaker":"あべ委員","kind":"質問","question":"実際にお話を伺ってみると、やはり、あそこはひとり暮らしのはずなのに、もう１週間ごみが出ていないのは何だろうというような気付きのようなものはいろいろあると聞いておりまして、そういったものを、例えば１つの書式に集約して、書かれたものを関連の部署が共有できるような仕組みをつくるとか、今のお仕事にあまり負担にならないような形で、何かシステマチックに情報共有できるようなことがあれば。","respondent":"小林品川区清掃事務所長","answer":"今ご提案がありましたのは、私どもハードの点検だけではなくて、場合によると住んでいる人、ソフトの点検も一緒にしてきたらどうだというご提案として受け止めまして、いろいろ課題はあるかと思いますが、検討はさせていただきたいと思います。","voiceIndex":322,"id":"exchange-141"},{"speaker":"あべ委員","kind":"意見","question":"貴重な財産だと思いますので、ぜひ活用をと考えています。今、清掃の職員の方は再任用の方も数が大分増えてきていると思います。高齢と言ってはまだ失礼なお年かもしれませんけれども、やはりうまくマッチングして、活用できるような仕組みをぜひご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":324,"id":"exchange-142"},{"speaker":"浅野委員","kind":"質問","question":"２６３ページ、胃がんリスク検診、同じく２６３ページの肝炎ウイルス検診、２７５ページの環境調査測定費、それと２８５ページの収集運搬作業費について質問します。続いて肝炎ウイルスについて質問します。区の予算としては今回は平成２７年度４,１００人分、例年、３,５００から４,０００人が受けています。これまでの区の取組みについて、区民への周知などについてお伺いします。","respondent":"川島健康課長","answer":"この事業は、肝炎ウイルス検査を受診した後の陽性者等を早期に治療につなげて重症化を予防するという目的で都が１０月から開始したものですが、４月にさかのぼりまして、陽性者を対象としてフォローアップに同意した方に対しまして。","voiceIndex":326,"id":"exchange-143"},{"speaker":"浅野委員","kind":"質問・要望","question":"細かい数字までありがとうございました。親からの口移しとか、子どもが幼少の頃に、胃酸の分泌がまだ十分でないときにピロリ菌に感染するということで、自治体によっては、中学生とか二十歳でピロリ菌検査を実施しておるわけですが、がん危険性の早期発見のために、またその次の世代に安全安心のためにも、区でもそのような時期にピロリ菌検診を要望しますが、いかがでしょうか。ご答弁を後でお願いします。","respondent":"川島健康課長、三ツ橋環境課長","answer":"それで、刻みをなくすということと、それから若い年代から実施ということにつきましては、一般質問のほうでもご答弁させていただいていることと同じになるのですが、品川区の年齢の考え方は、ピロリ菌の陽性率の高いところということで。航空機の騒音測定につきましてお答えいたします。昔、補償されていた部分ということだと思うのですけれども、そちらにつきましては、環境課で、かなり昔に補償はしていたと思われます。","voiceIndex":328,"id":"exchange-144"},{"speaker":"浅野委員","kind":"質問","question":"騒音の件ですけれども、国もこの騒音の調査をやっていると思います。区のほうでもスタートするということですけれども、どちらかというと、国の計測結果を区として検証するというのでしょうか。そのように考えるのですけれども、そのような考え方でいいのかどうか教えてください。","respondent":"三ツ橋環境課長","answer":"国の騒音結果を検証するというご質問ですけれども、実際に来年度以降、区が航空機騒音、今、静かな状況の部分を測定してまいりますけれども、国の値、また区の値、またそのほかに東京都でも実際に航空機の騒音につきましては測定しておりますので。","voiceIndex":331,"id":"exchange-145"},{"speaker":"浅野委員","kind":"質問","question":"２８５ページの収集運搬作業費ですけれども、最近、ワンルームマンションが多くなってきておりますけれども、ごみの出し方についてですが、かなり荒っぽいというのでしょうか、管理者もいないような中でばらばらに出されているということで、カラスがそれを広げていってしまうというようなこともあると思いますが、清掃事務所も苦慮していることかと思います。","respondent":"小林品川区清掃事務所長","answer":"この４月以降、正確な数字ではございませんが、２０件を上回る適正排出指導を行っているところです。これに関しましては、持ち主もしくは不動産管理者に対して適正な排出についての対応をするとともに、各戸に出し方のリーフレットの配布等で対応しています。","voiceIndex":333,"id":"exchange-146"},{"speaker":"須藤委員","kind":"質問","question":"２５９ページの衛生統計調査費のうち、国民健康・栄養調査というのがありますけれども、これでどういうことがわかるのでしょうか。教えてください。","respondent":"高山生活衛生課長","answer":"国民健康・栄養調査ですが、こちらのほうは、国庫委託金に基づきまして毎年実施している調査です。","voiceIndex":336,"id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"それで２６９ページで、食育推進事業、区民健康づくりプラン品川推進事業、それから２６９ページの不妊治療助成事業といったものに関連して、最初に不妊治療助成ですけれども、今、区内というか日本の国では、結婚されて何組、例えば１０組いればその１組ぐらいがこういう不妊治療が必要だというふうになるのかどうかが一つと、それから、先進国ではそういう状況があるけれども、開発途上国というか。","respondent":"川島健康課長","answer":"現在、夫婦１０組のうちの１組が不妊で悩んでいるというような状況にあると言われております。その時代性とか背景というのはなかなか難しいものではあるのですが、やはり晩婚化が進んでいるということは、当然、一つの要因としてあるのかと思います。","voiceIndex":338,"id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"むしろそういうところへ日本の人たちが行って人口増加防止というような形で教育をしたりということがあるのだけれども、そのあたりとの関係はどういうふうにお考えになっているのでしょうか。ですから、そのあたりも関係してくるのだろうと思うのだけれど、今言ったように、世界で見てどうなのだろう、先進国でこういう不妊というのがあるのだけれども、そのあたりはどういうふうにお考えかなと。","respondent":"太田品川保健センター所長","answer":"やはり妊婦の高齢化が進みますと妊娠する率というのは下がってまいります。アフリカ等は、やはり結婚も早いですし、若い方ですので、やはりたくさん妊娠されてたくさんお子さんをつくられる。","voiceIndex":340,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問","question":"食育推進事業と区民の健康づくりで、食育というのは非常に大切だと思うのですけれども、今の栄養とか、そういうのを見てきて、どういうことを食育推進事業というのはやっていかれようとされているのかと思うのですが。そういうこと自体が、栄養をとること、それから食事のあり方、そういうこともどういうふうに考えていらっしゃるのかというのを教えてください。","respondent":"川島健康課長","answer":"どのように区が取り組んでいくかということとは少し違う答弁になるかもしれないのですが、４月に発行しますしながわ健康プラン２１は、食育推進計画も兼ねることになっております。","voiceIndex":342,"id":"exchange-150"},{"speaker":"須藤委員","kind":"質問","question":"そういうことと、いろんなことを考えていかなくてはいけないだろうと思うのだけれど、国がこう発表したから、そのまま鵜呑みにしていいのだろうかということをちょっと思うのですけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"いろいろな新たな知見が出てきた場合は、国の言うことを鵜呑みにするのではなくて、品川区みずからも、その辺の確認は当然しなければならないなと思います。","voiceIndex":344,"id":"exchange-151"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今言われたように、食事自体も３食とることが本当に必要なのだろうか。逆に、今は１日１食という人がいて、そういう人が非常に元気で頑張っているよというのが、いっぱい、私の知っている有名人などもそういう生活をしているというようなことも聞くのだけれども、それで稽古してばりばりやっているというのがいるのだけれども、そういうこと自体考えてきてどうだろうと。","respondent":"川島健康課長","answer":"それから減塩です。それから野菜をたくさん食べるという、こういう一般的な話ですが、その辺の今までの流れを踏襲したものにはなるのですが、そういう食事の部分を啓発していくような予定になってあります。","voiceIndex":346,"id":"exchange-152"},{"speaker":"須藤委員","kind":"意見","question":"これはまたいろいろお話ししたいのだけれども、時間がないのだけど、やはり健康というものは、その人その人に合うようにそれぞれ考えていかなくてはいけない。そのこと自体が何だろうとやっぱり考えておかなくてはいけないと思う。がんを発症させる状況というのが今この時代にいろいろあるわけで、それを次に変えていくというような形がどうあるべきだというのをまた考えておいてください。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"私は２９７ページ、プレミアム付区内共通商品券について答えをお聞きします。これはもう一度聞きます。なぜならこれは２０％プレミアムが付く。本当に品川区としては特別の商品券を発行助成しますが、この原資は、前回もお話ししましたが、国の地域住民生活等の緊急支援のための交付金を使うとともに、プレミアム商品券の発行に全額使われます。お願いします。","respondent":"米田商業・観光課長","answer":"それで、その中のいろいろな国から来る情報の中では、いわゆる低所得者等に対象を限定するということではなく、広く区民全体に消費を喚起できるような、プレミアム付商品券のような事業を推奨するというようなことがあった関係で、区としても。","voiceIndex":350,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"要は文字どおり言えば、地域住民生活等の緊急支援ということですよね。そうすると、それに全額、消費喚起だけに使っていいものなのでしょうか。そうすると、あくまで一部の人だけ、一部の区民だけしか購入できないという、私はちょっとその支援策というのは違うのではないかと思うのですが、どうでしょう。","respondent":"米田商業・観光課長","answer":"その辺についても国のほうから来ておりまして、今、委員がおっしゃったような形というのは、プレミアム付共通商品券事業がどうしても域内でできないような場合が想定されるというようなことで、基本的には先ほど申し上げましたように。","voiceIndex":352,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"もう、あらかじめ買えない層の人がいるわけですよね。これは税金を使って、国民、都民、区民の皆さんにこの共通商品券を生活支援のために使ってください。これは２０％でしょう。２０％ということならば、やはり何かそこは対策を私は考えるべきではないかと思うのですが、もう一度だけお聞かせください。それでいいのですか。区のスタンスとして、これはこういう使い方が正しいのですか。お願いします。","respondent":"米田商業・観光課長","answer":"いろいろ情報をとっている中で、まずは区民の方が広く買えるような形での仕組みを構築して、それを区商連ともいろいろ話し合いながら、４月に向けて調整を進めていくというようなことで、そういった意味では、買えない人というよりは。","voiceIndex":354,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"スタンスはわかりました。ではちょっとここでお聞きしますが、現在の２０％プレミアムは、物価高や所得が増えない中の区民にとっては、私は有効な支援策の一つとは思っております。それは同じです。ですが、ではここで混雑が想定されますが、それに対して何か対応策はお考えなのですか。広く皆さんに買っていただくと、今お話がありましたよね。どうなのですか。","respondent":"米田商業・観光課長","answer":"混雑というのはおそらく、発売当日にたくさんの方が販売所に押しかけてというようなことのご趣旨だと思いますけれども、販売所を分散するとともに、量を多く確保していますので、その辺の混乱が生じないようなあらかじめのアナウンスと、それから各売り場における安全対策。","voiceIndex":356,"id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"これはあくまで税金を使っているということと、商品券というのは限りがありますよね。早くそこの販売所に行けば買えてしまう。できるだけ多くの区民が等しく購入できるチャンスをつくる、そういう制度をつくるということは、私は自治体として必要なことではないかと思うのです。ところが、結局、行ける人が、早く行った人が早く買えてしまう。そういうことでよろしいのですか。","respondent":"米田商業・観光課長","answer":"今回の商品券につきましては上限を１万円上げましたけれども、その１万円をもってしても、１万６,０００人の方が購入できるという計算ですので、不必要に早期に買いに走るというようなことなく購入できるというようなことも、あわせて周知していきたいと考えています。","voiceIndex":358,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"これだけの事業をやるならば、区はさまざまな施設を持っています。そこで購入希望者に対しては、予約して申し込み、予約申込み後に区で抽選会を行って、当選した人に購入権を与えるとか、そういうことをしない限りは、必ず一部の人になってしまいますよね。何で多くの人に平等のチャンスを与えないのか、私はこれは区の施策としておかしいのではないかと思うのですが、その辺どうお考えですか。","respondent":"米田商業・観光課長","answer":"重ねてになりますが、１万６,０００人の方が購入できるということでは、今までの規模よりも相当大きくなってありますので、それとあわせて国の交付金の趣旨が、早期に販売して、それから早期に地域での消費喚起というようなことですので、その辺の最善の策といたしましては。","voiceIndex":360,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"はっきり申し上げて、今まで２０％というのはやっていないですよね。殺到する云々はありますが、それは別としても、やはり皆さん１回予約して、それで１週間後でもいいです、抽選して、その方たち、当たった人にお配りする。そういう平等なチャンスをつくるのは、私は、自治体としての使命ではないですか。早く行った人が早く買えるよというやり方は考えてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-160"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区は平成２５・２６年度、若者就業体験事業を行ってきましたが、まずこちらを聞きたいと思いますが、あなたの働きたいを応援しますということで、私は大変いい事業であったなと思うのですが、まずどのような成果を上げているのか、ちょっと実績を教えていただきたいのと、今度の新しい若者・女性就業支援事業に変わっていくと思うのですが、私はこの前の事業の年１回を２回に増やしてほしいし。","respondent":"山崎ものづくり・経営支援課長","answer":"いずれにしましても、こういった経済状況などを踏まえて、雇用対策については総合的に対応してまいるというような考えのもとに構築させていただいているものです。","voiceIndex":364,"id":"exchange-161"},{"speaker":"飯沼委員","kind":"質問","question":"総合的ということと、あと女性のところに力が入っていくのはいいと思うのですが、若者のところで、ちょっとプレス発表を見まして質問したいと思います。今までは中小企業の正規に就職をするということですが、ここの違いはなぜなのか。ここがどうして変わっていったのかというのと、若者が２０人なのです。これが、応募がたくさんあったら枠で受け止めてくれるのかどうかお伺いします。","respondent":"山崎ものづくり・経営支援課長","answer":"ですから、申込みして説明会などを行うときには、広く来ていただいて、やりとりをする方というのは、やはりもっと多いかとは思っております。","voiceIndex":366,"id":"exchange-162"},{"speaker":"飯沼委員","kind":"質問・要望","question":"しっかり生活をしながら新しい生活再建ができるという、そこの説明が全然なかったので、幾らの助成が出るのか、そこを具体的にもう一回教えていただきたいのと、２０人以上参加されたとき、受け止めてくれるのか、くれないのか、もう一回そこのところをはっきりお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"それで企業を見学して実習に行くまでに至らない方も何人かはやはりいらっしゃいます。このスキームではちょっと参加できないなというようなことでもって、最終的な到達が今申し上げている枠だです。","voiceIndex":368,"id":"exchange-163"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。２０人の枠はちょっと広げていただけるようなのですが、助成金のところが、期間がどのくらいで幾ら出るのかというのは、生活をしていく上でとても大事なことなのでお答えいただきたいと思います。労働相談の窓口の強化と周知。もう一つはブラック企業を許さない、区民を守る立場をぜひ企業と区民にアピールしていただきたいのですが、いかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"実習の期間につきましては、さまざま１カ月、２カ月、あるいは多様な就労に対応するためにもっと短期というようなことも含めて、いろいろバリエーションを組んでおります。８時間で６,０００円というようなことを考えております。","voiceIndex":370,"id":"exchange-164"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは２７５ページ、カラス・外来種対策事業、２８９ページ、伝統的産業の振興について。これは、２９１ページの若者・女性就業支援事業にも絡めての質問です。ハクビシン等が町にあらわれたときに、それを見つけた区民の方の一番ベストな対応というのは何なのか、区のお考えを教えてください。伝統的産業の振興について、現在、品川区内にいわゆる職人という方たちがどれほどいらっしゃるのでしょうか。","respondent":"三ツ橋環境課長、米田商業・観光課長","answer":"区民の方がハクビシンを見つけたときは、区の環境課にお電話をいただいて、実際に見つけた場合と、また被害がある場合、また大分そちらは変わってまいりますので、それの対応をしてまいりたいと考えています。伝統的産業の振興に関するご質問ですが、いわゆる品川区伝統工芸保存会の会員としては、２５名の方が会員になっているという状況です。","voiceIndex":373,"id":"exchange-165"},{"speaker":"石田（し）委員","kind":"確認","question":"外来種の対策なのですけれど、ある方から僕のところに電話がかかってきて、タヌキが出たのだけど、どうすればいいんだというお電話をいただいて、それは保健所だったり区のほうにご連絡してくださいというふうに僕は言ったのですけれど、よくよく考えると、いや、それが本当に正しかったのかというのもちょっと不安だったので、改めて確認させていただきました。わかりました。お知らせください。","respondent":"米田商業・観光課長","answer":"は実際に、弟子を育てるというようなことを行っている方もいらっしゃいますけれども、なかなか伝統的産業を今後志していこうという若い方が、正直なかなか門をたたくというようなことが少ない状況かと把握しています。","voiceIndex":376,"id":"exchange-166"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"品川産業支援交流施設について、もう何人かの方からもお問い合わせがありましたが、ちょっと１つ、３Ｄプリンタについてお伺いします。それと今回のこの施設は、たしか当初、創業支援センターに現在入っている方たちの次のステップにもご利用していただきたいというような話があったと思うのですが、現在、その辺の方たちが申込み等をされているのか、もし伝えられる範囲で構いませんので、お願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"それから第二成長の受け皿としましては、今オフィスのほうを１６室予定しておりますけれど、１０社内定しているうちの４社が、既存の西大井ですとかの創業支援センターからの第二成長の受け皿として内定しております。","voiceIndex":378,"id":"exchange-167"},{"speaker":"石田（し）委員","kind":"質問","question":"壊れやすいということ。オフィスの利用時間ですが、２４時間利用できるということで、本当によかったなと思うのですけれど、これは例えばＷｉ‐Ｆｉなども管理をされると思うのですが、その点も２４時間利用が可能なのかどうか、あわせて教えてください。今後もぜひ、創業支援センターと連携して、１つでも多くの企業が巣立っていければと思いますので、引き続きの連携をよろしくお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"いわゆる情報機器の通信環境のＷｉ‐Ｆｉも、当然２４時間、電波を飛ばすというようなことで考えております。","voiceIndex":380,"id":"exchange-168"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから今回、医師会のほうからも要望が出ていたと思うのですけれど、５年たった後の再接種についても、今回、一定の基準の中で設けられておりますけれども、これも昨年の補正の審議のときにお伺いしたときに、国のほうでは５年間かけて、いろいろ部会のほうで再接種について審議した上で、それを踏まえて検討するということだったのですけれど、随分早くこういう形でやっていただいて。","respondent":"佐藤保健予防課長","answer":"４月からこれを任意予防接種で開始しましたときにも、インフルエンザですとか、そういったものと違って、一気にあるシーズン、特定のシーズンに固まって打つというようなタイプの予防接種ではないのかと考えています。","voiceIndex":383,"id":"exchange-169"},{"speaker":"たけうち委員","kind":"質問","question":"それで、実は私は、クリーニング店をどうしても事情があって廃業される方からご相談をいただいて、要はクリーニングでもドライクリーニングをやられている方などは、テトラクロロエチレンとかトリクロロエチレンですか、こういうのを使っていることで、いわゆる土壌汚染が非常に心配だということで、調査費用はそんなにかからないのですけれども、調査して土壌汚染という結果が出たときに。","respondent":"三ツ橋環境課長","answer":"そちらのご相談に関しましては、環境課指導調査係でご相談を受けております。実際にクリーニング店を廃業する場合には、都の環境確保条例第１１６条に基づいてご相談を受けております。","voiceIndex":388,"id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問","question":"だから、そういう面では、これは東京都も含めて、品川区もそうなのですけど、品川区単独でどうしろというのではないのですけれども、やはり今後のことを考えると、これは何かしら、助成なのか融資なのか、考えなくては、そのままほったらかしで逃げられてしまいますので。そうすると、本当に土壌汚染でかなり近隣の人たちも困ってしまうということになるのですけれど、その辺はどのようにお考えですか。","respondent":"三ツ橋環境課長","answer":"今現在のところ、委員がおっしゃられたように、お金、融資の部分に関しては特にございませんけれども、また引き続き、これから東京都や国に対してどのように考えていくか、また一緒に検討していきたいと考えています。","voiceIndex":390,"id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これも当時、アスベストというのは危険だというのがなくて、非常に便利な材料だということで、そういう形になってきたわけですけれども、そういう面で言えば、この溶剤も当時はその害があまりないと言われている中で使ってくるということなので、これはぜひ、アスベストとまた違うかもしれませんけれど、でも考え方としては同じなので、ぜひ東京都もしくは東京都を通して国でもそうですけれども。","respondent":"三ツ橋環境課長","answer":"実際に土壌汚染に関する支援策などにつきましては、東京都と２３区が一緒になってやっております。対応を考えてまいります。","voiceIndex":392,"id":"exchange-172"},{"speaker":"伊藤委員","kind":"質問","question":"なので、今、騒音対策については方向性はわかるのだけれども、年度を区切って、つまりある年までは現状把握をして、それから実際に飛行機を多分飛ばすでしょうから、飛ばしたらどうなるかということを測定して、それで問題点を抽出して、それで国土交通省と協議しながら問題点を具体的に解決する方策を考えていく。どうぞお願いいたします。","respondent":"三ツ橋環境課長","answer":"実際に、具体的には国からの区民に対する丁寧な説明というものをまずはしていってもらいたいということを要望しておりますけれども、今後につきまして、来年度は航空機騒音のまずは調査測定というものを実施してまいりますけれども。","voiceIndex":395,"id":"exchange-173"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは非常に大きな問題なのです。なので、今これから検討するとおっしゃったけれども、もう一声いただきたいのは、やっぱり２０２０年までにこうしていくとか、品川区としてもはっきりとした方向性を持っていかないと、この問題の解決はなかなか見えてこないと思うのですが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"は品川区としての考えですけれども、実際には東京都および関連区市、近隣区の関係と、一緒に協力しながら考えてまいりたいと考えています。","voiceIndex":397,"id":"exchange-174"},{"speaker":"伊藤委員","kind":"質問","question":"そうですね。それからプレミアム付共通商品券。先ほど渡部委員からお話をさせていただきましたけれども、一旦２０％を出すと、その後が大変だと思うのです。だけどその一方で、地方に考えてくれと金が来ているわけだから、やっぱり品川区としてそれを捉まえた上で、新たな形の経済支援策なりを創出していくということが必要だと思うのですが、これは企画財政課のほうですか、答弁をお願いいたします。","respondent":"柏原行財政改革担当課長","answer":"そのプランの中で、地方の再生というところが大きなテーマになってありますので、そのプランをつくることによって、どういう形で効果が生み出せるかというところも検討しながら、メニューとしては今すぐ云々とはなかなか言いづらい部分がありますけれども。","voiceIndex":399,"id":"exchange-175"},{"speaker":"伊藤委員","kind":"質問","question":"プレミアム付共通商品券は、これはこれで価値があるものと、私たちも進めてきたのだから思っています。だけれども、これを毎年やっていくとなると、結構なお金がかかってくるわけじゃないですか。","respondent":"柏原行財政改革担当課長","answer":"そういったいろいろな、さまざまな環境、それから先を見る中で、どういった形が品川区の今後、未来の発展につながっていくのかというのを考えながら進めていきたいと思ってあります。","voiceIndex":401,"id":"exchange-176"},{"speaker":"伊藤委員","kind":"質問","question":"この事業自体はすばらしいと思うのだけれども、単年度でいいのでしょうか。それで環境啓発をするためには、もっとさまざまな方法を具体化していって、ミュージカルを否定するわけではないのだけれども、これはできれば単年度で終わったほうがいいのではないでしょうか。むしろ具体的に効果のある、多くの区民の方々にご理解していただくような政策を展開していくべきだと思うのですが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"しかしながら、果たしてこれを継続というものがいいのかどうかは、環境活動推進会議の中でも考えてまいりますけれども、実際に１回公演をした場合には、また次の段階というものを考えていかなければならないと考えていますので、今のところ。","voiceIndex":403,"id":"exchange-177"},{"speaker":"伊藤委員","kind":"意見","question":"五反田宇宙ミュージアムにつながるようなイメージがあるのです。だけれども、やった後の事業をどういうふうに評価していって、目的を遂げて達成されたかということとか、それから同じ税金を投入するのであれば、もっと効果的なことはないかということを検証する仕組みが必要ではないかと思うのですが、最後に答弁をお願いいたします。","respondent":"三ツ橋環境課長","answer":"委員がおっしゃいますように、実際に環境啓発ミュージカルだけではなく、さまざまな環境への取組みというものを考えていかなければならないものだと思っています。特に環境啓発ミュージカルに関しましては、しっかり評価して、また検証しながら考えてまいりたいと思います。","voiceIndex":405,"id":"exchange-178"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":122170,"voices":407}}]);
